    // Update 28: the forms and gates the 27.4 runs showed missing (BUILD-SM2.md section 38).
    test("Update 28: ADDRESS FINDER finds camera-relative view, view*proj (rows, columns) and its inverse", [] {
        using namespace address_finder;
        const Camera cam = finderCamera(.3f, 12.f, .001f, -.002f);
        const float sx = projSx(cam), sy = projSy(cam);
        const float* r0 = &cam.pose.m[0];
        const float* r1 = &cam.pose.m[4];
        const float* r2 = &cam.pose.m[8];
        const auto has = [](const std::vector<Match>& hits, MatchKind kind, int form = -1) {
            for (const auto& h : hits)
                if (h.kind == kind && !h.nearMiss && (form < 0 || h.form == form))
                    return true;
            return false;
        };
        float buf[48]{};
        for (int r = 0; r < 3; ++r) // R^T, translation dropped
            for (int c = 0; c < 3; ++c)
                buf[r * 4 + c] = cam.view.m[r * 4 + c];
        buf[15] = 1;
        check(has(matchBuffer(buf, 48, cam), MatchKind::viewRotation), "camera-relative view not found");
        float vp[48]{};
        for (int k = 0; k < 3; ++k) {
            vp[k] = sx * r0[k] + .1f * r2[k];
            vp[4 + k] = sy * r1[k] - .05f * r2[k];
            vp[8 + k] = r2[k];
        }
        vp[15] = 1;
        check(has(matchBuffer(vp, 48, cam), MatchKind::viewProj, 0), "view*proj rows not found");
        float vpc[48]{};
        for (int r = 0; r < 4; ++r)
            for (int c = 0; c < 4; ++c)
                vpc[c * 4 + r] = vp[r * 4 + c];
        check(has(matchBuffer(vpc, 48, cam), MatchKind::viewProj, 1), "view*proj columns not found");
        float inv[48]{};
        for (int k = 0; k < 3; ++k) {
            inv[k] = r0[k] / sx;
            inv[4 + k] = r1[k] / sy;
            inv[8 + k] = r2[k];
        }
        inv[15] = 1;
        check(has(matchBuffer(inv, 48, cam), MatchKind::invViewProj, 0), "inverse view*proj not found");
        float noise[48]{};
        for (int k = 0; k < 3; ++k) {
            noise[k] = sx * r1[k]; // the wrong axis
            noise[4 + k] = sy * r0[k];
        }
        check(!has(matchBuffer(noise, 48, cam), MatchKind::viewProj), "swapped axes matched view*proj");
    });
    test("Update 28: ADDRESS FINDER jitter is relative, scaled / flipped forms match, 25% noise does not", [] {
        using namespace address_finder;
        // The 27.4 run's frozen camera jitter (multiples of 1/7680).
        const Camera cam = finderCamera(.3f, 12.f, .00039063f, 6.8083e-05f);
        const auto jitterHits = [&](float x, float y, bool nearMisses) {
            float buf[48]{};
            buf[30] = x;
            buf[31] = y;
            std::vector<Match> out;
            for (const auto& h : matchBuffer(buf, 48, cam, 64, nearMisses))
                if (h.kind == MatchKind::jitter || h.kind == MatchKind::jitterScaled)
                    out.push_back(h);
            return out;
        };
        auto h = jitterHits(cam.jitterX, cam.jitterY, false);
        check(h.size() == 1 && h[0].kind == MatchKind::jitter && h[0].offset == 120, "as-is jitter");
        h = jitterHits(2 * cam.jitterX, -2 * cam.jitterY, false);
        check(h.size() == 1 && h[0].kind == MatchKind::jitterScaled &&
                  std::string(jitterFormName(h[0].form)) == "x2_flip_y", "x2 flipped jitter");
        check(jitterHits(1.25f * cam.jitterX, 1.25f * cam.jitterY, true).empty(), "25% noise matched");
        check(std::abs(1.25f * cam.jitterX - cam.jitterX) < jitterTol, "the old absolute gate let it in");
        h = jitterHits(1.06f * cam.jitterX, cam.jitterY, false);
        check(h.empty(), "6% off matched as jitter");
        h = jitterHits(1.06f * cam.jitterX, cam.jitterY, true);
        check(h.size() == 1 && h[0].nearMiss, "6% off is not a near miss");
        check(relativeError(1.f, 1.f) == 0 && relativeError(0.f, 0.f) == 0, "relative error");
    });
    test("Update 28: ADDRESS FINDER store keeps room for values, one row per site, stable and almost", [] {
        using namespace address_finder;
        check(rawHitAdmit(0, false) && !rawHitAdmit(maxRawHits * 3 / 4, false), "non-value hits not held back");
        check(rawHitAdmit(maxRawHits * 3 / 4, true) && !rawHitAdmit(maxRawHits, true), "value hits room");
        RawHitSummary rows[4] = {{true, false, 1, 1}, {false, true, 1, 1}, {false, false, 1, 1}, {false, true, 3, 3}};
        check(evictIndex(rows, 4) == 2, "evicts the non-value one-hit row first");
        rows[2].hits = 2;
        check(evictIndex(rows, 4) == 1, "then a one-frame value row");
        rows[1].distinctFrames = 2;
        check(evictIndex(rows, 4) == -1, "evicted a confirmed or repeated row");
        check(sameSite(0x2cc6000, 0x2cc66fe, 0, 0x2cc66fe), "a live hit after the worker filled the function");
        check(sameSite(0, 0, 0, 0), "site-less rows");
        check(!sameSite(0, 0x2cc66fe, 0, 0x2cc6b84) && !sameSite(0, 0, 0, 0x2cc6b84), "different calls merged");
        StableState st{};
        check(!noteStableSample(st, 1, 0x1b24) && !noteStableSample(st, 1, 0x1b24), "one frame counted twice");
        check(!noteStableSample(st, 5, 0x1b28) && st.scans == 1, "a new offset did not restart");
        bool ok = false;
        for (uint64_t f = 6; f < 6 + confirmFramesK; ++f)
            ok = noteStableSample(st, f, 0x1b28);
        check(ok, "a stable value never confirmed");
        check(isAlmost(false, true, 2, false) && isAlmost(false, false, 1, true), "almost");
        check(!isAlmost(true, true, 5, true) && !isAlmost(false, true, 1, false), "not almost");
        JitterTrack frozen{};
        for (int i = 0; i < 6; ++i)
            noteJitterHit(frozen, 0x2e00, .00039063f, 6.8083e-05f);
        check(frozen.hits == 6 && frozen.changes == 0 && !jitterTrackConfirmed(frozen), "a frozen jitter confirmed");
        JitterTrack moving{};
        for (int i = 0; i < static_cast<int>(confirmFramesK); ++i)
            noteJitterHit(moving, 0x2e00, (i + 1) / 7680.f, -(i % 3) / 4320.f);
        check(jitterTrackConfirmed(moving), "a changing jitter did not confirm");
    });
    test("Update 29: ADDRESS FINDER says which camera a hit was built from", [] {
        using namespace address_finder;
        Camera cams[cameraSlots]{};
        cams[0] = finderCamera(.3f, 12.f, .001f, -.002f);
        cams[1] = cams[0]; // a still camera: flat-1 is the same picture
        cams[2] = finderCamera(.31f, 12.5f, .003f, -.001f);
        cams[headSlot] = finderCamera(.9f, 20.f, .004f, .002f);
        cams[eyeSlot0] = finderCamera(.95f, 19.97f, -.003f, .001f);
        cams[eyeSlot0 + 1] = finderCamera(.95f, 20.03f, .0035f, -.0035f);
        check(sameCamera(cams[0], cams[1]) && !sameCamera(cams[0], cams[2]), "sameCamera wrong");
        const auto poseOf = [](const std::vector<CameraHit>& hits) -> const CameraHit* {
            for (const auto& h : hits)
                if (h.match.kind == MatchKind::pose && h.match.offset == 0)
                    return &h;
            return nullptr;
        };
        float buf[48];
        finderBuffer(cams[0], buf);
        const auto flat = matchCameras(buf, 48, cams);
        const CameraHit* p = poseOf(flat);
        check(p != nullptr, "flat pose not found");
        check(p && p->mask == 3u && p->match.lag == 0, "a still camera must say flat+flat-1, lag 0");
        check(p && cameraMaskText(p->mask) == "flat+flat-1", "mask text wrong");
        check(p && std::string(cameraTag(p->mask, 8.f)) == "FLAT-ONLY", "flat-only not tagged");
        check(p && std::string(cameraTag(p->mask, .1f)).empty(), "flat and head close: no tag");
        finderBuffer(cams[2], buf);
        const CameraHit* old = poseOf(matchCameras(buf, 48, cams));
        check(old && old->mask == 4u && old->match.lag == 2, "flat-2 lag wrong");
        finderBuffer(cams[eyeSlot0], buf);
        const CameraHit* e = poseOf(matchCameras(buf, 48, cams));
        check(e && (e->mask & (1u << eyeSlot0)) && !(e->mask & flatSlotsMask), "eye pose not attributed");
        check(e && std::string(cameraTag(e->mask, 8.f)) == "EYE-ONLY", "eye-only not tagged");
        check(std::string(cameraTag(1u << headSlot, 8.f)) == "HEAD-ONLY", "head-only not tagged");
        check(std::string(cameraTag((1u << headSlot) | 1u, 8.f)).empty(), "mixed tagged");
        check(cameraMaskText(0) == "none" && std::string(cameraSlotName(cameraSlots)) == "?", "names wrong");
    });
