    test("Update 32.1: a graphics setting's new eye images are taken over or pause the eyes", [] {
        namespace es = eye_swap;
        const es::Desc eye{3, 1440, 1620, 1, 1, 28, 1, 0x1};
        check(es::compatible(eye, eye), "the same eye image must be compatible");
        auto d = eye;
        d.width = 1920;
        check(!es::compatible(eye, d), "a new width must not be taken over");
        d = eye;
        d.format = 24;
        check(!es::compatible(eye, d), "a new format must not be taken over");
        d = eye;
        d.flags |= 0x8;
        check(!es::compatible(eye, d), "a new deny-shader-resource flag must not be taken over");
        d = eye;
        d.sampleCount = 4;
        check(!es::compatible(eye, d), "multisampling must not be taken over");
        d = eye;
        d.flags = 0x4;
        check(es::compatible(eye, d), "an unrelated flag must not pause the eyes");
        check(es::releasable(10, 10) && es::releasable(10, 11), "finished work must free the old image");
        check(!es::releasable(10, 9), "the old image freed while the GPU may still read it");
        check(!es::releasable(10, UINT64_MAX), "a removed device's fence must not free the old image");
        check(es::lostCode == 3503, "pause code drifted");
        for (const char* line : es::lostLines)
            check(std::string(line).size() <= 80, "notice line too long");
        for (const float aspect : {16.f / 9, 1.f, 3.f}) {
            std::vector<Vertex> notice, backing;
            es::appendLostNotice(notice, aspect);
            es::appendLostBacking(backing, aspect);
            check(!notice.empty() && notice.size() % 3 == 0 && backing.size() == 6, "notice has no triangles");
            const auto p = es::noticeProjection(aspect);
            bool inside = true;
            for (const auto& v : notice) {
                const float x = v.position.x * p[0], y = v.position.y * p[5];
                inside = inside && std::fabs(x) <= .95f && std::fabs(y) <= .95f && v.position.z > 0 &&
                         v.position.z < 1;
            }
            check(inside, "the notice leaves the game screen's image");
        }
        check(std::string(es::lostMessage).find("3503") != std::string::npos, "lost message lacks its code");
    });
