    test("Update 30: ADDRESS FINDER bind trace finds the pass camera data feeds", [] {
        using namespace address_finder;
        Watched w[maxWatched]{};
        size_t n = 0;
        const uint32_t head = 1u << headSlot, eye = 1u << eyeSlot0;
        // A seed page (Update 29) and a live head view*proj at page+0x80.
        w[n].va = 0x11e0190000ull;
        w[n++].seed = true;
        check(noteWatched(w, n, maxWatched, 0x11e0190080ull, head, "HEAD-ONLY", MatchKind::viewProj, 10) == 1,
              "live value not stored");
        check(noteWatched(w, n, maxWatched, 0x11e0190080ull, eye, "EYE-ONLY", MatchKind::viewProj, 11) == 1 &&
                  n == 2 && w[1].camMask == eye,
              "same address must refresh, not add");
        // A CBV at the page start covers +0x80 (64 KiB window); one past it does not.
        check(findWatched(w, n, 0x11e0190000ull, 12) == 1, "bind covering live value missed");
        check(findWatched(w, n, 0x11e0190100ull, 12) == 0, "bind past the value must fall to the seed");
        check(findWatched(w, n, 0x11e0180000ull, 12) == -1, "bind before the window matched");
        check(findWatched(w, n, 0x11e0190000ull, 11 + watchExpiryFrames + 1) == 0, "stale live value not expired");
        check(findWatched(w, n, 0, 12) == -1, "null VA matched");
        // Full table: the oldest live entry goes, seeds stay.
        Watched full[3]{};
        size_t fn = 0;
        full[fn].va = 1;
        full[fn++].seed = true;
        noteWatched(full, fn, 3, 100, head, "", MatchKind::position, 5);
        noteWatched(full, fn, 3, 200, head, "", MatchKind::position, 6);
        check(noteWatched(full, fn, 3, 300, eye, "", MatchKind::position, 7) == 1 && full[0].seed &&
                  full[1].va == 300 && full[2].va == 200,
              "full watch table replaced the wrong entry");
        // Pass kinds.
        int listA = 0, listB = 0;
        PassTarget t{};
        check(passKindFor(t, false, &listA) == PassKind::unknown, "no targets must be unknown");
        check(passKindFor(t, true, &listA) == PassKind::compute, "compute bind not compute");
        t.list = &listA;
        t.known = true;
        t.hasDsv = true;
        check(passKindFor(t, false, &listA) == PassKind::depthOnly, "0 RT + DSV must be depth-only");
        check(passKindFor(t, false, &listB) == PassKind::unknown, "another list's targets used");
        t.rtCount = 2;
        check(passKindFor(t, false, &listA) == PassKind::color, "colour pass wrong");
        check(std::string(passKindName(PassKind::depthOnly)) == "depth_only" &&
                  std::string(bindApiName(1)) == "compute_cbv" && std::string(bindApiName(9)) == "?",
              "names wrong");
        // Reserved bind store: dedupe, frames, shadow candidates win room at the cap.
        BindRow rows[2]{};
        size_t rn = 0;
        BindRow color{};
        color.rva = 0x100;
        color.pass = PassKind::color;
        color.camMask = head;
        BindRow shadow{};
        shadow.rva = 0x200;
        shadow.pass = PassKind::depthOnly;
        shadow.camMask = head;
        shadow.vpW = shadow.vpH = 2048;
        check(noteBind(rows, rn, 2, color, 1) && noteBind(rows, rn, 2, color, 1) && noteBind(rows, rn, 2, color, 2),
              "color bind not stored");
        check(rn == 1 && rows[0].hits == 3 && rows[0].frames == 2, "dedupe / frame count wrong");
        BindRow other = color;
        other.rva = 0x300;
        check(noteBind(rows, rn, 2, other, 3) && rn == 2, "second row not stored");
        check(!noteBind(rows, rn, 2, BindRow{color.rva + 9}, 3), "a non-shadow row passed the cap");
        check(noteBind(rows, rn, 2, shadow, 3) && rows[1].rva == 0x200, "shadow row did not take a one-hit slot");
        check(shadowPassCount(rows, rn) == 1 && shadowPassCandidate(rows[1]), "shadow count wrong");
        BindRow seeded = shadow;
        seeded.seed = true;
        check(!shadowPassCandidate(seeded), "a seed29 row counted as a shadow candidate");
        BindRow noCam = shadow;
        noCam.camMask = 0;
        check(!shadowPassCandidate(noCam), "a row with no camera counted");
        check(!watchKind(MatchKind::jitter) && watchKind(MatchKind::viewProj), "watch kinds wrong");
    });
    test("Update 28.1: EYE LOD reads first, judges by range and steadiness, never an exact match", [] {
        using K = native_view::EyeLodStep;
        // The Oct 23 2026 session: a Quest 3 eye lens about 94 degrees across.
        native_view::Descriptor eye{};
        eye.values[0x410 / 4] = 1.6406f;
        eye.values[0x41c / 4] = .925f;
        const float own = native_view::distanceScale(eye);
        near(own, .629f, .002f);
        // Update 28 required +1b24 == own; the finder's 0.4667 was the 110-degree active view's.
        native_view::Descriptor active = eye;
        active.values[0x410 / 4] = 1.9314f;
        near(native_view::distanceScale(active), .4667f);
        check(std::fabs(native_view::distanceScale(active) - own) > 1e-3f * own, "28's exact match would pass");
        // A value other than the eye lens's own (0.4667) is accepted by range once steady.
        native_view::EyeLodTrack t;
        K s{};
        for (unsigned i = 1; i < native_view::eyeLodSettleFrames; ++i) {
            s = native_view::eyeLodStep(t, .4667f, eye, 0);
            check(s.kind == K::settling, "wrote before the value held still");
        }
        s = native_view::eyeLodStep(t, .4667f, eye, 0);
        check(s.kind == K::write, "a steady in-range value was not raised");
        near(s.value, .4667f / own);
        near(t.base, .4667f);
        t.ours = s.value;
        check(native_view::eyeLodStep(t, s.value, eye, 0).kind == K::held, "our value not held");
        // The engine writing its own value back every frame: still raised, no compounding.
        auto again = native_view::eyeLodStep(t, .4667f, eye, 0);
        check(again.kind == K::write, "the engine's rewrite was not raised again");
        near(again.value, s.value);
        // The flat game's camera scale, when further, wins; at most 3x, never lower.
        near(native_view::eyeLodTarget(.4f, eye, 1.1f), 1.1f);
        near(native_view::eyeLodTarget(.3f, eye, 2.f), .9f);
        native_view::Descriptor narrow = eye; // a lens already past 68 degrees' distances: eyeDetail 1
        narrow.values[0x410 / 4] = 1.f;
        near(native_view::eyeLodTarget(1.5f, narrow, .5f), 1.5f);
        near(native_view::eyeLodTarget(1.5f, eye, .5f), 1.5f / own);
        check(native_view::eyeLodTarget(3.9f, eye, 0) <= native_view::eyeLodHighest, "above the range");
        // Out of range (0, NaN, huge) for 120 frames fails; one sane frame resets it.
        native_view::EyeLodTrack z;
        for (unsigned i = 0; i < native_view::eyeLodBadFrames; ++i)
            check(native_view::eyeLodStep(z, 0, eye, 0).kind == K::settling, "failed early");
        check(native_view::eyeLodStep(z, std::numeric_limits<float>::quiet_NaN(), eye, 0).kind == K::outOfRange,
              "NaN forever did not fail");
        native_view::EyeLodTrack h;
        for (unsigned i = 0; i < native_view::eyeLodBadFrames; ++i)
            native_view::eyeLodStep(h, 1e6f, eye, 0);
        native_view::eyeLodStep(h, .5f, eye, 0);
        check(h.bad == 0, "a sane frame did not reset the out-of-range count");
        // A value that changes every frame is never written and fails after ~10 s.
        native_view::EyeLodTrack m;
        K last{};
        for (unsigned i = 0; i <= native_view::eyeLodUnsteadyFrames; ++i) {
            last = native_view::eyeLodStep(m, .3f + .001f * static_cast<float>(i % 7), eye, 0);
            check(last.kind != K::write, "an unsteady value was written");
        }
        check(last.kind == K::unsteady, "an unsteady value did not fail");
        check(native_view::sm2DistanceScaleOffset == 0x1b24, "offset drifted");
        check(sizeof(native_view::EyeLodData) == 88 && native_view::EyeLodData{}.magic == 0x444f4c45, "protocol");
        for (uint32_t r = 1; r < native_view::eyeLodReasons; ++r) {
            const std::string text = native_view::eyeLodReasonText(r);
            check(!text.empty() && text.size() <= 40, "reason text " + std::to_string(r));
        }
    });
    test("Update 24: the session FPS: warm-up ignored, whole seconds, idle and stalls skipped, RESET", [] {
        using namespace wrist_hud;
        FpsSession s;
        check(std::isnan(s.high()) && std::isnan(s.low()) && std::isnan(s.average()), "numbers before any frame");
        check(fpsTenths(s.low()) == 0 && fpsTenths(45.2f) == 452 && fpsTenths(1e30f) == 2047 && fpsTenths(.01f) == 1, "tenths");
        double t = 100;
        auto run = [&](double seconds, double fps) { // new pairs at fps, the XR loop at 90 Hz
            const double end = t + seconds;
            double nextPair = t;
            for (; t < end; t += 1. / 90) {
                const bool pair = fps > 0 && t >= nextPair;
                if (pair)
                    nextPair += 1. / fps;
                s.frame(t, pair);
            }
        };
        run(9.5, 5); // the load: 5 a second, inside the warm-up
        check(std::isnan(s.low()) && s.warmingUp(), "the warm-up counted");
        run(10.5, 40);
        check(s.windows() >= 9 && std::abs(s.low() - 40) < 2.5f && std::abs(s.average() - 40) < 1, "40 a second");
        run(3, 0); // paused: no new pairs, no windows
        check(std::abs(s.low() - 40) < 2.5f, "a paused second counted as LOW");
        run(3, 60);
        check(std::abs(s.high() - 60) < 2.5f && std::abs(s.low() - 40) < 2.5f, "HIGH");
        const double before = s.trackedSeconds();
        s.frame(t + 5, true); // a 5 s stall (a load): the window under way is dropped
        t += 5;
        check(s.trackedSeconds() == before, "a stall counted");
        s.reset();
        run(2.2, 30);
        check(s.windows() >= 1 && std::abs(s.high() - 30) < 2.5f && std::abs(s.low() - 30) < 2.5f, "RESET kept the old");
        s.frame(t - 50, true); // the clock back: nothing breaks
        check(std::isfinite(s.average()), "the clock going back broke it");
        // Its row on the GRAPHICS page (Update 39.0.2): RESET answers there and only there, not a setting.
        check(controlSpot(graphicsPage, Control::fpsReset).found, "no RESET on GRAPHICS");
        for (int page = 0; page < pages; ++page)
            check(page == graphicsPage || !controlSpot(page, Control::fpsReset).found, "RESET on another page");
        check(std::string(helpText(Control::fpsReset)).size() <= 80, "the RESET sentence is too long");
        Applier a;
        a.start(Settings{});
        a.want(Control::fpsReset, 1);
        check(a.due(0, Control::none) == 0, "RESET was due as a setting");
        // Pressed: Result::fpsReset, nothing changed.
        Menu m;
        Settings set;
        m.setPage(graphicsPage);
        auto step = [&](float u, float v, float trigger) {
            Menu::Input in;
            in.active = true;
            in.pointer.hit = true;
            in.pointer.u = u;
            in.pointer.v = v;
            in.trigger = trigger;
            return m.update(in, set);
        };
        const Spot spot = controlSpot(graphicsPage, Control::fpsReset);
        step(spot.u, spot.v, 0);
        step(spot.u, spot.v, .3f);
        const auto r = step(spot.u, spot.v, .8f);
        check(r.fpsReset && r.changed == 0 && !r.recalibrate, "RESET's press did nothing or changed a setting");
    });
