    test("Update 38 WALL TILT: a death or a respawn levels the view at once; OFF leaves it", [] {
        const Vec3 feet{10,20,30},n{1,0,0};
        const SurfaceHold crawl{n,feet,3,true};
        for (uint32_t mode : {0u, 1u}) {
            GameTrackingRig rig;auto f=trackedFrame();
            rig.wallTilt(mode);
            holdFor(rig,f,feet,{},.2f);
            auto out=holdFor(rig,f,feet,crawl,.6f,n);
            check(out.standing,"the crawl did not turn the view");near(out.viewTilt,1.5707963f,.001f);
            // Off the wall a frame later: SAFE levels it at once on the death; OFF eases back.
            rig.diedOrRespawned();
            out=holdFor(rig,f,feet,{},.012f);
            if (mode == 0) {
                near(out.viewTilt,0,.01f);
                check(rig.tiltGuard().resets==1,"the death was not counted");
                near(length(out.headPose.orientation.rotate({0,1,0})-Vec3{0,1,0}),0,.01f);
            } else {
                check(out.viewTilt>.3f,"WALL TILT OFF levelled the view on a death");
                check(rig.tiltGuard().resets==0,"WALL TILT OFF counted a reset");
            }
            // reset() keeps the setting.
            rig.reset();
            rig.diedOrRespawned();
            out=holdFor(rig,f,feet,{},.012f);
            check(rig.tiltGuard().resets==(mode==0?2u:0u),"reset() lost WALL TILT");
        }
    });
