        TargetCommand yank{7,TargetKind::Character,TargetCommand::Mode::Launch};yank.velocity={0,4,10};
        near(pullLaunch(yank,from,gravity,c).z,10);
        const TargetCommand none{7,TargetKind::Character,TargetCommand::Mode::Rope};
