            for(int side=0;side<2;++side)near(dot(heroPalm(b,b.rest,side),{0,-1,0}),std::cos(.5236f),.01f);
            const Quat grips[]={gripFacing({0,0,1}),gripFacing({0,.5f,.866f}),
                                gripFacing({.3f,-.2f,1})*body::axisAngle({0,1,0},1.2f)};
