    test("Update 17: every text size reflows the settings pages, nothing overflows or overlaps", [] {
        using namespace wrist_hud;
        near(textFactor(.2f), .75f);
        near(textFactor(9), 1.75f);
        near(textFactor(std::nanf("")), 1);
        for (int page = 1; page < pages; ++page) {
            float lastHeight = 0, lastTitle = 0;
            for (float k : {.75f, 1.f, 1.25f, 1.5f, 1.75f}) {
                const auto areas = pageAreas(page, k);
                check(!areas.empty(), "a page has nothing on it");
                float title = 0;
                for (size_t a = 0; a < areas.size(); ++a) {
                    const Area& x = areas[a];
                    const std::string what = x.what;
                    check(x.u0 < x.u1 && x.v0 < x.v1, what + " is empty");
                    check(x.u0 >= -panelWidth / 2 + .006f && x.u1 <= scrollbarU0 - .001f && x.v1 <= viewTop,
                          what + " leaves its row at a text size");
                    if (what == "an explanation line")
                        check(x.u1 - x.u0 <= helpWidth + 1e-4f, "an explanation line is not wrapped");
                    if (what == "the title" || what == "a control's name")
                        title = std::max(title, x.v1 - x.v0);
                    for (size_t b = a + 1; b < areas.size(); ++b) {
                        const Area& y = areas[b];
                        check(x.u1 <= y.u0 || y.u1 <= x.u0 || x.v1 <= y.v0 || y.v1 <= x.v0,
                              what + " overlaps " + y.what + " at a text size");
                    }
                }
                check(title > lastTitle, "bigger text is not bigger");
                const float h = contentHeight(page, k);
                check(h >= lastHeight - 1e-5f, "bigger text made a page shorter");
                near(maxScroll(page, k), std::max(0.f, h - (viewTop - viewBottom)), 1e-5f);
                lastTitle = title;
                lastHeight = h;
            }
            check(maxScroll(page, 1.75f) > 0, "the biggest text does not scroll");
            // Every control is still where it is drawn, scrolled into view.
            for (unsigned i = 0; i < controls; ++i) {
                const auto c = static_cast<Control>(i);
                const Spot at0 = controlSpot(page, c, 0, 1.5f);
                if (!at0.found || c == Control::previous || c == Control::next)
                    continue;
                const float scroll = clampScroll(page, (viewTop + viewBottom) / 2 - at0.v, 1.5f);
                const Spot at = controlSpot(page, c, scroll, 1.5f);
                check(at.visible && controlAt(page, at.u, at.v, scroll, 1.5f) == c,
                      "a control at 150% text is not where it is drawn");
            }
        }
        // Update 18: page 2 has WEB STYLE and WEB COLOR too, so it scrolls a
        // little even at 75% text, but less than at 100%.
        // Update 39.0.2: sectioned pages; smaller text never scrolls further.
        for (int page = 1; page < pages; ++page)
            check(maxScroll(page, .75f) <= maxScroll(page, 1), "a page at 75% text scrolls further than at 100%");
    });
    test("Update 17: a page scrolls inside the fixed panel; out of view nothing answers", [] {
        using namespace wrist_hud;
        for (int page = 0; page < pages; ++page)
            check(panelTop(page) == panelHeight / 2, "a page is not the status page's size");
        check(maxScroll(0) == 0 && !scrollThumb(0, 0).shown, "the status page scrolls");
        const float strip = -panelHeight / 2 - .014f;
        for (int page = 1; page < pages; ++page) {
            const float most = maxScroll(page);
            if (most <= 0) { // Update 39.0.2: a page with its sections closed (COLOR) may fit at 100%.
                check(maxScroll(page, 1.75f) > 0, "a settings page fits at the biggest text: no scroll to test");
                continue;
            }
            near(clampScroll(page, -1), 0);
            near(clampScroll(page, 9), most);
            near(clampScroll(page, std::nanf("")), 0);
            // The thumb: inside the track, at the top unscrolled, the bottom scrolled, moving down.
            const Thumb top = scrollThumb(page, 0), mid = scrollThumb(page, most / 2), end = scrollThumb(page, most);
            check(top.shown && mid.shown && end.shown, "no scrollbar on a scrolling page");
            check(top.v1 > top.v0 && top.v1 <= viewTop + .003f && end.v0 >= -panelHeight / 2,
                  "the thumb leaves its track");
            check(top.v0 > mid.v0 && mid.v0 > end.v0, "the thumb does not follow the scroll");
            near(top.v1 - top.v0, end.v1 - end.v0);
            check(onScrollbar(page, (scrollbarU0 + scrollbarU1) / 2, 0) && !onScrollbar(page, 0, 0) &&
                      !onScrollbar(page, (scrollbarU0 + scrollbarU1) / 2, viewTop + .01f),
                  "the scrollbar's grab zone is wrong");
            for (float v = viewBottom; v <= viewTop; v += .005f)
                check(controlAt(page, (scrollbarU0 + scrollbarU1) / 2, v, most / 2) == Control::none,
                      "the scrollbar answered as a control");
            // The arrows do not scroll.
            check(controlAt(page, .06f, strip, most) == Control::next &&
                      controlAt(page, -.06f, strip, most) == Control::previous,
                  "the arrows moved with the scroll");
            // A control: found where drawn at every scroll, and nothing outside the inner area.
            for (unsigned i = 0; i < controls; ++i) {
                const auto c = static_cast<Control>(i);
                if (c == Control::previous || c == Control::next)
                    continue;
                for (float scroll : {0.f, most / 3, most}) {
                    const Spot at = controlSpot(page, c, scroll);
                    if (!at.found)
                        continue;
                    near(at.v, controlSpot(page, c).v + scroll);
                    check(at.visible == (at.v >= viewBottom && at.v <= viewTop), "a spot's visibility is wrong");
                    if (at.visible)
                        check(controlAt(page, at.u, at.v, scroll) == c, "a scrolled control is not where drawn");
                    else { // under the inner area only the page arrows (always shown) answer
                        const Control got = controlAt(page, at.u, at.v, scroll);
                        check(got == Control::none || got == Control::previous || got == Control::next,
                              "a hidden control answered");
                    }
                }
            }
            for (float u = -.08f; u <= .08f; u += .004f) {
                for (float v = viewTop + .0005f; v < panelHeight / 2; v += .002f)
                    check(controlAt(page, u, v, most) == Control::none, "a control scrolled above the view answered");
                for (float v = -panelHeight / 2; v < viewBottom - .0005f; v += .002f)
                    check(controlAt(page, u, v, 0) == Control::none, "a control below the view answered");
            }
        }
    });
    test("Update 17: the scrolled content is clipped to the inner area", [] {
        using namespace wrist_hud;
        const Frame f{{0, 1, 0}, {1, 0, 0}, {0, 1, 0}};
        auto tri = [&](float v0, float v1, float v2) {
            return std::vector<Vertex>{{{-.01f, 1 + v0, 0}, {1, 1, 1}, 1, {}},
                                       {{.01f, 1 + v1, 0}, {1, 1, 1}, 1, {}},
                                       {{0, 1 + v2, 0}, {1, 1, 1}, 1, {}}};
        };
        // Inside: kept as is.
        auto in = tri(0, .01f, .02f);
        auto out = in;
        clipBand(out, 0, f, 1, -.05f, .05f);
        check(out.size() == 3, "a triangle inside was changed");
        for (size_t i = 0; i < 3; ++i)
            near(out[i].position.y, in[i].position.y);
        // Wholly outside: gone. Straddling: cut to the band, whole triangles.
        out = tri(.06f, .07f, .08f);
        clipBand(out, 0, f, 1, -.05f, .05f);
        check(out.empty(), "a triangle outside was drawn");
        out = tri(-.1f, .1f, .1f);
        clipBand(out, 0, f, 1, -.05f, .05f);
        check(!out.empty() && out.size() % 3 == 0, "a straddling triangle was lost or broken");
        for (const Vertex& x : out)
            check(x.position.y >= 1 - .05f - 1e-5f && x.position.y <= 1 + .05f + 1e-5f && finite(x.position),
                  "a clipped vertex is outside the band");
        // Before `from`, untouched; at scale 2 the band doubles.
        out = tri(.2f, .3f, .4f);
        auto more = tri(.06f, .07f, .08f);
        out.insert(out.end(), more.begin(), more.end());
        clipBand(out, 3, f, 2, -.05f, .05f);
        check(out.size() == 6 && out[0].position.y > 1.19f, "clipping touched what came before or the scale");
        // The drawn panel: a scrolled settings page stays inside its frame.
        View v;
        v.emitter = {0, 1, -.4f};
        const Vec3 eye{0, 1.6f, 0};
        for (int page = 1; page < pages; ++page)
            for (float text : {1.f, 1.75f}) {
                v.page = page;
                v.textScale = text;
                v.scroll = maxScroll(page, text) / 2;
                std::vector<Vertex> drawn;
                appendWristHud(drawn, v, eye, .001f);
                check(!drawn.empty() && drawn.size() % 3 == 0 && drawn.size() <= maxVertices, "a scrolled page broke");
                check(sane(drawn, 0, v.emitter, 1.f), "a scrolled page is not sane");
                const Frame g = place(v, eye);
                for (const Vertex& x : drawn)
                    check(dot(x.position - g.centre, g.up) <= panelHeight / 2 + .04f,
                          "scrolled content was drawn above the panel");
            }
    });
    test("Update 17: the themes keep text readable and never lean on red/green alone", [] {
        using namespace wrist_hud;
        const auto lum = [](Vec3 c) { return .2126f * c.x + .7152f * c.y + .0722f * c.z; };
        const auto contrast = [&](Vec3 a, Vec3 b) {
            const float x = lum(a) + .05f, y = lum(b) + .05f;
            return std::max(x, y) / std::min(x, y);
        };
        std::set<std::string> names, keys;
        for (int t = 0; t < themes; ++t) {
            names.insert(themeName(t));
            keys.insert(themeKey(t));
            for (int c = 0; c < textColors; ++c) {
                const Palette p = palette(t, c);
                for (Vec3 x : {p.text, p.label, p.value, p.help})
                    check(contrast(x, p.backing) >= 4.5f, std::string(themeName(t)) + " text is under 4.5:1");
                check(p.backingAlpha > .3f && p.backingAlpha <= 1, "a theme's glass is see-through");
            }
            const Palette p = palette(t, 0);
            check(std::abs(lum(p.good) - lum(p.bad)) > .1f || std::abs(p.good.z - p.bad.z) >= .5f ||
                      std::abs(p.good.x - p.bad.x) >= .5f,
                  "a theme's FPS bands are alike");
        }
        check(names.size() == themes && keys.size() == themes, "the theme names are not distinct");
        check(std::string(themeKey(0)) == "spiderman" && std::string(themeKey(4)) == "mono" &&
                  std::string(themeKey(5)) == "raimi" && std::string(themeName(5)) == "2000s Raimi" &&
                  std::string(textColorKey(2)) == "yellow",
              "the live.txt theme keys changed");
        // Update 36: 2000s Raimi draws every page in the pixel font, at most
        // maxVertices, sane, the larger text and scrolled to its end too; its
        // COLOR THEME subtext one sentence of at most 80 characters.
        for (const float k : {1.f, 1.75f})
            for (int page = 0; page < pages; ++page)
                for (const bool end : {false, true}) {
                    View v;
                    v.emitter = {0, 1, -.4f};
                    v.theme = raimiTheme;
                    v.settings.hudTheme = static_cast<float>(raimiTheme);
                    v.page = page;
                    v.textScale = k;
                    v.settings.hudText = k * 100;
                    v.scroll = end ? maxScroll(page, k) : 0;
                    std::vector<Vertex> out;
                    appendWristHud(out, v, {0, 1.6f, 0}, .001f);
                    check(!out.empty() && out.size() % 3 == 0 && out.size() <= maxVertices &&
                              sane(out, 0, v.emitter, 1.f),
                          "a 2000s Raimi page broke");
                }
        {
            const std::string help = raimiHelp;
            check(help.size() <= 80 && std::count(help.begin(), help.end(), '.') == 1 && help.back() == '.',
                  "the 2000s Raimi subtext is not one short sentence");
        }
        // Deutan/protan: good and bad apart by blue; tritan: by red.
        near(palette(-1, 0).frame.x, palette(0, 0).frame.x);
        check(std::abs(palette(2, 0).good.z - palette(2, 0).bad.z) >= .5f, "the deutan theme leans on red/green");
        check(std::abs(palette(3, 0).good.x - palette(3, 0).bad.x) >= .5f, "the tritan theme leans on blue/yellow");
        const Palette m = palette(4, 0);
        for (Vec3 x : {m.frame, m.accent, m.line, m.text, m.label, m.value, m.help, m.good, m.warn, m.bad})
            check(std::abs(x.x - x.y) < 1e-4f && std::abs(x.y - x.z) < 1e-4f, "the monochrome theme has colour");
        // A text colour overrides the theme's text, not its frame.
        const Palette y = palette(0, 2);
        check(y.label.x == y.value.x && y.text.z < .5f && y.frame.x == palette(0, 0).frame.x, "YELLOW text is wrong");
        near(palette(0, 9).label.x, palette(0, 0).label.x);
        // Words, not colour alone.
        std::set<std::string> words{fpsWord(-1), fpsWord(0), fpsWord(1), fpsWord(2)};
        check(words.size() == 4 && std::string(fpsWord(2)) == "OK" && std::string(fpsWord(1)) == "LOW",
              "the FPS words are wrong");
    });
    test("Update 17: the hologram page's settings, their values and when they apply", [] {
        using namespace wrist_hud;
        const auto bit = [](Control c) { return 1u << static_cast<unsigned>(c); };
        // Update 39.0.2: HOLOGRAM is VR SETTINGS' third section.
        check(placeOf(Control::hudHeight).page == vrPage &&
                  std::string(sectionName(vrPage, placeOf(Control::hudHeight).section)) == "HOLOGRAM",
              "HOLOGRAM is not a VR SETTINGS section");
        for (Control c : {Control::hudHeight, Control::hudScale, Control::hudText, Control::hudTheme,
                          Control::hudTextColor}) {
            check(onPageAny(vrPage, c) && !restartRequired(c) && !gpuSide(c), "a hologram setting is wrong");
            const std::string help = helpText(c);
            check(help.size() > 20 && help.back() == '.', "a hologram setting has no explanation");
        }
        Settings s;
        near(s.hudHeight, 9);
        near(s.hudScale, 1);
        near(s.hudText, 100);
        s[Control::hudScale] = 1.5f;
        near(s.hudScale, 1.5f);
        near(clampTo(Control::hudHeight, 40), 25);
        near(clampTo(Control::hudScale, .1f), .5f);
        near(clampTo(Control::hudScale, 3), 2);
        near(clampTo(Control::hudText, 300), 175);
        near(clampTo(Control::hudText, std::nanf("")), 75);
        near(clampTo(Control::hudTheme, 7), 5);
        near(clampTo(Control::hudTextColor, 7), 3);
        check(valueText(Control::hudHeight, 9) == "9 CM" && valueText(Control::hudScale, 1.25f) == "1.25X" &&
                  valueText(Control::hudText, 150) == "150%" &&
                  valueText(Control::hudTheme, 0) == themeName(0) &&
                  valueText(Control::hudTextColor, 3) == textColorName(3),
              "a hologram value prints wrong");
        for (float u = -.07f; u < .07f; u += .003f) {
            const float x = sliderValue(Control::hudScale, u);
            near(x * 20, std::round(x * 20), 1e-3f);
            near(std::fmod(sliderValue(Control::hudText, u), 5.f), 0);
        }
        // Size, height and text wait for the slider to be let go (the panel would move under it).
        Applier a;
        a.start(s);
        a.want(Control::hudScale, 1.2f);
        check(!(a.due(1, Control::hudScale) & bit(Control::hudScale)), "the size applied while dragged");
        check(a.due(1, Control::none) & bit(Control::hudScale), "the size did not apply when let go");
        a.want(Control::hudTheme, 3);
        check(a.due(1, Control::hudTheme) & bit(Control::hudTheme), "the theme waited");
        check(a.result(Control::hudScale, true, 1.2f, 1), "the size failed");
    });
    test("Update 17: the menu scrolls by stick and drag, cycles themes, and ignores a relaid panel", [] {
        using namespace wrist_hud;
        const auto bit = [](Control c) { return 1u << static_cast<unsigned>(c); };
        Menu m;
        Settings s;
        resetSections();
        m.setPage(graphicsPage);
        auto step = [&](float u, float v, float trigger, float stick = 0, uint32_t layout = 0, float seconds = .05f) {
            Menu::Input in;
            in.active = true;
            in.pointer.hit = true;
            in.pointer.u = u;
            in.pointer.v = v;
            in.trigger = trigger;
            in.stick = stick;
            in.seconds = seconds;
            in.layout = layout;
            return m.update(in, s);
        };
        const float most = maxScroll(graphicsPage);
        // Stick down on the panel shows further down; off the panel the stick is the game's.
        auto r = step(0, 0, 0, -1);
        check(r.stick && r.scrolled && m.scroll() > 0, "stick down did not scroll");
        const float after = m.scroll();
        r = step(.5f, 0, 0, -1);
        check(!r.stick && !r.scrolled && m.scroll() == after, "the stick off the panel scrolled");
        r = step(0, 0, 0, .1f);
        check(r.stick && !r.scrolled, "the deadzone scrolled");
        for (int i = 0; i < 100; ++i)
            step(0, 0, 0, -1);
        near(m.scroll(), most);
        for (int i = 0; i < 100; ++i)
            step(0, 0, 0, 1, 0, std::nanf(""));
        near(m.scroll(), most); // NaN seconds: no time passed
        for (int i = 0; i < 100; ++i)
            step(0, 0, 0, 1);
        near(m.scroll(), 0);
        // Dragging the empty panel: the content follows the pointer.
        float emptyU = -.075f, emptyV = 0;
        bool found = false;
        for (float v = viewTop - .005f; v > viewBottom + .02f && !found; v -= .002f)
            for (float u = -.075f; u < .07f && !found; u += .005f)
                if (controlAt(graphicsPage, u, v, 0) == Control::none &&
                    controlAt(graphicsPage, u, v + .02f, .02f) == Control::none) {
                    emptyU = u;
                    emptyV = v;
                    found = true;
                }
        check(found, "no empty place on the page to drag");
        step(emptyU, emptyV, .3f);
        step(emptyU, emptyV, .8f);
        r = step(emptyU, emptyV + .02f, .8f);
        check(r.scrolled && m.held() == Control::none, "dragging the panel did not scroll");
        near(m.scroll(), std::min(.02f, most), 1e-4f);
        r = step(emptyU, emptyV + .02f, .8f, -1);
        check(!r.scrolled, "the stick scrolled during a drag");
        step(emptyU, emptyV, 0);
        // The scrollbar: dragged down, the page scrolls to its end.
        const float bar = (scrollbarU0 + scrollbarU1) / 2;
        const Thumb th = scrollThumb(graphicsPage, m.scroll());
        step(bar, (th.v0 + th.v1) / 2, .3f);
        step(bar, (th.v0 + th.v1) / 2, .8f);
        step(bar, -.5f, .8f);
        near(m.scroll(), most);
        step(bar, 0, 0);
        // A slider held: the stick does not scroll.
        const float histScroll = clampScroll(graphicsPage, (viewTop + viewBottom) / 2 - controlSpot(graphicsPage, Control::history).v);
        m.setScroll(graphicsPage, histScroll);
        const Spot hist = controlSpot(graphicsPage, Control::history, m.scroll());
        step(hist.u, hist.v, .3f);
        step(hist.u, hist.v, .8f);
        check(m.held() == Control::history, "the history slider was not held");
        r = step(hist.u, hist.v, .8f, -1);
        check(!r.scrolled && m.scroll() == histScroll, "the stick scrolled while a slider was held");
        step(hist.u, hist.v, 0);
        // Relaid (resized or moved) as the trigger is pulled: no hover, no press,
        // and holding on after presses nothing.
        step(hist.u, hist.v, 0, 0, 0);
        check(m.hover() == Control::history, "no hover");
        step(hist.u, hist.v, .3f, 0, 0);
        r = step(hist.u, hist.v, .8f, 0, 7);
        check(!r.pressed && !r.changed && m.hover() == Control::none && m.held() == Control::none,
              "a press on a relaid panel acted");
        r = step(hist.u, hist.v, .8f, 0, 7);
        check(!r.pressed && !r.changed, "a press held through a relayout acted");
        step(hist.u, hist.v, 0, 0, 7);
        // Relaid while a slider is held: it is let go.
        step(hist.u, hist.v, .3f, 0, 7);
        step(hist.u, hist.v, .8f, 0, 7);
        check(m.held() == Control::history, "the slider was not held again");
        step(hist.u, hist.v, .8f, 0, 8);
        check(m.held() == Control::none, "a held slider survived a relayout");
        r = step(-.07f, hist.v, .8f, 0, 8);
        check(!r.changed, "a slider let go by a relayout still moved");
        step(hist.u, hist.v, 0, 0, 8);
        // The theme cycles and wraps on each press.
        const int themePage = openAt(Control::hudTheme);
        m.setPage(themePage);
        const Spot theme = controlSpot(themePage, Control::hudTheme);
        const float scroll = clampScroll(themePage, (viewTop + viewBottom) / 2 - theme.v);
        m.setScroll(themePage, scroll);
        const Spot at = controlSpot(themePage, Control::hudTheme, scroll);
        check(at.visible, "the theme cannot be shown");
        s.hudTheme = 4;
        for (float want : {5.f, 0.f, 1.f}) {
            step(at.u, at.v, 0, 0, 8);
            step(at.u, at.v, .3f, 0, 8);
            r = step(at.u, at.v, .8f, 0, 8);
            check(r.pressed && r.changed == bit(Control::hudTheme), "the theme did not change");
            near(s.hudTheme, want);
            step(at.u, at.v, 0, 0, 8);
        }
    });
    test("Update 18: web styles and their shades: names, unique across styles, distinct colours", [] {
        namespace st = web_style;
        const char* names[] = {"90s", "MESSY", "MODERN", "SYMBIOTE", "ENERGY"};
        const char* keys[] = {"90s", "messy", "modern", "symbiote", "energy"};
        const std::vector<std::vector<std::string>> shades = {
            {"CREAM", "IVORY", "PARCHMENT", "WARM GREY"},
            {"SILVER", "PEARL", "SMOKE", "FROST"},
            {"BRIGHT WHITE", "PLATINUM", "ICE", "CHROME"},
            {"BLUE SHEEN", "PURPLE SHEEN", "CRIMSON SHEEN", "MATTE"},
            {"BLUE", "RED", "GREEN", "ORANGE", "PURPLE", "GOLD"}};
        check(st::count == 5, "not five styles");
        for (int i = 0; i < st::count; ++i) {
            check(std::strcmp(st::name(i), names[i]) == 0 && std::strcmp(st::key(i), keys[i]) == 0, "a style's name");
            check(st::shades(i) == static_cast<int>(shades[static_cast<size_t>(i)].size()) &&
                      st::shades(i) <= st::maxShades,
                  "a style's shade count");
            for (int k = 0; k < st::shades(i); ++k) {
                check(st::shadeName(i, k) == shades[static_cast<size_t>(i)][static_cast<size_t>(k)], "a shade's name");
                std::string key = st::shadeName(i, k);
                for (char& c : key)
                    c = c == ' ' ? '_' : static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
                check(key == st::shadeKey(i, k), "a shade's key is not its name");
            }
            // Out of range: the style's default.
            check(std::strcmp(st::shadeName(i, -1), st::shadeName(i, 0)) == 0 &&
                      std::strcmp(st::shadeName(i, 99), st::shadeName(i, 0)) == 0,
                  "an out-of-range shade");
        }
        check(std::strcmp(st::name(-1), "90s") == 0 && std::strcmp(st::name(5), "90s") == 0, "an out-of-range style");
        // 90s CREAM is the rope as it always was.
        const WebLook plain;
        near(st::shade(st::nineties, 0).color.x, plain.core.x);
        near(st::shade(st::nineties, 0).color.y, plain.core.y);
        near(st::shade(st::nineties, 0).color.z, plain.core.z);
        // No name twice anywhere, and no near colour across styles (sRGB
        // distance of the shaded rope's swatch, 0-1 a channel).
        const auto srgb = [](Vec3 c) {
            const auto e = [](float x) { return std::pow(std::clamp(x, 0.f, 1.f), 1 / 2.2f); };
            return Vec3{e(c.x), e(c.y), e(c.z)};
        };
        std::set<std::string> seen, seenKeys;
        float closestAcross = 9, closestWithin = 9;
        for (int a = 0; a < st::count; ++a)
            for (int i = 0; i < st::shades(a); ++i) {
                check(seen.insert(st::shadeName(a, i)).second && seenKeys.insert(st::shadeKey(a, i)).second,
                      std::string("a shade's name is used twice: ") + st::shadeName(a, i));
                const Vec3 x = srgb(st::swatch(a, i));
                check(std::isfinite(x.x) && std::isfinite(x.y) && std::isfinite(x.z), "a swatch is not finite");
                for (int b = a; b < st::count; ++b)
                    for (int j = b == a ? i + 1 : 0; j < st::shades(b); ++j) {
                        const float d = length(x - srgb(st::swatch(b, j)));
                        (a == b ? closestWithin : closestAcross) = std::min(a == b ? closestWithin : closestAcross, d);
                        if (a != b && d < .08f)
                            std::cout << "  near: " << st::shadeName(a, i) << " / " << st::shadeName(b, j) << ' ' << d
                                      << '\n';
                    }
            }
        check(closestAcross >= .08f, "two styles have a near-identical shade");
        check(closestWithin >= .03f, "two shades of one style look the same");
    });
    test("Update 18: every style and shade draws finite, in budget, with the width, travel and far floor", [] {
        namespace st = web_style;
        WebLine held;
        held.start = {0, 10, 0};
        held.end = {2, 24, -16};
        held.slack = 1.5f;
        held.wave = .3f;
        held.wavePhase = .7f;
        held.seed = .3f;
        const Vec3 head{.2f, 10.3f, .4f};
        const Vec3 axis = normalized(held.end - held.start);
        const float pixel = .0011f;
        for (int style = 0; style < st::count; ++style)
            for (int shade = 0; shade < st::shades(style); ++shade)
                for (float width : {WebLook::minRadius, .0065f, WebLook::maxRadius})
                    for (float extended : {.3f, 1.f}) {
                        WebLook look;
                        look.style = style;
                        look.color = shade;
                        look.radius = width;
                        look.seconds = 2.7f;
                        WebLine web = held;
                        web.extended = extended;
                        web.splat = extended >= 1;
                        std::vector<Vertex> v;
                        appendWeb(v, web, head, pixel, look);
                        check(!v.empty() && v.size() % 3 == 0 && v.size() <= st::vertexBudget,
                              std::string("a styled web's size: ") + st::name(style));
                        check(st::sane(v, 0), std::string("a styled web is not finite: ") + st::name(style));
                        // The travel: an unfinished shot stops short of the anchor.
                        if (extended < 1) {
                            float reach = 0;
                            for (const Vertex& x : v)
                                reach = std::max(reach, dot(x.position - web.start, axis));
                            check(reach < length(web.end - web.start) * .6f, "a styled shot reached the anchor early");
                        }
                    }
        // Width: a wider rope is wider in every style.
        for (int style = 0; style < st::count; ++style) {
            float spread[2] = {};
            for (int w = 0; w < 2; ++w) {
                WebLook look;
                look.style = style;
                look.radius = w ? .016f : .004f;
                WebLine web = held;
                web.slack = 0;
                web.wave = 0;
                web.splat = false;
                std::vector<Vertex> v;
                appendWeb(v, web, head, pixel, look);
                for (const Vertex& x : v) {
                    const Vec3 r = x.position - web.start;
                    const float along = dot(r, axis);
                    if (along > 2 && along < 4)
                        spread[w] = std::max(spread[w], length(r - axis * along));
                }
            }
            check(spread[1] > spread[0] * 1.8f, std::string("web_width does not widen ") + st::name(style));
        }
        // Update 20: MESSY and MODERN are translucent threads, tip and splat
        // too (no opaque blob, bead or glint); 90s keeps its solid rope.
        for (int style : {st::messy, st::modern, st::nineties})
            for (float extended : {.4f, 1.f}) {
                WebLook look;
                look.style = style;
                look.seconds = 1.3f;
                WebLine web = held;
                web.extended = extended;
                web.splat = extended >= 1;
                std::vector<Vertex> v;
                appendWeb(v, web, head, pixel, look);
                float most = 0;
                for (const Vertex& x : v)
                    most = std::max(most, x.alpha);
                if (style == st::nineties)
                    check(most > .99f, "the 90s rope is no longer solid");
                else
                    check(most < .9f && most > .3f, std::string("not a translucent thread: ") + st::name(style) +
                                                        " " + std::to_string(most));
            }
        // Far: still drawn (the pixel floor), and MESSY is one strand there.
        WebLine far;
        far.start = {0, 10, 0};
        far.end = {3, 30, -60};
        far.splat = false;
        const Vec3 away{0, 10, 140};
        size_t messyNear = 0, messyFar = 0;
        for (int style = 0; style < st::count; ++style) {
            WebLook look;
            look.style = style;
            std::vector<Vertex> v;
            appendWeb(v, far, away, pixel, look);
            check(!v.empty() && st::sane(v, 0), std::string("a far styled web vanished: ") + st::name(style));
            if (style == st::messy) {
                messyFar = v.size();
                v.clear();
                appendWeb(v, far, away, pixel * .01f, look); // the same web a hundred times nearer in pixels
                messyNear = v.size();
            }
        }
        check(messyFar * 2 < messyNear, "far MESSY did not fall back to one strand");
    });
    test("Update 24: every style is a twisted fibrous strand near the eye, plain far off, in budget", [] {
        namespace ws = web_shading;
        namespace st = web_style;
        WebLine held;
        held.start = {-.16f, -.3f, -.55f};
        held.end = {14, 26, -30};
        held.splat = false;
        const Vec3 dir = normalized(held.end - held.start), side = normalized(cross(dir, Vec3{0, 1, 0}));
        const Vec3 closeEye = held.start + dir * .8f + side * .3f + Vec3{0, .04f, 0};
        WebLine across;
        across.start = {-2.2f, -.6f, -4};
        across.end = {2.6f, .9f, -4.4f};
        across.splat = false;
        for (int style = 0; style < st::count; ++style) {
            WebLook look;
            look.style = style;
            look.seconds = 1.35f;
            const auto count = [&](const WebLine& web, Vec3 eye, float pixel, int& loose, int& plies) {
                std::vector<Vertex> v;
                appendWeb(v, web, eye, pixel, look);
                loose = plies = 0;
                for (const Vertex& x : v) {
                    loose += x.shape.w == 0;
                    plies += ws::isGloss(x.shape) && x.shape.w > ws::glossBase + 3.5f;
                }
                return v;
            };
            int looseNear = 0, pliesNear = 0, looseFar = 0, pliesFar = 0;
            const auto nearV = count(held, closeEye, .00065f, looseNear, pliesNear);
            const auto farV = count(across, Vec3{0, 0, 0}, .00065f, looseFar, pliesFar);
            // (ENERGY's glow band is plain colour too: what is drawn where
            // pixels are far too coarse for any fibre is that alone.)
            int looseNearCoarse = 0, looseFarCoarse = 0, unused = 0;
            count(held, closeEye, .01f, looseNearCoarse, unused);
            count(across, Vec3{0, 0, 0}, .01f, looseFarCoarse, unused);
            check(looseNear > looseNearCoarse, std::string("no loose fibres up close: ") + st::name(style));
            check(looseFar == looseFarCoarse && pliesFar == 0,
                  std::string("fibres or plies on a far web: ") + st::name(style));
            check(style == st::energy || looseFarCoarse == 0, std::string("plain colour on a far web: ") + st::name(style));
            check(style == st::nineties || pliesNear > 0, std::string("no plies up close: ") + st::name(style));
            check(farV.size() < nearV.size(), std::string("a far web is not cheaper: ") + st::name(style));
            // The plies stay inside the rope's own radius (its width unchanged).
            if (style == st::messy || style == st::modern || style == st::energy)
                for (const Vertex& x : nearV) {
                    if (!(ws::isGloss(x.shape) && x.shape.w > ws::glossBase + 3.5f))
                        continue;
                    const Vec3 o = x.position - held.start;
                    const float off = length(o - dir * dot(o, dir));
                    check(off <= look.radius * 1.05f + 1e-4f, std::string("a ply outside the rope: ") + st::name(style));
                }
            // In budget wherever the eye is, at headset and finer pixels (90s,
            // never budget-checked when drawn and in a growing buffer, only at
            // headset pixels: twice as fine it was near the budget before).
            for (const Vec3 eye : {Vec3{0, 0, 0}, closeEye, held.start + Vec3{.05f, .02f, .05f}})
                for (const float pixel : {.00065f, .0003f}) {
                    if (style == st::nineties && pixel < .0005f)
                        continue;
                    std::vector<Vertex> v;
                    appendWeb(v, held, eye, pixel, look);
                    check(!v.empty() && v.size() % 3 == 0 && v.size() <= st::vertexBudget,
                          std::string("over budget: ") + st::name(style));
                    if (style != st::nineties)
                        check(st::sane(v, 0), std::string("not sane, would fall back to 90s: ") + st::name(style));
                }
        }
    });
    test("Update 24: the fibre shading shows up close and fades out far, the ply flag decodes", [] {
        namespace ws = web_shading;
        for (int kind = 0; kind < 4; ++kind) {
            for (const bool ply : {false, true}) {
                const Shape s = ws::glossShape(kind, .3f, .6f, .1f, ply);
                check(ws::isGloss(s) && !ws::isTube(s) && !ws::isStrand(s), "a ply is not gloss");
                near(s.w - (ply ? ws::plyOffset : 0.f), ws::glossShape(kind, .3f, .6f, .1f).w, 1e-6f);
            }
            // Far (a turn of the twist in under a pixel): the phase no longer shows.
            float lo = 9, hi = -9, nearLo = 9, nearHi = -9;
            for (int i = 0; i < 16; ++i) {
                const float p = i / 16.f * .9f;
                const bool round = kind <= ws::glossMessy; // MODERN/MESSY: the phase in z; else in x
                const Shape s = round ? ws::glossShape(kind, .3f, .8f, p, true) : ws::glossShape(kind, p, .8f, .7f, true);
                Vec3 far{.6f, .6f, .6f}, close{.6f, .6f, .6f};
                ws::shadeGloss(far, s, round ? 10.f : 1.f, round ? 1.f : 10.f);
                ws::shadeGloss(close, s, .004f, .004f);
                if (round) {
                    lo = std::min(lo, far.x), hi = std::max(hi, far.x);
                    nearLo = std::min(nearLo, close.x), nearHi = std::max(nearHi, close.x);
                }
                check(std::isfinite(far.x) && std::isfinite(close.x), "fibre shading not finite");
            }
            if (kind <= ws::glossMessy) {
                check(hi - lo < 1e-4f, "fibres still show far off (they would shimmer)");
                check(nearHi - nearLo > .03f, "no fibre lines up close");
            }
        }
    });
