    test("Update 36: the health ring shows as the meter did, under the wrist, sanely", [] {
        Pose hand{{.1f, 1.1f, -.3f}, {}};
        const Vec3 viewer{0, 1.6f, 0};
        const float pixelAngle = .0015f;
        SlowMotionView slow;
        slow.meter = 1;
        slow.focus = .5f;
        const auto count = [&](const SlowMotionView& s, float health, Pose h, Vec3 v) {
            std::vector<Vertex> art;
            health_ring::append(art, s, health, h, v, pixelAngle, 1.25f);
            return art;
        };
        auto art = count(slow, .7f, hand, viewer);
        check(!art.empty() && art.size() % 3 == 0, "the ring drew nothing");
        Vec3 sum{};
        for (const auto& v : art) {
            check(finite(v.position) && finite(v.color) && std::isfinite(v.alpha) && v.alpha >= 0 && v.alpha <= 1,
                  "a ring vertex not finite");
            check(v.shape.x >= 0 && v.shape.x <= 1 && v.shape.y >= 0 && v.shape.y <= 1, "a ring vertex off the atlas");
            const Vec3 centre = hand.position + health_ring::fromHand;
            check(length(v.position - centre) < health_ring::outerRadius + .01f, "a ring vertex off the ring");
            sum += v.position;
        }
        check(length(sum / static_cast<float>(art.size()) - (hand.position + health_ring::fromHand)) < .006f,
              "the ring away from under the wrist");
        auto none = slow;
        none.meter = 0;
        check(count(none, .7f, hand, viewer).empty(), "the ring without the meter");
        none.meter = std::numeric_limits<float>::quiet_NaN();
        check(count(none, .7f, hand, viewer).empty(), "the ring with an unknown opacity");
        check(count(slow, .7f, hand, hand.position + health_ring::fromHand + Vec3{0, 0, .05f}).empty(),
              "the ring in the viewer's face");
        check(count(slow, .7f, hand, hand.position + Vec3{0, 0, 4}).empty(), "the ring 4 m away");
        auto lost = hand;
        lost.position.x = std::numeric_limits<float>::quiet_NaN();
        check(count(slow, .7f, lost, viewer).empty(), "the ring for a hand without a place");
        check(count(slow, .9f, hand, viewer).size() > count(slow, .2f, hand, viewer).size(),
              "more health, no more fill");
        auto fuller = slow;
        fuller.focus = .9f;
        check(count(fuller, .5f, hand, viewer).size() > count(slow, .5f, hand, viewer).size(),
              "more focus, no more fill");
        check(count(slow, std::numeric_limits<float>::quiet_NaN(), hand, viewer).size() >
                  count(slow, 0, hand, viewer).size(),
              "unread health not marked N/A");
    });
    test("Update 36: health and focus drain from the wide right end toward the thin left tip", [] {
        Pose hand{{.1f, 1.1f, -.3f}, {}};
        const Vec3 viewer{0, 1.6f, 0};
        const Vec3 centre = hand.position + health_ring::fromHand;
        const Vec3 right = normalized(cross(Vec3{0, 1, 0}, normalized(viewer - centre)));
        // The farthest a fill vertex reaches to the right, health (red) or focus (blue).
        const auto reach = [&](float health, float focus, bool blueFill) {
            SlowMotionView slow;
            slow.meter = 1;
            slow.focus = focus;
            std::vector<Vertex> art;
            health_ring::append(art, slow, health, hand, viewer, .0015f, 1.25f);
            float most = -1;
            int n = 0;
            for (const auto& v : art) {
                const Vec3 c = v.color;
                const bool fill = v.alpha > .9f && (blueFill ? c.z > .7f && c.x < .45f
                                                             : c.x > .7f && c.y < .4f && c.z < .4f);
                if (!fill)
                    continue;
                most = std::max(most, dot(v.position - centre, right));
                ++n;
            }
            return n ? most : -1.f;
        };
        check(reach(1, 1, false) > .015f && reach(1, 1, true) > .015f, "a full ring not reaching the right end");
        check(reach(.25f, .5f, false) < -.008f, "a quarter of health not held at the left");
        check(reach(.5f, .25f, true) < -.008f, "a quarter of focus not held at the left");
        check(reach(.5f, .5f, false) < .002f && reach(.5f, .5f, true) < .002f, "half not ending mid-ring");
        // Smoothly: a little less always reaches a little less, no steps.
        float last = reach(1, .5f, false);
        for (int i = 99; i >= 30; --i) {
            const float r = reach(i / 100.f, .5f, false);
            check(r <= last + 1e-4f && last - r < .003f, "health drains in steps");
            last = r;
        }
        // Thinner at the left tip, wider at the right: the taper is pronounced.
        check(health_ring::discShift > .006f, "the crescent barely tapers");
    });
    test("Update 36: the ring eases health jumps briefly, snapping when unknown", [] {
        const float nan = std::numeric_limits<float>::quiet_NaN();
        health_ring::Eased e;
        check(std::isnan(e.update(nan, .011f)), "unknown health not N/A");
        check(e.update(.8f, .011f) == .8f, "the first reading not shown at once");
        float shown = e.update(.3f, .011f);
        check(shown < .8f && shown > .3f, "a hit not eased");
        for (int i = 0; i < 17; ++i) {
            const float next = e.update(.3f, .011f);
            check(next <= shown && next >= .3f, "the ease overshoots or turns back");
            shown = next;
        }
        check(shown < .32f, "the ease lags more than 0.2 s");
        for (int i = 0; i < 20; ++i)
            shown = e.update(.3f, .011f);
        check(shown == .3f, "the ease never arrives");
        check(e.update(.5f, nan) == .5f && e.update(.6f, -1) == .6f, "a bad frame time not snapping");
        check(std::isnan(e.update(nan, .011f)), "health lost not N/A");
        check(e.update(.4f, .011f) == .4f, "health back not shown at once");
    });
