    test("Update 37: the mirror stays where placed when the head turns, moves with the playspace", [] {
        using namespace vr_mirror;
        Frame f;
        f.anchor = {10, 0, 10};
        f.head.position = {10, 1.7f, 10};
        const Placement p = recentre(f, playspace);
        check(p.placed, "RECENTRE did not place the mirror");
        Config c;
        c.on = true;
        const Plane first = plane(p, f, c);
        check(first.valid, "no mirror plane");
        near(first.centre.z, 10 - 1.2f);
        near(first.centre.y, 1.7f);
        Frame turned = f;
        turned.head.orientation = Quat::around({0, 1, 0}, 1.2f);
        const Plane still = plane(p, turned, c);
        check(length(still.centre - first.centre) < 1e-4f, "the mirror followed the head");
        Frame moved = f;
        moved.anchor = f.anchor + Vec3{50, 3, 0};
        moved.head.position = f.head.position + Vec3{50, 3, 0};
        near(plane(p, moved, c).centre.x, first.centre.x + 50);
        const Placement w = recentre(f, world);
        near(plane(w, moved, c).centre.x, first.centre.x); // WORLD: pinned
        // The reflection: the head in front of the mirror shows behind it, facing back.
        const Vec3 r = reflect(first, f.head.position);
        near(r.z, 10 - 2.4f);
        c.spot = Spot::left;
        check(plane(p, f, c).centre.x < first.centre.x, "LEFT is not left");
        std::vector<Vertex> out;
        check(append(out, first, f, c, f.head.position) > 0 && !out.empty(), "the mirror drew nothing");
        Frame bad = f;
        bad.head.position.x = std::nanf("");
        check(!recentre(bad, playspace).placed && !plane(p, bad, c).valid, "a NaN head placed the mirror");
        check(sizeof(Data) == 72, "MIRR record changed");
    });
