    test("Update 37: the WORLD LOG classifies by RTTI name, rate-limits, finds texts and gaze", [] {
        using namespace world_trace;
        check(bitsOf(".?AVPlayDialogComponent@@") == dialogueBit, "a dialogue component is not dialogue");
        check(bitsOf(".?AVCivilianBot@@") == civilianBit && bitsOf(".?AVThugBot@@") == enemyBit,
              "bots are not sorted");
        check(bitsOf(".?AVProximitySpawner@@") & spawnerBit, "a spawner is not a spawner");
        check(!(bitsOf(".?AVAnimSpawnActorCreatedEvent@@") & spawnerBit), "an event counted as a spawner");
        check(bitsOf(".?AVMissionStartVolume@@") & missionBit, "a mission class is not a mission");
        check(bitsOf(".?AVObjectiveStateChangedEvent@@") == 0, "an event counted as an objective");
        check(bitsOf(".?AVActivityClueSystem@@") & activityBit, "an activity class is not an activity");
        check(bitsOf("garbage") == 0 && bitsOf(nullptr) == 0, "not an RTTI name, still sorted");
        check(std::string(speakerOf(allyBit | botBit)) == "ally/police (candidate)", "police are not candidate");
        check(std::string(speakerOf(0)) == "unknown", "no bits, not unknown");
        RateLimit r;
        int took = 0;
        for (int i = 0; i < 100; ++i)
            took += r.take(0);
        check(took == 8 && r.dropped == 92, "the burst is not 8");
        r.refill(1.f);
        check(r.take(0) && r.take(0) && !r.take(0), "a second does not give two more");
        r.refill(std::nanf(""));
        check(!r.take(0), "a NaN refilled");
        check(printable("HeroLine_042", 63) == 12 && printable("ab", 63) == 0 && printable("bad\x01text", 63) == 0,
              "printable texts");
        check(std::abs(gazeDegrees({0, 0, 0}, {0, 0, -1}, {0, 0, -5})) < .01f &&
                  std::abs(gazeDegrees({0, 0, 0}, {0, 0, -1}, {5, 0, 0}) - 90.f) < .01f &&
                  gazeDegrees({0, 0, 0}, {0, 0, 0}, {1, 0, 0}) == 180.f,
              "gaze degrees");
        const uint64_t a[2]{1, 2}, b[2]{1, 3};
        check(hashWords(a, 2) != hashWords(b, 2) && hashWords(a, 2) == hashWords(a, 2), "the hash does not tell a change");
        Data d;
        check(d.magic == dataMagic && d.bytes == sizeof(Data) && offsetof(Data, ring) == 168 &&
                  offsetof(Data, census_) == 9896 && offsetof(Data, sequence) == 11240,
              "the WTRC layout drifted from tools/update37_records.py");
    });
