    test("Update 38.5: BLOOD EXTREME - more than BRUTAL, a second burst, within budget, VISOR DROPS only when asked", [] {
        using namespace blood_splatter;
        const Vec3 eye{0, 1.6f, 0};
        auto quads = [&](uint32_t intensity, bool brutalLook) {
            Pool pool;
            std::vector<Vertex> out;
            pool.fire({0, 1.2f, -1}, {0, 0, -1}, intensity, false, true, 0.f, brutalLook);
            pool.step(.2f);
            append(out, pool, eye);
            for (const auto& v : out)
                check(finite(v.position) && std::isfinite(v.alpha), "a NaN blood vertex");
            return out.size();
        };
        const size_t b = quads(175, true), e = quads(extreme, true);
        check(isExtreme(extreme) && !isExtreme(175) && !isExtreme(100), "isExtreme");
        check(e > b * 3 / 2, "EXTREME is not clearly more than BRUTAL");
        Pool pool;
        pool.fire({0, 1.2f, -1}, {0, 0, -1}, extreme, false, true, 0.f, true);
        check(pool.extremeBursts == 1 && pool.fired == 1, "EXTREME's second burst");
        size_t waiting = 0;
        for (const auto& sp : pool.splashes)
            waiting += sp.age >= 0 && sp.wait > 0;
        check(waiting == 1, "the second burst does not wait");
        // Worst case: the pool full of EXTREME splashes, both coats, the visor.
        std::vector<Vertex> out;
        for (unsigned i = 0; i < most; ++i)
            pool.fire({0, 1.2f, -1}, {0, 0, -1}, extreme, false, true, 0.f, true);
        pool.step(.3f);
        append(out, pool, eye);
        appendCoat(out, {.2f, 1.2f, -.4f}, {0, 0, -1}, 1.f, 1, eye, true, 2.f);
        appendCoat(out, {-.2f, 1.2f, -.4f}, {0, 0, -1}, 1.f, 2, eye, true, 2.f);
        Visor visor;
        check(appendVisor(out, visor, eye, {0, 0, -1}, {0, 1, 0}, {1, 0, 0}) == 0, "a clean visor drew");
        visor.splat(7);
        check(appendVisor(out, visor, eye, {0, 0, -1}, {0, 1, 0}, {1, 0, 0}) > 0, "VISOR DROPS drew nothing");
        check(out.size() <= static_cast<size_t>(budgetQuads) * 6, "EXTREME over its quad budget");
        std::vector<Vertex> plain, heavy;
        appendCoat(plain, {0, 1, 0}, {0, 0, -1}, 1.f, 3, eye);
        appendCoat(heavy, {0, 1, 0}, {0, 0, -1}, 1.f, 3, eye, true, 1.f);
        check(heavy.size() > plain.size(), "EXTREME's glove coat is not heavier");
        for (int i = 0; i < 60; ++i)
            visor.step(.1f);
        check(visor.age < 0, "VISOR DROPS never ran off");
        for (int i = 0; i < 160; ++i)
            pool.step(.1f);
        check(!pool.any() && extremeFloorLife < 16, "EXTREME splashes outlived their time");
        using namespace wrist_hud;
        bool listed = false;
        for (int page = 0; page < pages; ++page)
            listed = listed || (onPageAny(page, Control::bloodVisor) && placeOf(Control::bloodVisor).page == placeOf(Control::blood).page &&
                                 placeOf(Control::bloodVisor).section == placeOf(Control::blood).section);
        check(listed, "VISOR DROPS is not beside BLOOD SPLATTER");
        const std::string h = helpText(Control::bloodVisor);
        check(h.size() <= 80 && h.back() == '.', "VISOR DROPS' help");
    });
