    test("Update 37.2: the MIRROR - body only, stays put until dismissed, never follows gaze or head turns", [] {
        using namespace vr_mirror;
        const Config defaults;
        check(!defaults.on && defaults.style == figure && defaults.anchor == playspace,
              "the mirror's defaults (off, FIGURE: no background, PLAYSPACE)");
        Frame f;
        f.anchor = {0, 0, 0};
        f.head.position = {0, 1.7f, 0};
        const Placement p = recentre(f, playspace);
        Config c;
        c.on = true;
        const Plane first = plane(p, f, c);
        // Look around, up, down, and walk about in the playspace: it stays where it was placed.
        for (int i = 0; i < 40; ++i) {
            Frame g = f;
            g.head.orientation = Quat::around({0, 1, 0}, .3f * static_cast<float>(i)) *
                                 Quat::around({1, 0, 0}, .05f * static_cast<float>(i % 9) - .2f);
            g.head.position = f.head.position + Vec3{.02f * static_cast<float>(i % 5), 0, .03f * static_cast<float>(i % 4)};
            check(length(plane(p, g, c).centre - first.centre) < 1e-4f &&
                      length(plane(p, g, c).normal - first.normal) < 1e-4f,
                  "the mirror moved with the gaze or the head");
        }
        // FIGURE draws fewer vertices than PANEL (PANEL adds the dark backing): no background by default.
        std::vector<Vertex> figureOut, panelOut;
        append(figureOut, first, f, c, f.head.position);
        Config withBacking = c;
        withBacking.style = panel;
        append(panelOut, first, f, withBacking, f.head.position);
        check(!figureOut.empty() && panelOut.size() > figureOut.size(), "FIGURE drew a backing");
        // WORLD: pinned in the city when the playspace moves.
        Frame moved = f;
        moved.anchor = {30, 0, 0};
        moved.head.position = {30, 1.7f, 0};
        check(length(plane(recentre(f, world), moved, c).centre - first.centre) < 1e-4f, "WORLD is not pinned");
    });
