    test("Update 37.2: no gadget with a web attached, the Sonic Burst's cooldown, sane hand speeds", [] {
        using namespace combat_input;
        Config c;
        Machine m;
        Frame f;
        f.play = true;
        f.seconds = 1.f / 90;
        f.head = {0, 1.6f, 0};
        f.forward = {0, 0, -1};
        for (auto& h : f.hands) {
            h.tracked = h.free = true;
            h.palm = {0, 0, -1};
        }
        f.hands[0].position = {-.08f, 1.35f, -.45f};
        f.hands[1].position = {.08f, 1.35f, -.45f};
        uint64_t bursts = 0;
        auto pressBoth = [&](bool web) {
            f.webAttached = web;
            for (auto& h : f.hands)
                h.button = 1;
            for (int i = 0; i < 3; ++i)
                bursts += m.update(f, c).fired[0] == sonicBurst;
            for (auto& h : f.hands)
                h.button = 0;
            for (int i = 0; i < 3; ++i)
                m.update(f, c);
        };
        pressBoth(true);
        check(bursts == 0, "a Sonic Burst with a web attached");
        pressBoth(false);
        check(bursts == 1, "no Sonic Burst in its pose");
        pressBoth(false);
        check(bursts == 1, "a second Sonic Burst inside the cooldown");
        for (int i = 0; i < 100; ++i)
            m.update(f, c);
        pressBoth(false);
        check(bursts == 2, "no Sonic Burst after the cooldown");
        // A near-zero frame time with a small move never makes a huge speed (run371: 57,000 m/s).
        Machine s;
        Frame g = f;
        g.hands[0].position = {0, 1.3f, -.4f};
        s.update(g, c);
        g.seconds = 1e-5f;
        g.hands[0].position = {0, 1.3f, -.41f};
        const Out o = s.update(g, c);
        check(o.speed[0] < Config::glitchSpeed, "a near-zero frame made a huge speed");
    });
    test("Update 37.2: the SM1 web - about 0.15 s in flight, erratic, snaps taut", [] {
        WebTravel t;
        t.speed = 70;
        const float frame = 1.f / 90;
        check(WebAnimation::flight(.05f, 25, t, frame).flying, "not flying at 0.05 s");
        check(!WebAnimation::flight(.16f, 25, t, frame).flying, "still flying after 0.15 s");
        float lastWave = 0;
        bool changed = false;
        for (float s = .01f; s < .14f; s += .01f) {
            const auto fl = WebAnimation::flight(s, 25, t, frame);
            check(std::isfinite(fl.wave) && std::isfinite(fl.wavePhase), "a bad wave");
            changed |= std::abs(fl.wave - lastWave) > 1e-4f;
            lastWave = fl.wave;
        }
        check(changed, "no wiggle in flight");
        const float d = WebAnimation::flightSeconds(25, 70, frame, WebTravel::physicsFlight);
        check(std::abs(WebAnimation::flight(d + WebAnimation::twangSeconds + .001f, 25, t, frame).wave) < 1e-6f,
              "the snap does not end");
        check(std::abs(WebAnimation::flight(d + .06f, 25, t, frame).wave) < .002f, "it does not snap taut quickly");
        // The SM1 rope's faint white glow with jagged edges (MESSY, near): plain bright vertices
        // standing off the line, their outer edges at uneven distances.
        WebLine w;
        w.start = {0, 1.5f, -.5f};
        w.end = {0, 12, -20};
        w.splat = false;
        WebLook look;
        look.style = web_style::messy;
        std::vector<Vertex> v;
        appendWeb(v, w, {.15f, 1.6f, 0}, .00065f, look);
        int glow = 0;
        float lo = 1e9f, hi = 0;
        const Vec3 along = normalized(w.end - w.start);
        for (const Vertex& x : v)
            if (x.shape.w == 0 && x.alpha == 0 && x.color.x > .85f && x.color.y > .85f && x.color.z > .8f) {
                const Vec3 off = x.position - w.start;
                const float out = length(off - along * dot(off, along));
                const float at = dot(off, along);
                if (at > 1 && at < 4) {
                    ++glow;
                    lo = std::min(lo, out);
                    hi = std::max(hi, out);
                }
            }
        check(glow > 20, "no glow round the SM1 rope up close");
        check(hi > lo * 1.3f, "the glow's edges are not jagged");
    });
