    test("Update 38: CRAWL CAP - 2.4 m never, a punch holds it off 1.5 s, few samples, OFF, WITH FLAG", [] {
        using namespace combat38;
        CrawlCap room;
        bool any = false;
        for (int i = 0; i < 900; ++i)
            any = room.update({1 / 90.f, 2.4f, true, false, false}, crawlAuto) || any;
        check(!any, "a 2.4 m room capped");
        for (float m : {1.6f, 1.8f, 2.0f}) {
            CrawlCap c;
            bool a = false;
            for (int i = 0; i < 300; ++i)
                a = c.update({1 / 90.f, m, true, false, false}, crawlAuto) || a;
            check(!a, "a ceiling at or above 1.6 m capped");
        }
        // a duct with a punch: held off while the punch is within 1.5 s, then caps
        CrawlCap duct;
        int capAt = -1;
        for (int i = 0; i < 400 && capAt < 0; ++i)
            if (duct.update({1 / 90.f, 1.2f, i % 3 == 0, false, i == 0}, crawlAuto))
                capAt = i;
        check(capAt >= 134 && capAt <= 140 && duct.heldOff() > 0, "a punch did not hold the cap off 1.5 s");
        // two readings only (one ray glitch) never caps
        CrawlCap few;
        bool f = false;
        for (int i = 0; i < 90; ++i)
            f = few.update({1 / 90.f, i < 30 ? 1.2f : 0.f, i == 0 || i == 27, false, false}, crawlAuto) || f;
        check(!f, "two readings capped");
        // a low reading then a high one at once: no cap
        CrawlCap mixed;
        bool mx = false;
        for (int i = 0; i < 300; ++i)
            mx = mixed.update({1 / 90.f, i % 6 < 3 ? 1.2f : 3.f, i % 3 == 0, false, false}, crawlAuto) || mx;
        check(!mx, "alternating low and high readings capped");
        CrawlCap off;
        bool o = false;
        for (int i = 0; i < 300; ++i)
            o = off.update({1 / 90.f, 1.2f, true, true, false}, crawlOff) || o;
        check(!o && off.why() == capOff, "OFF capped");
        // AUTO ignores the floor flag; WITH FLAG takes it (a duct no ray sees), never in a fight
        CrawlCap autoFlag, withFlag, flagFight;
        bool af = false, wf = false, ff = false;
        for (int i = 0; i < 90; ++i) {
            af = autoFlag.update({1 / 90.f, 0, true, true, false}, crawlAuto) || af;
            wf = withFlag.update({1 / 90.f, 0, true, true, false}, crawlWithFlag) || wf;
            ff = flagFight.update({1 / 90.f, 0, true, true, i % 60 == 0}, crawlWithFlag) || ff;
        }
        check(!af && wf && !ff && withFlag.why() == capFlag, "the crawl flag's modes");
        check(std::string(crawlWhyNames[heldByCombat]) == "held off: combat", "why names");
        // NaN never caps or breaks
        CrawlCap nan;
        bool n = false;
        for (int i = 0; i < 90; ++i)
            n = nan.update({std::nanf(""), std::nanf(""), true, false, false}, crawlAuto) || n;
        check(!n, "NaN capped");
    });
