    test("Update 38 SpidyVR: BALL FIRE PRESS shoots one ball on a still hold; RELEASE waits for the tap", [combatFrame] {
        using namespace combat_input;
        Config c;
        const auto hold = [&](const Config& config, int frames) {
            Machine m;
            Frame f = combatFrame();
            int balls{};
            for (int i = 0; i < frames; ++i) {
                f.hands[0].button = i >= 5 && i < 5 + 60 ? 1.f : 0.f;
                const auto o = m.update(f, config);
                balls += o.fired[0] == combat_input::webShooter;
            }
            return balls;
        };
        check(hold(c, 120) == 1, "a still one-second hold under PRESS was not one web ball");
        Config release = c;
        release.ballOnPress = false;
        check(hold(release, 120) == 0, "RELEASE shot a ball on a long hold");
    });
