    test("Update 38.5: HERO SWITCH PROBE times a real switch's re-attach, read-only", [] {
        hero_switch::Watch w;
        double t = 0;
        auto run = [&](uint64_t hero, double ms, bool view, bool body, bool screen) {
            for (double end = t + ms; t < end; t += 10)
                w.frame(hero, hero ? hero + 8 : 0, t, view, body, screen);
        };
        run(0x1000, 500, true, true, false); // Peter, found at the start: not a switch
        check(w.data().swaps == 0, "the first hero found counted as a switch");
        run(0, 800, false, false, true);     // the switch's fade: no hero
        run(0x2000, 300, false, false, true); // Miles, the view not back yet
        check(w.data().swaps == 1 && w.data().pending == 1, "the switch was not seen");
        check(w.data().lastGapMs >= 790 && w.data().lastGapMs <= 810, "the no-hero gap");
        check(w.data().lastHero == 0x1000 && w.data().hero == 0x2000, "the heroes before and after");
        run(0x2000, 200, true, true, false);
        check(w.data().lastViewMs >= 290 && w.data().lastViewMs <= 310 && w.data().lastBodyMs >= 290 &&
                  w.data().lastBodyMs <= 310, "the view / body back times");
        run(0x2000, hero_switch::backSeconds * 1000, true, true, false);
        check(w.data().pending == 0 && w.data().viewBack == 1 && w.data().bodyBack == 1 && w.data().screenAfter == 0,
              "the switch's outcome");
        run(0x3000, 100, false, false, true); // straight to another (no gap), never back
        run(0x3000, hero_switch::backSeconds * 1000 + 20, false, false, true);
        check(w.data().swaps == 2 && w.data().lastGapMs == 0 && w.data().lastViewMs < 0 && w.data().lastBodyMs < 0 &&
                  w.data().screenAfter == 1 && w.data().viewBack == 1,
              "a switch VR did not come back from");
        uint32_t seen = 0;
        check(w.swapStarted(seen) && !w.swapStarted(seen), "swapStarted");
        check(sizeof(hero_switch::Data) == 112 && hero_switch::Data{}.magic == 0x50575348, "the HSWP layout");
    });
