    test("Update 38.3: GRAB WEB ASSIST takes an enemy 8 degrees off the ray (EXACT misses), never 20 or past 15 m", [] {
        std::array<Vec3, 4> enemies{};
        const Vec3 origin{0, 1.3f, 0};
        const auto off = [&](float degrees, float metres) {
            const float r = degrees * 3.14159265f / 180;
            // his feet, so that his chest (centre mass) is at the hand's height
            enemies[0] = origin + Vec3{std::sin(r) * metres, -combat38::centreMass, -std::cos(r) * metres};
        };
        off(8, 6);
        bool assisted{};
        float metres{};
        check(combat38::grabTarget(origin, {0, 0, -1}, enemies, 1) < 0, "EXACT is expected to miss at 8 degrees, 6 m");
        check(combat38::grabAssistTarget(origin, {0, 0, -1}, enemies, 1, true, &metres, &assisted) == 0 && assisted &&
                  std::abs(metres - 6) < .05f,
              "ASSIST did not take the enemy 8 degrees off");
        check(combat38::grabAssistTarget(origin, {0, 0, -1}, enemies, 1, false) < 0, "EXACT (assist off) took him");
        off(20, 6);
        check(combat38::grabAssistTarget(origin, {0, 0, -1}, enemies, 1, true) < 0, "ASSIST took an enemy 20 degrees off");
        off(5, 18);
        check(combat38::grabAssistTarget(origin, {0, 0, -1}, enemies, 1, true) < 0, "ASSIST took an enemy past 15 m");
    });
