    test("0.0.5 BATON CHAIN (0.0.62: 2 bounces, 5 m): at most batonMaxChains chains, never the same enemy twice, home after, home at once with none in range", [] {
        using namespace spidy::hero_modes;
        const float dt = 1.f / 90;
        const Vec3 hand{0, 1.4f, 0};
        // Five enemies in a line 3 m apart (each within 5 m of the next): 0.0.62 stops at 3.
        BatonEnemy five[5] = {{11, {0, 1.2f, -4}}, {12, {3, 1.2f, -4}}, {13, {6, 1.2f, -4}}, {14, {9, 1.2f, -4}},
                              {15, {12, 1.2f, -4}}};
        Baton b;
        uint32_t hitFrames = 0;
        b.update(dt, true, hand, {0, 0, -1}, five, 5, 0);
        std::vector<uint64_t> order;
        for (int i = 0; i < 3000 && !b.inHandNow(); ++i) {
            const uint64_t aimingAt = b.targetId;
            if (b.update(dt, false, hand, {0, 0, -1}, five, 5, 0)) {
                ++hitFrames;
                order.push_back(aimingAt);
            }
        }
        check(hitFrames == 3 && b.chains == 2 && b.chainEnds == 1, "the chain did not stop at 2 bounces (3 enemies)");
        check(order.size() == 3 && order[0] == 11 && order[1] == 12 && order[2] == 13,
              "the chain did not go to the nearest other enemy each time");
        check(b.inHandNow() && b.catches == 1, "the baton did not come home after the chain");
        bool repeat = false;
        for (size_t i = 0; i < order.size(); ++i)
            for (size_t j = i + 1; j < order.size(); ++j)
                repeat |= order[i] == order[j];
        check(!repeat, "the chain hit the same enemy twice on one throw");
        // Two enemies close together: it never goes back to the first (only 1 chain, then home).
        BatonEnemy two[2] = {{21, {0, 1.2f, -4}}, {22, {2, 1.2f, -4}}};
        Baton p;
        p.update(dt, true, hand, {0, 0, -1}, two, 2, 0);
        uint32_t pHits = 0;
        for (int i = 0; i < 3000 && !p.inHandNow(); ++i)
            pHits += p.update(dt, false, hand, {0, 0, -1}, two, 2, 0);
        check(pHits == 2 && p.chains == 1 && p.chainNoneInRange == 1 && p.inHandNow(), "a pair: not hit once each then home");
        // None in range (the other is 10 m away): home at once after the first hit.
        BatonEnemy apart[2] = {{31, {0, 1.2f, -4}}, {32, {10, 1.2f, -4}}};
        Baton n;
        n.update(dt, true, hand, {0, 0, -1}, apart, 2, 0);
        uint32_t nHits = 0;
        bool turnedHome = false;
        for (int i = 0; i < 3000 && !n.inHandNow(); ++i) {
            if (n.update(dt, false, hand, {0, 0, -1}, apart, 2, 0)) {
                ++nHits;
                turnedHome = n.state == returning;
            }
        }
        check(nHits == 1 && turnedHome && n.chains == 0 && n.chainNoneInRange == 1 && n.inHandNow(),
              "with none in range it did not head home at once");
        // A miss (nobody aimed, nobody near the line) still comes home and chains nothing.
        Baton m;
        m.update(dt, true, hand, {0, 0, -1}, nullptr, 0, -1);
        for (int i = 0; i < 3000 && !m.inHandNow(); ++i)
            m.update(dt, false, hand, {0, 0, -1}, nullptr, 0, -1);
        check(m.inHandNow() && m.hits == 0 && m.chains == 0 && m.catches == 1, "a miss did not come home");
        // A new throw starts a new chain (last throw's enemies may be hit again).
        b.update(dt, true, hand, {0, 0, -1}, five, 5, 0);
        uint32_t again = 0;
        for (int i = 0; i < 3000 && !b.inHandNow(); ++i)
            again += b.update(dt, false, hand, {0, 0, -1}, five, 5, 0);
        check(again == 3 && b.chains == 4, "the second throw did not chain afresh");
        check(b.chainTarget({0, 0, 0}, nullptr, 0) == -1, "an empty list chose an enemy");
    });
    test("Version 0.0.62: BEACONS IN VISION - bright coloured beacons stay in colour in the sonar; lamps and OFF as 0.0.6", [] {
        using namespace spidy;
        using C = std::array<float, 3>;
        // A 100x100 eye: dark street, a vivid yellow beacon (8x8) at (50,40), a white lamp at (20,40).
        auto scene = [](int x, int y) -> C {
            if (std::abs(x - 50) < 4 && std::abs(y - 40) < 4)
                return {1.f, .85f, .1f};
            if (std::abs(x - 20) < 4 && std::abs(y - 40) < 4)
                return {.95f, .93f, .9f};
            return {.08f, .08f, .09f};
        };
        const C off = eye_color::sonarPixel(scene, 50, 40, 100, 100, 0.f, false);
        const C on = eye_color::sonarPixel(scene, 50, 40, 100, 100, 0.f, true);
        check(off[0] < .2f && off[2] < .1f, "0.0.6's sonar darkened the beacon's middle (the problem)");
        check(on[0] > .8f && on[1] > .65f && on[2] < .3f, "BEACONS IN VISION: the beacon is not bright yellow");
        // Its outline: a pixel just outside it takes its colour.
        const C rim = eye_color::sonarPixel(scene, 55, 40, 100, 100, 0.f, true);
        check(rim[1] > .3f && rim[1] > eye_color::sonarPixel(scene, 55, 40, 100, 100, 0.f, false)[1], "no outline round the beacon");
        // A white lamp (not saturated) keeps the sonar look: the same with BEACONS on or off.
        const C lampOn = eye_color::sonarPixel(scene, 20, 40, 100, 100, 0.f, true),
                lampOff = eye_color::sonarPixel(scene, 20, 40, 100, 100, 0.f, false);
        check(std::fabs(lampOn[0] - lampOff[0]) < 1e-5f && std::fabs(lampOn[1] - lampOff[1]) < 1e-5f, "a white lamp was kept");
        // The dark street is untouched.
        const C road = eye_color::sonarPixel(scene, 80, 80, 100, 100, 0.f, true),
                roadOff = eye_color::sonarPixel(scene, 80, 80, 100, 100, 0.f, false);
        check(road == roadOff, "the road changed");
        // The pulse is gentle (0.8-1.0) and NaN-safe; a dim coloured pixel is not a beacon.
        check(eye_color::beaconPulse(.5f) <= 1.0001f && eye_color::beaconPulse(1.5f) >= .799f && std::isfinite(eye_color::beaconPulse(1e30f)) && eye_color::beaconPulse(1e30f) >= .79f,
              "the pulse");
        check(eye_color::beaconMask({.3f, .1f, .05f}) == 0.f && eye_color::beaconMask({.2f, .2f, .2f}) == 0.f &&
                  eye_color::beaconMask({NAN, 1.f, 0.f}) >= 0.f,
              "dim colour or grey counted as a beacon");
        // The setting: ON by default, live; the sonar's mode says so (2), OFF is 0.0.6's (1).
        check(combat38::beaconsInVision(0) && !combat38::beaconsInVision(1) &&
                  std::string(combat38::valueName(combat38::beaconsVision, 0)) == "ON",
              "BEACONS IN VISION ON by default");
        eye_color::Config c;
        c.on = c.sonar = true;
        check(eye_color::toon(c).sonar == 1.f, "OFF: 0.0.6's sonar");
        c.sonarBeacons = true;
        check(eye_color::toon(c).sonar == 2.f, "ON: the sonar's beacon mode");
    });
    test("Version 0.0.62: PLASMA FLICKER - the beams shimmer 0.76-1.0, never dark, never NaN", [] {
        using namespace spidy::repulsor_mcu;
        float lo = 2.f, hi = -1.f;
        for (int i = 0; i < 6000; ++i) {
            const float f = plasmaFlicker(static_cast<float>(i) * .0137f, static_cast<unsigned>(i % 7));
            lo = std::min(lo, f);
            hi = std::max(hi, f);
        }
        check(lo >= .759f && hi <= 1.0001f, "flicker stays 0.76-1.0");
        check(hi - lo > .1f, "it actually flickers");
        check(plasmaFlicker(std::nanf("")) == 1.f && plasmaFlicker(INFINITY) == 1.f, "not finite: steady");
        check(plasmaFlicker(1.f, 0u) != plasmaFlicker(1.f, 41u), "beams flicker out of step");
    });
    test("Version 0.0.62: PALM BLAST - Iron Man's hand repulsor leaves the palm along its normal; webs keep the shooter axis", [] {
        using namespace spidy;
        auto near = [](Vec3 a, Vec3 b) { return length(a - b) < 1e-4f; };
        const Pose level{{0, 1, 0}, {0, 0, 0, 1}};
        // OpenXR grip +X: out of the LEFT palm, into the RIGHT one.
        check(near(repulsor::palmNormal(level, 0), {1, 0, 0}), "left palm: grip +X");
        check(near(repulsor::palmNormal(level, 1), {-1, 0, 0}), "right palm: grip -X (mirrored)");
        check(near(repulsor::palmCentre(level, 0), {repulsor::palmOut, 1, 0}) &&
                  near(repulsor::palmCentre(level, 1), {-repulsor::palmOut, 1, 0}),
              "the palm's centre, 3.5 cm out on the palm's side");
        // Palm turned to face forward (-Z): the right hand rolled +90 deg about the grip's -Y (the
        // forearm), i.e. a grip turned -90 deg about world Y; the left the mirror (+90 deg).
        const float h = .70710678f;
        const Pose rightFwd{{0, 1, 0}, {0, -h, 0, h}}, leftFwd{{0, 1, 0}, {0, h, 0, h}};
        check(near(repulsor::palmNormal(rightFwd, 1), {0, 0, -1}), "right palm facing forward fires forward");
        check(near(repulsor::palmNormal(leftFwd, 0), {0, 0, -1}), "left palm facing forward fires forward");
        // Palm down (MCU hover): the right palm rolled about the grip's Z.
        const Pose rightDown{{0, 1, 0}, {0, 0, h, h}};
        check(near(repulsor::palmNormal(rightDown, 1), {0, -1, 0}), "right palm down fires down");
        // The web shooter's axis (aim_axis HAND) is not the palm: Spider-Man keeps it.
        const Vec3 web = combat38::aimOf(level, level, combat38::axisHand);
        check(near(web, {0, -1, 0}) && std::fabs(dot(web, repulsor::palmNormal(level, 1))) < 1e-4f,
              "the web shooter axis moved");
        // A broken pose: no direction (the blast falls back to the assisted aim).
        check(length(repulsor::palmNormal(Pose{{0, 0, 0}, {0, 0, 0, 0}}, 0)) == 0.f, "a broken grip gave a palm");
        // Aim assist still bends a palm blast onto a foe near its line, from the palm.
        our_ball::Pool shooter;
        our_ball::Enemies foes{};
        foes.count = 1;
        foes.list[0].id = 7;
        foes.list[0].feet = {0, 0, -8};
        const Vec3 from = repulsor::palmCentre(rightFwd, 1);
        check(shooter.fire(1, from, repulsor::palmNormal(rightFwd, 1), foes, 0, 0), "the palm blast fired");
    });
    test("Version 0.0.73 (fix 14): the mirror shows the hero's props, reflected (Spider-Man's figure and every suit)", [] {
        namespace vm = spidy::vr_mirror;
        vm::Plane m;
        m.valid = true;
        m.centre = {0, 1, -2};
        m.normal = {0, 0, 1};
        m.up = {0, 1, 0};
        m.right = {1, 0, 0};
        m.scale = .8f;
        const Vec3 p{.3f, 1.2f, -.5f};
        const Vec3 back = vm::unreflect(m, vm::reflect(m, p));
        check(length(back - p) < 1e-5f, "unreflect undoes reflect");
        check(vm::reflect(m, p).z < m.centre.z, "a prop in front of the mirror is seen behind it");
        std::vector<Vertex> v{{p, {1, 1, 1}}, {{0, 1, 0}, {1, 1, 1}}};
        check(vm::reflectVertices(m, v, 1) && length(v[0].position - p) < 1e-6f && v[1].position.z < -2.f,
              "only the props' vertices are reflected");
        v.push_back({{std::nanf(""), 0, 0}, {1, 1, 1}});
        check(!vm::reflectVertices(m, v, 1) && v.size() == 1, "a broken vertex: none of them drawn");
        m.valid = false;
        v.push_back({p, {1, 1, 1}});
        check(!vm::reflectVertices(m, v, 1) && v.size() == 1, "no mirror: nothing reflected");
    });
    test("Version 0.0.73 (fix 10): every Wolverine suit's claws are the JACKET AND JEANS claws, retractable, never doubled", [] {
        namespace mm = spidy::mesh_model;
        namespace h7 = spidy::hero007;
        check(std::string(mm::slotFolders[mm::slotClawsLeft]) == "Claws/Left" && std::string(mm::slotFolders[mm::slotClawsRight]) == "Claws/Right" &&
                  !mm::slotIsSuit(mm::slotClawsLeft) && !mm::slotIsSuit(mm::slotClawsRight) && mm::slotIsSuit(mm::slotSuitEnd - 1),
              "the claws' folders follow the suits, and are not suits");
        // A claw in its own frame: base at the origin, 0.36 m along -z.
        mm::Mesh claw;
        claw.corners = {{0, 0, 0}, {.01f, 0, -.36f}, {-.01f, .01f, -.36f}};
        claw.colors = {{.8f, .8f, .8f}};
        claw.low = {-.01f, 0, -.36f};
        claw.high = {.01f, .01f, 0};
        h7::Item it{};
        it.look = h7::lookClaws;
        it.at = {0, 1, 0};
        it.forward = {0, 0, -1};
        it.up = {0, 1, 0};
        it.spin = 1.f;
        const Vec3 viewer{0, 1.6f, 1};
        std::vector<Vertex> out;
        check(h7::appendClawModel(out, it, claw, viewer) && !out.empty(), "out: drawn");
        float reach = 0;
        for (const Vertex& v : out)
            reach = std::max(reach, -v.position.z);
        check(reach > .36f && reach < .36f + h7::clawKnuckle + .05f, "out: the full claw past the knuckles");
        out.clear();
        it.spin = .5f;
        check(h7::appendClawModel(out, it, claw, viewer), "half out: drawn");
        float half = 0;
        for (const Vertex& v : out)
            half = std::max(half, -v.position.z);
        check(half < reach - .1f, "half out: shorter (it slides out of the knuckles)");
        out.clear();
        it.spin = .01f;
        check(h7::appendClawModel(out, it, claw, viewer) && out.empty(), "in: nothing shows, and no built-in claws either");
        mm::Mesh huge = claw;
        huge.high.z = 5;
        check(!h7::appendClawModel(out, it, huge, viewer), "not a claws model (too big): the built-in claws instead");
        // The draw: lookClaws by its side's model; a missing model keeps the built-in claws.
        h7::Draw d{};
        d.any = true;
        d.held[0] = it;
        d.held[0].spin = 1.f;
        d.held[0].side = 0;
        std::vector<Vertex> built, modelled;
        h7::appendHero007(built, d, {}, viewer, .002f);
        d.clawModel[0] = &claw;
        h7::appendHero007(modelled, d, {}, viewer, .002f);
        check(!built.empty() && !modelled.empty() && built.size() != modelled.size(), "the model replaces the built-in claws (never both)");
    });
    test("Version 0.0.73 (fix 15/16): Iron Man's palm faces the aim, the blast leaves the palm, a visible beam", [] {
        using namespace spidy;
        auto near = [](Vec3 a, Vec3 b) { return length(a - b) < 1e-3f; };
        const Pose level{{0, 1, 0}, {0, 0, 0, 1}};
        const Vec3 ahead{0, 0, -1};
        check(near(repulsor::palmAim(level, 1, ahead), ahead), "the blast goes along the controller's aim");
        check(near(repulsor::palmAim(level, 0, {0, 0, 0}), repulsor::palmNormal(level, 0)), "no aim: the palm's normal");
        check(near(repulsor::palmFrom(level, 1, ahead), {0, 1, -repulsor::palmAhead}), "from the palm, ahead of the grip");
        for (unsigned hand = 0; hand < 2; ++hand) {
            repulsor::PalmFrame f;
            check(repulsor::palmFrame(ahead, {0, 1, 0}, hand, f), "a palm frame");
            // suit_wear: the back of the hand is -X (left) / +X (right): it must face away from the aim.
            const Vec3 back = hand == 0 ? f.x * -1.f : f.x;
            check(near(back, {0, 0, 1}), "the back of the hand faces away from the aim (palm to the aim)");
            check(near(f.up * -1.f, {0, 1, 0}), "the fingers point up");
            check(std::fabs(dot(f.forward, f.x)) < 1e-3f && std::fabs(dot(f.forward, f.up)) < 1e-3f &&
                      near(cross(f.x, f.up), f.forward * -1.f),
                  "a right-handed grip frame");
        }
        repulsor::PalmFrame f;
        check(!repulsor::palmFrame({0, 1, 0}, {0, 1, 0}, 1, f), "aimed straight up: the hand as held");
        check(!repulsor::palmFrame({NAN, 0, 0}, {0, 1, 0}, 1, f), "a broken aim: the hand as held");
        std::vector<Vertex> v;
        appendRepulsorBeam(v, {0, 1, -.1f}, {0, 1, -20}, {0, 1.6f, 0}, .001f, 1.f);
        check(!v.empty(), "the repulsor beam is drawn");
        const size_t n = v.size();
        appendRepulsorBeam(v, {0, 1, 0}, {0, 1, -.05f}, {0, 1.6f, 0}, .001f, 1.f);
        appendRepulsorBeam(v, {NAN, 1, 0}, {0, 1, -5}, {0, 1.6f, 0}, .001f, 1.f);
        appendRepulsorBeam(v, {0, 1, 0}, {0, 1, -5}, {0, 1.6f, 0}, .001f, 0.f);
        check(v.size() == n, "nothing for a short, broken or faded beam");
    });
    test("Version 0.0.62: BATON BOUNCE - 3 enemies at most within 5 m, no repeats, none down, always home", [] {
        using namespace spidy::hero_modes;
        check(batonChainRange == 5.f && batonMaxChains + 1 == 3, "3 enemies in all, 5 m");
        const float dt = 1.f / 90;
        const Vec3 hand{0, 1.4f, 0};
        auto throwAt = [&](BatonEnemy* list, uint32_t n, int aimed, std::vector<uint64_t>& order, Baton& b) {
            b.update(dt, true, hand, {0, 0, -1}, list, n, aimed);
            bool sawReturn = false;
            for (int i = 0; i < 3000 && !b.inHandNow(); ++i) {
                const uint64_t at = b.targetId;
                if (b.update(dt, false, hand, {0, 0, -1}, list, n, aimed))
                    order.push_back(at);
                sawReturn |= b.state == returning;
            }
            return sawReturn;
        };
        auto noRepeats = [](const std::vector<uint64_t>& o) {
            for (size_t i = 0; i < o.size(); ++i)
                for (size_t j = i + 1; j < o.size(); ++j)
                    if (o[i] == o[j])
                        return false;
            return true;
        };
        {   // 3 in range (2 m apart): 3 hits, then home.
            BatonEnemy three[3] = {{41, {0, 1.2f, -4}}, {42, {2, 1.2f, -4}}, {43, {4, 1.2f, -4}}};
            Baton b; std::vector<uint64_t> o;
            const bool back = throwAt(three, 3, 0, o, b);
            check(o.size() == 3 && o[0] == 41 && o[1] == 42 && o[2] == 43 && noRepeats(o), "3 in range: 3 hits in order");
            check(back && b.inHandNow() && b.catches == 1 && b.timeouts == 0, "3 in range: then back in the hand");
        }
        {   // 1 in range (the others 7 m and more away): 1 hit, then home.
            BatonEnemy far[3] = {{51, {0, 1.2f, -4}}, {52, {7, 1.2f, -4}}, {53, {-8, 1.2f, -4}}};
            Baton b; std::vector<uint64_t> o;
            throwAt(far, 3, 0, o, b);
            check(o.size() == 1 && o[0] == 51 && b.chainNoneInRange == 1 && b.inHandNow() && b.timeouts == 0,
                  "1 in range: 1 hit, then home at once");
        }
        {   // 0: a throw at nobody comes straight back.
            Baton b; std::vector<uint64_t> o;
            const bool back = throwAt(nullptr, 0, -1, o, b);
            check(o.empty() && back && b.inHandNow() && b.hits == 0 && b.catches == 1, "0 in range: straight back");
        }
        {   // Never one down (dead or knocked out): the down one 2 m away is skipped for the one 4 m away.
            BatonEnemy mixed[3] = {{61, {0, 1.2f, -4}}, {62, {2, 1.2f, -4}, true}, {63, {4, 1.2f, -4}}};
            Baton b; std::vector<uint64_t> o;
            throwAt(mixed, 3, 0, o, b);
            check(o.size() == 2 && o[0] == 61 && o[1] == 63 && noRepeats(o), "a downed enemy is skipped");
            // A target who goes down while it flies: home, no hit.
            BatonEnemy one[1] = {{71, {0, 1.2f, -8}}};
            Baton c;
            c.update(dt, true, hand, {0, 0, -1}, one, 1, 0);
            for (int i = 0; i < 5; ++i)
                c.update(dt, false, hand, {0, 0, -1}, one, 1, 0);
            one[0].down = true;
            uint32_t hits = 0;
            for (int i = 0; i < 3000 && !c.inHandNow(); ++i)
                hits += c.update(dt, false, hand, {0, 0, -1}, one, 1, 0);
            check(hits == 0 && c.targetDowns == 1 && c.inHandNow(), "a target who went down: home, no hit");
            check(Baton::sweepHit({0, 1.2f, -1}, {0, 1.2f, -7}, mixed + 1, 1) == -1, "a straight throw passes a downed body");
        }
        {   // Two close together: never back to the first (no repeats), and the hand never waits past batonMaxOut.
            BatonEnemy two[2] = {{81, {0, 1.2f, -4}}, {82, {1, 1.2f, -4}}};
            Baton b; std::vector<uint64_t> o;
            throwAt(two, 2, 0, o, b);
            check(o.size() == 2 && noRepeats(o), "a pair: each once");
            // An enemy who runs away as fast as it flies: the timeout brings it home.
            Baton r;
            BatonEnemy runner[1] = {{91, {0, 1.2f, -4}}};
            r.update(dt, true, hand, {0, 0, -1}, runner, 1, 0);
            int frames = 0;
            for (; frames < 3000 && !r.inHandNow(); ++frames) {
                runner[0].chest.z -= batonSpeed * dt * 1.01f;
                r.update(dt, false, hand, {0, 0, -1}, runner, 1, 0);
            }
            check(r.inHandNow() && frames <= static_cast<int>(batonMaxOut * 90) + 2, "the baton always comes back");
        }
    });
    test("0.0.5 HERO HEIGHT: 1.00X changes nothing, the eyes rise along up, the arm grows, limits clamp", [] {
        using namespace spidy::hero_height;
        check(factorOf(0) == 1.f && factorOf(4) == 1.6f && factorOf(99) == 1.f, "the values' factors");
        check(clampFactor(.5f) == 1.f && clampFactor(3.f) == 1.6f && clampFactor(std::nanf("")) == 1.f,
              "the factor is not clamped to 1.00-1.60");
        const Targets t{{.05f, 1.62f, .1f}, 1.62f, .7f};
        const Targets same = scaled(t, {0, 1, 0}, 1.f);
        check(same.eyes.x == t.eyes.x && same.eyes.y == t.eyes.y && same.eyes.z == t.eyes.z && same.height == t.height &&
                  same.armLength == t.armLength,
              "1.00X changed the body");
        const Targets big = scaled(t, {0, 1, 0}, 1.3f);
        check(std::fabs(big.eyes.y - (1.62f + .3f * 1.62f)) < 1e-4f && big.eyes.x == t.eyes.x && big.eyes.z == t.eyes.z,
              "the eyes did not rise straight up by (k-1) x height");
        check(std::fabs(big.height - 1.62f * 1.3f) < 1e-4f && std::fabs(big.armLength - .7f * 1.3f) < 1e-4f,
              "height and arm did not grow k times");
        // Along a tilted up (a wall run's body up), not world y.
        const Targets wall = scaled(t, {1, 0, 0}, 1.6f);
        check(std::fabs(wall.eyes.x - (.05f + .6f * 1.62f)) < 1e-4f && wall.eyes.y == t.eyes.y, "not along the body's up");
        // A bad up falls back to world up; an unknown height (0) changes nothing; arm 0 stays the hero's own.
        const Targets bad = scaled(t, {0, 0, 0}, 1.6f);
        check(std::fabs(bad.eyes.y - (1.62f + .6f * 1.62f)) < 1e-4f, "a zero up was used");
        const Targets unknown = scaled({{0, 1, 0}, 0.f, .7f}, {0, 1, 0}, 1.6f);
        check(unknown.height == 0 && unknown.eyes.y == 1 && unknown.armLength == .7f, "an unknown height was scaled");
        check(scaled({{0, 1.6f, 0}, 1.6f, 0.f}, {0, 1, 0}, 1.6f).armLength == 0, "the hero's own arm was replaced");
        // The body's limits grow with k (never cut back to Spider-Man's), unchanged at 1.00X.
        check(maxScale(1.3f, 1.f) == 1.3f && std::fabs(maxScale(1.3f, 1.6f) - 2.08f) < 1e-5f, "the scale limit");
        check(maxHeight(1.f) == 2.5f && maxHeight(1.6f) == 4.f && 1.62f * 1.6f < maxHeight(1.6f),
              "a 1.60X tall player is refused by the height check");
        // Every hologram value: the swing/FLY inputs are not in Targets (only the body's targets move).
        for (uint32_t v = 0; v < steps; ++v)
            check(scaled(t, {0, 1, 0}, factorOf(v)).eyes.y >= t.eyes.y, "a step lowered the eyes");
    });
    test("0.0.5 DAMAGE TEST: the melee site's handle, a slot check, the request's fields and masks, the pool check", [] {
        using namespace spidy::sm2_damage;
        check(handleOf(3, 42) == ((3u << 20) | 42u) && handleOf(0xffff, 0xfffffff) == ((0x7ffu << 20) | 0xfffffu),
              "the handle is not the melee site's build");
        const uint64_t table = 0x10000;
        check(isSlot(table + 5 * actorSlotBytes, table, 10, 1, 5), "a live slot was refused");
        check(!isSlot(table + 5 * actorSlotBytes + 8, table, 10, 1, 5), "a slot's middle was taken");
        check(!isSlot(table + 12 * actorSlotBytes, table, 10, 1, 12), "past the count was taken");
        check(!isSlot(table + 5 * actorSlotBytes, table, 10, 0, 5), "generation 0 (no actor) was taken");
        check(!isSlot(table + 5 * actorSlotBytes, table, 10, 1, 6), "a slot with another index was taken");
        check(!isSlot(table - actorSlotBytes, table, 10, 1, 0) && !isSlot(table, 0, 10, 1, 0), "below the table");
        std::vector<unsigned char> req(requestBytes, 0);
        uint32_t pre = 0x4;
        std::memcpy(req.data() + setA, &pre, 4);
        fill(req.data(), {35.f, 5, 100.f, 0x123, meleeType});
        uint32_t type{}, knock{}, damager{}, a{}, b{};
        float amount{}, knockAmount{};
        std::memcpy(&type, req.data() + typeAt, 4);
        std::memcpy(&amount, req.data() + amountAt, 4);
        std::memcpy(&knock, req.data() + knockAt, 4);
        std::memcpy(&knockAmount, req.data() + knockAmountAt, 4);
        std::memcpy(&damager, req.data() + damagerAt, 4);
        std::memcpy(&a, req.data() + setA, 4);
        std::memcpy(&b, req.data() + setB, 4);
        const uint32_t all = typeBit | amountBit | knockBit | knockAmountBit | damagerBit;
        check(type == 7 && amount == 35.f && knock == 5 && knockAmount == 100.f && damager == 0x123, "the fields");
        check(a == (all | 0x4) && b == all, "the masks were not OR'd (or an old bit was lost)");
        std::vector<unsigned char> plain(requestBytes, 0);
        fill(plain.data(), webBallTest());
        std::memcpy(&a, plain.data() + setA, 4);
        std::memcpy(&knock, plain.data() + knockAt, 4);
        check(a == (typeBit | amountBit) && knock == 0, "a blow without knockback or damager set them");
        const uint64_t sys = 0x100000;
        check(poolRequest(sys + 0x68 + 0x1d0, sys) && !poolRequest(sys + spareAt, sys) && !poolRequest(0x50, sys) &&
                  !poolRequest(sys + 0x68 + 0x1d0, 0),
              "the spare or a stranger passed as a pool request");
        float hero[3] = {0, 0, 0}, victim[3] = {3, 0, 4}, dir[3]{};
        directionOf(hero, victim, dir);
        check(std::fabs(dir[0] - .6f) < 1e-5f && std::fabs(dir[2] - .8f) < 1e-5f, "the direction");
        float farV[3] = {0, 0, 9e5f};
        directionOf(hero, farV, dir);
        check(std::fabs(dir[2] - 1.f) < 1e-5f, "a far direction is not unit");
        directionOf(hero, hero, dir);
        check(dir[0] == 0 && dir[1] == 0 && dir[2] == 1, "a zero direction is not straight ahead");
        check(repulsorBlast().amount * 5 >= thugHp && chestBeam().amount >= 4 * repulsorBlast().amount,
              "a thug takes ~5 blasts, the beam 4x a blast or more");
        check(std::string(statusName(off)) == "OFF" && std::string(statusName(confirmed)) == "CONFIRMED", "status names");
    });
    test("0.0.5 DAMAGE PROBE: HP falls after X are CONFIRMED punches, ours alone the mod's, knockouts, the ring", [] {
        using namespace spidy::damage_probe;
        Tracker t;
        Sample s[2] = {{1, 100, 100, true}, {2, 300, 300, true}};
        t.update(1000, s, 2, 0, 0, false);
        check(t.healthState == 1 && t.writeState == 0 && t.enemiesRead == 2 && t.falls == 0, "first read");
        s[0].hp = 70; // no X press: unexplained
        t.update(1100, s, 2, 0, 0, false);
        check(t.falls == 1 && t.fallsUnexplained == 1 && t.healthState == 1, "an unexplained fall confirmed punches");
        s[0].hp = 40; // 300 ms after X
        t.update(2000, s, 2, 1700, 0, false);
        check(t.healthState == 2 && t.fallsMelee == 1 && t.recent[1].cause == melee && t.recent[1].delayMs == 300,
              "a fall after X was not CONFIRMED");
        s[0].hp = 30; // X press 1.5 s ago: outside the window
        t.update(3200, s, 2, 1700, 0, false);
        check(t.fallsMelee == 1 && t.fallsUnexplained == 2, "a fall long after X counted as a punch");
        s[1].hp = 200; // our blow, no X in the window
        t.update(4000, s, 2, 1700, 3900, true);
        check(t.writeState == 2 && t.fallsOurs == 1 && t.recent[3].cause == ours, "the mod's blow was not CONFIRMED");
        s[0].hp = 0; // knocked out by a punch
        t.update(5000, s, 2, 4900, 3900, true);
        check(t.knockouts == 1 && t.recent[4].knockedOut == 1 && t.biggestFall == 100, "a knockout");
        s[0].hp = 50;
        t.update(6000, s, 2, 0, 0, true);
        check(t.rises == 1, "a rise (healed / respawned)");
        Tracker w;
        Sample one[1] = {{9, 100, 100, true}};
        w.update(10, one, 1, 0, 0, true);
        check(w.writeState == 1, "a blow sent is not reported as sent");
        // Both X and our blow in the window: a punch (never the mod's confirmation).
        one[0].hp = 80;
        w.update(500, one, 1, 400, 450, true);
        check(w.writeState == 1 && w.healthState == 2, "a fall with X too confirmed the mod's write");
        // The ring keeps the last 8.
        for (int i = 0; i < 20; ++i) {
            one[0].hp -= 1;
            w.update(1000 + static_cast<uint64_t>(i) * 100, one, 1, 0, 0, true);
        }
        check(w.nextEvent == 21 && w.recent[(w.nextEvent - 1) % spidy::damage_probe::events].after == one[0].hp, "the ring");
        // Bad samples are skipped; more enemies than slots never overflow.
        Sample bad[3] = {{0, 5, 5, true}, {7, std::nanf(""), 5, true}, {8, 5, 0, true}};
        const uint64_t before = w.samples;
        w.update(9000, bad, 3, 0, 0, true);
        check(w.samples == before, "a bad sample was read");
        Sample many[40]{};
        for (uint32_t i = 0; i < 40; ++i)
            many[i] = {100 + i, 50, 50, true};
        w.update(9100, many, 40, 0, 0, true);
        check(w.enemiesRead >= 41, "more enemies than slots");
        check(std::string(stateName(2)) == "CONFIRMED", "state names");
    });
