    test("0.0.5 BEAM RING: the right wrist's ring fills over 30 s, flashes when ready, never draws junk", [] {
        using namespace spidy;
        using namespace spidy::repulsor;
        Trigger t;
        bool press[2]{}, held[2]{true, true};
        Vec3 aim[2]{{0, 0, -1}, {0, 0, -1}};
        float now = 0;
        bool readySeen = false;
        float shares[4]{};
        auto step = [&](float seconds, bool both) {
            for (float e = 0; e < seconds; e += 1.f / 90.f) {
                now += 1.f / 90.f;
                press[0] = press[1] = both && e < .012f;
                held[0] = held[1] = both;
                readySeen = t.update(now, press, aim, held).ready || readySeen;
            }
        };
        check(chargeShare(t) == 1.f, "full before any beam");
        step(.7f, true);
        step(.2f, false);
        check(t.beams() == 1 && chargeShare(t) < .04f, "the beam did not empty it");
        step(7.5f, false);
        shares[0] = chargeShare(t);
        step(7.5f, false);
        shares[1] = chargeShare(t);
        step(7.5f, false);
        shares[2] = chargeShare(t);
        check(std::fabs(shares[0] - .25f) < .04f && std::fabs(shares[1] - .5f) < .04f && std::fabs(shares[2] - .75f) < .04f,
              "not filling evenly over 30 s");
        check(!readySeen, "ready too early");
        step(8.f, false);
        shares[3] = chargeShare(t);
        check(readySeen && shares[3] == 1.f, "not full and ready after 30 s");
        check(readyFlash(0) == 1.f && readyFlash(.6f) > .4f && readyFlash(.6f) < .6f && readyFlash(readyFlashSeconds) == 0 &&
                  readyFlash(-1) == 0 && readyFlash(std::nanf("")) == 0, "the ready flash");
        // Its look: some vertices on the wrist, more while flashing; none for junk or too near/far.
        Pose hand{{.2f, 1.1f, -.3f}, {}};
        const Vec3 eye{0, 1.6f, 0};
        std::vector<Vertex> cooling, readyNow, flashing, junk;
        appendBeamRing(cooling, .4f, 0, hand, eye, .001f, 1);
        appendBeamRing(readyNow, 1, 0, hand, eye, .001f, 1);
        appendBeamRing(flashing, 1, 1, hand, eye, .001f, 1);
        check(!cooling.empty() && !readyNow.empty() && flashing.size() > readyNow.size(), "the ring draws nothing");
        float far = 0;
        for (const auto& v : cooling)
            far = std::max(far, length(v.position - (hand.position + Vec3{0, .045f, .065f})));
        check(far < .03f, "the ring is not on the wrist (it floats)");
        appendBeamRing(junk, std::nanf(""), 0, hand, eye, .001f, 1);
        appendBeamRing(junk, .5f, 0, Pose{{0, 1.6f, -.02f}, {}}, eye, .001f, 1);
        appendBeamRing(junk, .5f, 0, Pose{{0, 1.6f, -9.f}, {}}, eye, .001f, 1);
        appendBeamRing(junk, .5f, 0, hand, eye, std::nanf(""), 1);
        check(junk.empty(), "the ring drew junk");
    });
    test("0.0.5 FLY: FAST is 40 m/s; SUPERSONIC dashes hands-out with the left stick, booms once, then FLY as before", [] {
        using namespace spidy;
        using namespace spidy::extras385::fly;
        check(speeds[1] == 8 && speeds[2] == 16 && speeds[3] == 40, "FAST is not 40 m/s (SLOW, NORMAL unchanged)");
        check(supersonicTop <= native_movement::motionCeiling && native_movement::motionCeiling <= 120 &&
                  game_swing::motionSpeedLimit == 65, "the movement ceiling");
        // SUPERSONIC SPEED: 2X default, every value a different speed under the ceiling.
        float last = -1;
        for (uint32_t v : {1u, 0u, 2u, 3u}) {
            const float s = fly_boost::speedOf(v);
            check(s > last && s <= supersonicTop, "SUPERSONIC SPEED values are not distinct speeds");
            last = s;
        }
        check(fly_boost::speedOf(0) == 80 && fly_boost::speedOf(3) == 120 && combat38::supersonicK(9) == 2,
              "SUPERSONIC SPEED's speeds");
        // The asks bits: bit 0 is the game's own move, as before; the dash rides bits 1-3.
        check(fly_boost::asksOf(false, 3) == 0 && fly_boost::multiplierOf(1) == 0 &&
                  fly_boost::multiplierOf(fly_boost::asksOf(true, 0)) == 2 &&
                  fly_boost::multiplierOf(fly_boost::asksOf(true, 3) | 1u) == 3 && (fly_boost::asksOf(true, 3) & 1u) == 0,
              "the asks bits");
        game_swing::Command c;
        c.serial = c.focused = 1;
        c.asks = 1u | fly_boost::asksOf(true, 3);
        check(game_swing::valid(c), "the swing module refuses SUPERSONIC's asks");
        c.asks = 16; // 0.0.6: bit 4 is HULK LEAP
        check(game_swing::valid(c), "the swing module refuses HULK LEAP's ask");
        // Version 0.0.72: bits 5-8 (BATMAN, the grapples, the grapple without the cape) are valid -
        // 0.0.7 refused anything over 31, so BATMAN's own asks made the command invalid.
        c.asks = cape_glide::pack(true, true, true);
        check(game_swing::valid(c), "the swing module refuses BATMAN's asks");
        c.asks = cape_glide::packGrappleOnly(false, true);
        check(game_swing::valid(c) && c.asks == (cape_glide::askGrappleOnly | cape_glide::askGrapple[1]), "the grapple without the cape");
        check(cape_glide::asksMost == game_swing::asksMost && cape_glide::packGrappleOnly(false, false) == 0, "the asks' top");
        c.asks = 512;
        check(!game_swing::valid(c), "junk asks accepted");
        // The Boost: needs ON, flying, hands out and the stick forward; booms once, re-arms after 1 s off.
        fly_boost::Boost b;
        fly_boost::In bi{1 / 90.f, true, true, true, .9f};
        int booms = 0;
        auto run = [&](float seconds) {
            for (float e = 0; e < seconds; e += 1 / 90.f) {
                b.update(bi);
                booms += b.boomed() ? 1 : 0;
            }
        };
        run(1);
        check(b.engaged() && booms == 1 && b.engages() == 1, "the dash did not engage once");
        bi.stickY = .5f; // inside the hysteresis: still on
        run(.3f);
        check(b.engaged() && booms == 1, "the stick's wobble dropped the dash or boomed again");
        bi.stickY = 0;
        run(.3f);
        bi.stickY = .9f;
        run(.3f);
        check(b.engaged() && booms == 1, "a quick re-push boomed again (no re-arm)");
        bi.stickY = 0;
        run(1.2f);
        bi.stickY = .9f;
        run(.2f);
        check(booms == 2 && b.engages() == 2, "the dash did not boom again after a rest");
        for (int k = 0; k < 3; ++k) { // OFF, not flying, hands not out: no dash
            fly_boost::Boost n;
            fly_boost::In ni{1 / 90.f, k != 0, k != 1, k != 2, 1.f};
            bool any = false;
            for (int i = 0; i < 90; ++i)
                any = n.update(ni) || n.boomed() || any;
            check(!any, "the dash without all of ON, flying and hands out");
        }
        fly_boost::Boost nanB;
        check(!nanB.update({1 / 90.f, true, true, true, std::nanf("")}), "a NaN stick dashed");
        // The flight: hands out (FORWARD) at FAST reaches 0.85 x 40; with the dash, 2X = 80 m/s, then back.
        Flight fl;
        In in;
        in.seconds = 1 / 90.f;
        in.airborne = true;
        in.look = {0, 0, -1};
        in.hands[0] = {true, {0, 0, -1}, {-.2f, -.1f, -.4f}};
        in.hands[1] = {true, {0, 0, -1}, {.2f, -.1f, -.4f}};
        in.word = unpack(pack(fast, 0, 0, 0, true, extras385::fly::forward));
        Out o;
        for (int i = 0; i < 180; ++i)
            o = fl.update(in);
        check(std::string(o.how) == "FORWARD" && std::fabs(length(o.velocity) - 40 * Flight::forwardShare) < .5f && !o.supersonic,
              "FAST hands-out speed");
        in.boost = fly_boost::multiplierOf(fly_boost::asksOf(true, 0));
        float jump = 0, before = length(o.velocity);
        for (int i = 0; i < 180; ++i) {
            o = fl.update(in);
            jump = std::max(jump, std::fabs(length(o.velocity) - before));
            before = length(o.velocity);
        }
        check(std::string(o.how) == "SUPERSONIC" && o.supersonic && std::fabs(length(o.velocity) - 80) < .5f && o.top == 80 &&
                  o.velocity.z < 0 && jump < 2.f && o.vignette <= .6f,
              "the SUPERSONIC dash's speed or smoothness");
        in.boost = 5; // never past the top
        for (int i = 0; i < 270; ++i)
            o = fl.update(in);
        check(length(o.velocity) <= supersonicTop + .01f, "the dash passed supersonicTop");
        in.boost = 0;
        for (int i = 0; i < 270; ++i)
            o = fl.update(in);
        check(!o.supersonic && std::fabs(length(o.velocity) - 40 * Flight::forwardShare) < .5f, "FLY did not come back from the dash");
        // A boost word without the hands-out pose changes nothing (the sticks still steer as before).
        Flight a, bfl;
        In s = in;
        s.word = unpack(pack(fast, 0, 0, 0, true, extras385::fly::hover));
        s.move = {0, 0, -1};
        In s2 = s;
        s2.boost = 3;
        Out oa, ob;
        for (int i = 0; i < 120; ++i) {
            oa = a.update(s);
            ob = bfl.update(s2);
        }
        check(std::string(oa.how) == "STICK" && length(oa.velocity - ob.velocity) < 1e-4f && !ob.supersonic,
              "the boost changed FLY outside the hands-out pose");
        // The shockwave: draws for 0.9 s around the eye, nothing for junk.
        check(fly_boost::shock(0) == 1 && fly_boost::shock(.45f) > .4f && fly_boost::shock(.9f) == 0 && fly_boost::shock(-1) == 0 &&
                  fly_boost::shock(std::nanf("")) == 0 && fly_boost::shockSeconds == shockwaveSeconds,
              "the shockwave's life");
        const Vec3 eye{0, 1.6f, 0};
        std::vector<Vertex> early, late, junk;
        appendShockwave(early, eye, {0, 0, -1}, .05f, .001f);
        appendShockwave(late, eye, {0, 0, -1}, .8f, .001f);
        check(!early.empty() && !late.empty(), "the shockwave draws nothing");
        float far = 0;
        for (const auto& v : early)
            far = std::max(far, length(v.position - eye));
        check(far < 6.f, "the shockwave is not around the player");
        appendShockwave(junk, eye, {0, 0, -1}, 1.f, .001f);
        appendShockwave(junk, eye, {0, 0, 0}, .1f, .001f);
        appendShockwave(junk, {std::nanf(""), 0, 0}, {0, 0, -1}, .1f, .001f);
        appendShockwave(junk, eye, {0, 0, -1}, std::nanf(""), .001f);
        check(junk.empty(), "the shockwave drew junk");
    });
    test("Update 39.0.2 REPULSOR LOOK: the palm charges in the chord wait, a tight bolt, a short burst, cheap", [] {
        using namespace spidy::repulsor;
        namespace mcu = spidy::repulsor_mcu;
        Trigger t;
        const Vec3 aim[2] = {{0, 0, -1}, {.1f, 0, -1}};
        const bool none[2] = {false, false}, right[2] = {false, true};
        check(t.chargingFor(0) == -1 && t.chargingFor(1) == -1 && t.sinceBlast(1) == -1 && t.chargingFor(2) == -1 &&
                  t.sinceBlast(-1) == -1,
              "a fresh trigger charges or has blasted");
        t.update(1, right, aim, none);
        check(t.chargingFor(1) == 0 && t.chargingFor(0) == -1, "a press did not start the palm's charge");
        t.update(1 + chordWindow / 2, none, aim, none);
        near(t.chargingFor(1), chordWindow / 2, 1e-5f);
        bool blasted = false;
        float now = 1 + chordWindow / 2;
        for (int k = 0; k < 30 && !blasted; ++k) {
            now += 1.f / 90;
            blasted = t.update(now, none, aim, none).blast[1];
        }
        check(blasted && t.chargingFor(1) == -1 && t.sinceBlast(1) == 0 && t.sinceBlast(0) == -1,
              "the blast did not end the charge");
        t.update(now + .05f, none, aim, none);
        near(t.sinceBlast(1), .05f, 1e-5f);
        // The beam chord: both palms full while it waits.
        Trigger c;
        const bool both[2] = {true, true};
        c.update(5, both, aim, both);
        c.update(5.05f, none, aim, both);
        check(c.chordWaiting() && c.chargingFor(0) >= chordWindow && c.chargingFor(1) >= chordWindow,
              "a waiting chord's palms are not full");
        c.clear();
        check(c.sinceBlast(0) == -1, "clear kept a blast");
        // The glow: rises through the chord window (a quick tap shows), fades after; odd input is none.
        check(mcu::palmGlow(-1, -1) == 0 && mcu::palmGlow(0, -1) == 0 && mcu::palmGlow(chordWindow, -1) == 1 &&
                  mcu::palmGlow(chordWindow / 4, -1) > .25f && mcu::palmGlow(9, -1) == 1,
              "the palm's charge glow");
        check(mcu::palmGlow(-1, 0) == 1 && mcu::palmGlow(-1, mcu::muzzleSeconds / 2) > .4f &&
                  mcu::palmGlow(-1, mcu::muzzleSeconds) == 0 && mcu::palmGlow(std::nanf(""), std::nanf("")) == 0,
              "the palm's fade");
        check(mcu::impactLife(0) == 1 && mcu::impactLife(mcu::impactSeconds) == 0 && mcu::impactLife(-1) == 0 &&
                  mcu::impactLife(std::nanf("")) == 0 && mcu::impactSeconds < .25f,
              "the burst's life");
        // Drawn: two palms, a bolt, a burst within ~3,600 vertices, all finite; odd input draws nothing.
        const Vec3 eye{0, 1.6f, 0};
        std::vector<Vertex> out;
        mcu::appendCharge(out, {-.2f, 1.3f, -.4f}, {0, 0, -1}, eye, .001f, 1, .3f);
        mcu::appendCharge(out, {.2f, 1.3f, -.4f}, {0, 0, -1}, eye, .001f, .5f, 1.1f);
        const size_t palms = out.size();
        mcu::appendBolt(out, {0, 1.5f, -6}, {0, 1.45f, -4.8f}, eye, .001f, 1);
        const size_t bolt = out.size();
        mcu::appendImpact(out, {0, 1.5f, -8}, eye, eye, .001f, .7f);
        check(palms > 0 && bolt > palms && out.size() > bolt && out.size() <= 3600,
              "the look's vertex budget: " + std::to_string(out.size()));
        for (const Vertex& v : out)
            check(finite(v.position) && finite(v.color) && v.alpha >= 0 && v.alpha <= 1, "a bad repulsor vertex");
        std::vector<Vertex> junk;
        const float nan = std::nanf("");
        mcu::appendCharge(junk, {nan, 0, 0}, {0, 0, -1}, eye, .001f, 1);
        mcu::appendCharge(junk, {0, 1, -1}, {0, 0, 0}, eye, .001f, 1);
        mcu::appendCharge(junk, {0, 1, -1}, {0, 0, -1}, eye, .001f, 0);
        mcu::appendBolt(junk, {0, 1, -2}, {0, 1, -1}, eye, nan, 1);
        mcu::appendImpact(junk, {0, 1, -2}, eye, eye, .001f, 0);
        mcu::appendImpact(junk, eye, eye, eye, .001f, 1);
        check(junk.empty(), "odd input drew the repulsor");
    });
    test("0.0.5 SOUND EFFECTS: the seven WAVs (+ 0.0.7's nine: sixteen) are compiled in, 48 kHz mono 16-bit", [] {
        using namespace spidy::sfx;
        // Update 39.0.2: the MCU repulsor (take C, TIGHT): a .26 s blast and a .12 s charge-up.
#if defined(SPIDY_REPULSOR_TAKE_user)
        constexpr float fire = 1.088f; // Version 0.0.62: the player's own sound's blast (tools/sfx/user_repulsor.py)
#elif defined(SPIDY_REPULSOR_TAKE_a)
        constexpr float fire = .38f; // take A, CLASSIC
#elif defined(SPIDY_REPULSOR_TAKE_b)
        constexpr float fire = .5f; // take B, HEAVY
#else
        constexpr float fire = .26f; // take C, TIGHT (the 0.0.6 default, CMakeLists' SPIDY_REPULSOR_TAKE)
#endif
        // Version 0.0.72: the pistols' shot (2.496 s), the sawed-off's (3.504 s) and the pistols' reload (1.752 s)
        // are the player's own sounds, decoded unchanged (tools/sfx/user_guns.py): their own rate, stereo.
        const float expect[sounds] = {1.85f, fire, 1.7f, .62f, .5f, .34f, .12f,
                                      2.496f, 3.504f, .12f, .4f, .25f, .22f, .4f, 1.f, 1.f, // 0.0.7's nine (Version 0.0.72: heat vision and freeze breath are 1 s seamless loops)
                                      .6f,  .7f,  .45f, 1.1f, // CAPTAIN AMERICA's shield: throw, ricochet, catch, clang
                                      1.752f, 4.389f, 6.699f, // 0.0.72 pistol_reload, THOR's two lightnings
                                      3.25f, 11.519f, .26f}; // 0.0.73 the PUNISHER VAN: start-up, engine loop, door slam
        static_assert(sounds == 26);
        for (uint32_t i = 0; i < sounds; ++i) {
            const Pcm& p = sound(static_cast<Id>(i));
            const bool van = i == vanStart || i == vanEngine || i == vanDoorSlam; // 0.0.73: the player's quiet recording
            const bool user = van || i == pistolShot || i == shotgunBlast || i == pistolReload || i == thorLightning1 || i == thorLightning2;
            const uint32_t rate = i == thorLightning1 ? 44100u : i == shotgunBlast || i == thorLightning2 ? 48000u : user ? 24000u : 48000u;
            check(p.ok && p.rate == rate && p.channels == (user ? 2u : 1u) && p.bits == 16 && p.data && p.bytes % 2 == 0,
                  std::string(names[i]) + " is not its rate, channels and 16-bit PCM");
            check(std::fabs(p.seconds() - expect[i]) < .02f, std::string(names[i]) + " has the wrong length");
            int peak = 0;
            for (uint32_t k = 0; k + 1 < p.bytes; k += 2) {
                const int v = static_cast<int16_t>(static_cast<uint16_t>(p.data[k] | (p.data[k + 1] << 8)));
                peak = std::max(peak, v < 0 ? -v : v);
            }
            // the player's own sounds are full scale as given (-32768 included): kept as they are
            // 0.0.73: the van's recording is kept as it is (peak -20 dBFS); its voice's gain lifts it, never past full scale
            const float lift = i == vanDoorSlam ? slamGain : i == vanEngine ? engineFullGain : engineIdleGain;
            if (van)
                check(peak > 800 && peak * lift > 8000.f && peak * lift < 32768.f, std::string(names[i]) + " is silent or clips at its gain");
            else
                check(peak > 10000 && peak <= (user ? 32768 : 32767), std::string(names[i]) + " is silent or clipped");
        }
    });
    test("Version 0.0.72: the Punisher's guns play the player's own sounds, once a shot and once a pistol reload, never dropped", [] {
        using namespace spidy::sfx;
        using namespace spidy::hero007;
        // the embedded bytes are the player's MP3s decoded as they are (the Python gate compares them to the files)
        check(std::fabs(sound(shotgunBlast).seconds() - 3.504f) < .002f && std::fabs(sound(pistolShot).seconds() - 2.496f) < .002f &&
                  std::fabs(sound(pistolReload).seconds() - 1.752f) < .002f, "not the player's sounds");
        // a voice is always idle at the fastest fire: shots within one sound's length, both pistols at once
        auto within = [](float seconds, float every) { return static_cast<uint32_t>(std::floor(seconds / every)) + 1; };
        check(voicesFor(pistolShot) >= 2 * within(sound(pistolShot).seconds(), pistolSpec.cooldown), "a pistol shot can be dropped");
        check(voicesFor(shotgunBlast) >= within(sound(shotgunBlast).seconds(), sawedOffSpec.cooldown), "a shotgun blast can be dropped");
        check(voicesFor(pistolReload) >= 2 * within(sound(pistolReload).seconds(), seatSeconds), "a reload can be dropped");
        for (uint32_t id = 0; id < sounds; ++id)
            check(voicesFor(id) <= mostVoices && voicesFor(id) >= 1, "a voice count over the table");
        // the requests keep every shot of a burst up to the voices
        uint64_t dropped = 0;
        for (uint32_t i = 0; i < sounds; ++i)
            requests().take(static_cast<Id>(i), dropped);
        dropped = 0;
        for (int k = 0; k < 20; ++k)
            requests().play(pistolShot);
        check(requests().take(pistolShot, dropped) == 20 && dropped == 0, "a burst of pistol shots dropped");
        // two pistols firing on one frame: two playbacks
        PlayOutput o;
        o.sound(pistolShot);
        o.sound(pistolShot);
        check(o.playsOf(pistolShot) == 2 && o.playsOf(shotgunBlast) == 0 && (o.sounds >> pistolShot & 1), "one frame's two shots");
        PlayOutput bit;
        bit.sounds |= 1u << holsterTick;
        check(bit.playsOf(holsterTick) == 1 && bit.playsOf(sounds) == 0, "a bit set directly");
        // the pistol's reload sound: once, as a reload begins, in either mode
        check(reloadSoundOf(pistol, ready, opened) == pistolReload && reloadSoundOf(pistol, empty, opened) == pistolReload &&
                  reloadSoundOf(pistol, ready, autoLoading) == pistolReload && reloadSoundOf(pistol, empty, autoLoading) == pistolReload,
              "a pistol reload began silent");
        check(reloadSoundOf(pistol, opened, seating) == sounds && reloadSoundOf(pistol, seating, ready) == sounds &&
                  reloadSoundOf(pistol, opened, autoLoading) == sounds && reloadSoundOf(pistol, seating, autoLoading) == sounds &&
                  reloadSoundOf(pistol, autoLoading, ready) == sounds && reloadSoundOf(pistol, ready, ready) == sounds &&
                  reloadSoundOf(pistol, ready, empty) == sounds,
              "a pistol reload played twice");
        // the sawed-off as 0.0.7
        check(reloadSoundOf(sawedOff, ready, opened) == magDrop && reloadSoundOf(sawedOff, ready, autoLoading) == magSeat &&
                  reloadSoundOf(sawedOff, seating, ready) == magSeat && reloadSoundOf(sawedOff, autoLoading, ready) == magSeat &&
                  reloadSoundOf(sawedOff, opened, seating) == sounds,
              "the sawed-off's reload sounds changed");
        // a whole AUTO cycle on a real Gun: one reload sound a reload
        for (uint32_t mode : {uint32_t{reloadAuto}, uint32_t{reloadRealistic}}) {
            Gun g;
            g.arm(pistol);
            uint32_t reloadSounds = 0, was = g.state;
            float t = 0;
            for (int f = 0; f < 60 * 12; ++f, t += 1.f / 60) {
                const bool trigger = (f / 3) % 2 == 0; // pulls as fast as the frames allow
                const bool flick = mode == reloadRealistic && g.state == empty && f % 30 == 0;
                const bool hip = mode == reloadRealistic && g.state == opened && f % 30 == 15;
                g.update(1.f / 60, trigger, mode, flick, hip);
                reloadSounds += reloadSoundOf(g.weapon, was, g.state) == pistolReload;
                was = g.state;
            }
            check(g.reloads > 0 && reloadSounds == g.reloads + (g.state == opened || g.state == seating || g.state == autoLoading ? 1u : 0u),
                  "not one reload sound a reload");
        }
    });
    test("0.0.5 SOUND EFFECTS: broken WAVs are refused", [] {
        using namespace spidy::sfx;
        check(parseWav(sound(repulsorFire).data, 0).ok == false && parseWav(nullptr, 100).ok == false, "an empty file");
        std::vector<uint8_t> riff = {'R', 'I', 'F', 'F', 0, 0, 0, 0, 'W', 'A', 'V', 'E'};
        check(!parseWav(riff.data(), riff.size()).ok, "no fmt or data chunk");
        auto make = [](uint16_t format, uint16_t channels, uint16_t bits, uint32_t dataBytes, bool truncate) {
            std::vector<uint8_t> w;
            auto u32 = [&](uint32_t v) { for (int k = 0; k < 4; ++k) w.push_back(static_cast<uint8_t>(v >> (8 * k))); };
            auto u16 = [&](uint16_t v) { w.push_back(static_cast<uint8_t>(v)); w.push_back(static_cast<uint8_t>(v >> 8)); };
            for (char c : std::string("RIFF")) w.push_back(static_cast<uint8_t>(c));
            u32(36 + dataBytes);
            for (char c : std::string("WAVEfmt ")) w.push_back(static_cast<uint8_t>(c));
            u32(16); u16(format); u16(channels); u32(48000); u32(48000u * channels * bits / 8);
            u16(static_cast<uint16_t>(channels * bits / 8)); u16(bits);
            for (char c : std::string("data")) w.push_back(static_cast<uint8_t>(c));
            u32(dataBytes);
            w.resize(w.size() + (truncate ? dataBytes / 2 : dataBytes), 0);
            return w;
        };
        auto ok = make(1, 1, 16, 960, false);
        check(parseWav(ok.data(), ok.size()).ok && std::fabs(parseWav(ok.data(), ok.size()).seconds() - .01f) < 1e-4f,
              "a good 10 ms file is refused");
        auto floatWav = make(3, 1, 32, 960, false);
        check(!parseWav(floatWav.data(), floatWav.size()).ok, "float PCM taken");
        auto six = make(1, 6, 16, 960, false);
        check(!parseWav(six.data(), six.size()).ok, "six channels taken");
        auto cut = make(1, 1, 16, 960, true);
        check(!parseWav(cut.data(), cut.size()).ok || parseWav(cut.data(), cut.size()).bytes <= cut.size() - 44,
              "a cut-off file read past its end");
    });
