    test("Version 0.0.72: the looks into the world (worldLook), PERCH TAKEDOWN's light and rope", [] {
        using namespace hero072;
        Look l;
        l.any = l.perchLight = l.rope = true;
        l.perchAt = {0, 1, -5};
        l.ropeFrom = {0, 4, -5};
        l.ropeTo = {0, 1, -5};
        l.bolts = 1;
        l.boltFrom[0] = {0, 0, -1};
        Blood blood;
        l.blood = &blood;
        Pose w;
        w.position = {10, 0, 0};
        w.orientation = arc({0, 0, -1}, {1, 0, 0}); // a quarter turn: -z to +x
        const Look o = worldLook(l, w);
        check(o.any && o.blood == nullptr, "the world look kept the game thread's blood");
        check(length(o.perchAt - Vec3{15, 1, 0}) < 1e-3f && length(o.boltFrom[0] - Vec3{11, 0, 0}) < 1e-3f,
              "the world look's points are not turned and moved");
        check(length(o.ropeFrom - Vec3{15, 4, 0}) < 1e-3f, "the rope is not moved into the world");
        Pose bad = w;
        bad.orientation.w = NAN;
        check(!worldLook(l, bad).any, "a NaN pose drew a look");
        Look none;
        check(!worldLook(none, w).any, "an empty look became one");
        std::vector<Vertex> green, red;
        appendPerchLight(green, {0, 1, -5}, false, {0, 1.7f, 0});
        appendPerchLight(red, {0, 1, -5}, true, {0, 1.7f, 0});
        check(!green.empty() && green.size() == red.size() && green.size() <= budget::perch, "the perch light drew nothing");
        check(std::fabs(green[0].color.y - red[0].color.y) > .5f, "GREEN and RED look alike");
        std::vector<Vertex> rope, none2;
        appendRope(rope, {0, 4, -5}, {0, 1, -5}, {0, 1.7f, 0}, .001f);
        appendRope(none2, {NAN, 4, -5}, {0, 1, -5}, {0, 1.7f, 0}, .001f);
        appendPerchLight(none2, {0, 1, -500}, false, {0, 1.7f, 0});
        check(!rope.empty() && rope.size() <= budget::rope && none2.empty(), "the rope or its guards are wrong");
        // Play: a perch target's light reaches the look, above his head.
        Play p;
        PlayIn in;
        in.dt = .016f;
        in.play = true;
        in.hero = hero_modes::batman;
        in.head.position = {0, 8, 0};
        in.head.orientation = arc({0, 0, -1}, normalized(Vec3{0, -1, -1}));
        BatonEnemy e[1]{{0x51, {0, 1.2f, -6}}};
        in.list = e;
        in.count = 1;
        in.perched = true;
        PlayOut out;
        p.step(in, out);
        check(out.perch.light == lightGreen && out.look.perchLight && !out.look.perchRed &&
                  out.look.perchAt.y > e[0].chest.y, "the perch light did not reach the look");
    });

    test("Version 0.0.72: PUNISHER RAGE MODE - 5 downs or heavy damage, a heartbeat red at the edges, RAGE BLOOD", [] {
        using namespace hero072;
        hero072::Fight f;
        f.step(.016f, 6, 0, 0, true);
        Rage r;
        f.step(.016f, 6, 0, 4, true);
        r.step(.016f, true, f);
        check(!r.raging, "4 downs raged");
        f.step(.016f, 6, 0, 1, true);
        r.step(.016f, true, f);
        check(r.raging && rageDowns == 5, "the 5th down did not rage");
        check(rageShotScale > 1.f, "rage shots are not harder");
        // The heartbeat: lub-dub, 90-120 bpm, modest, edges only.
        check(heartBpm(0) == 90.f && heartBpm(1) == 120.f && heartBpm(NAN) == 90.f, "the heartbeat's bpm");
        check(heartPulse(heartWidth * .5f) > .99f && heartPulse(heartDub + heartWidth * .5f) > .55f &&
                  heartPulse(heartDub + heartWidth * .5f) < .65f && heartPulse(.7f) == 0 && heartPulse(NAN) == 0,
              "lub-dub");
        HeartBeat hb;
        int peaks = 0;
        float last = 0;
        bool rising = false;
        for (int i = 0; i < 600; ++i) { // 6 s at 100 bpm-ish
            const float p = hb.step(.01f, .33f);
            if (p < last && rising && last > .3f)
                ++peaks;
            rising = p > last;
            last = p;
        }
        check(peaks >= 16 && peaks <= 22, "not about two pulses a beat at ~100 bpm: " + std::to_string(peaks));
        const RageTint calm = rageTint(hero_modes::punisher, 1.f, 0.f), beat = rageTint(hero_modes::punisher, 1.f, 1.f);
        check(beat.tint == calm.tint && beat.warmth == calm.warmth, "the pulse moves the whole view (a flash)");
        check(beat.vignette > calm.vignette && beat.vignette - calm.vignette <= heartVignette, "the pulse is not modest, at the edges");
        check(rageTint(hero_modes::punisher, 1.f, 1.f, rageTintScale(3)).vignette == 0, "RAGE TINT OFF tinted");
        check(rageTint(hero_modes::punisher, 1.f, 0.f, rageTintScale(1)).warmth > calm.warmth &&
                  rageTint(hero_modes::punisher, 1.f, 0.f, rageTintScale(2)).warmth < calm.warmth,
              "RAGE TINT's STRONG / SUBTLE");
        check(rageTint(hero_modes::punisher, 0.f, 1.f).vignette == 0, "a pulse with no rage");
        // RAGE BLOOD: a lot on EXTREME, some on NORMAL, none OFF; capped; it falls and pools.
        Blood b;
        b.shot(bloodOff, {0, 1.2f, -3}, {0, 0, -1}, 0);
        check(b.liveDrops() == 0, "RAGE BLOOD OFF bled");
        b.shot(bloodNormal, {0, 1.2f, -3}, {0, 0, -1}, 0);
        const uint32_t normal = b.liveDrops();
        b.clear();
        b.shot(bloodExtreme, {0, 1.2f, -3}, {0, 0, -1}, 0);
        check(b.liveDrops() >= 3 * normal && b.livePools() > 0, "EXTREME is not a lot more than NORMAL");
        for (int i = 0; i < 40; ++i)
            b.shot(bloodExtreme, {0, 1.2f, -3}, {0, 0, -1}, 0);
        check(b.liveDrops() <= bloodDropsMost && b.livePools() <= bloodPoolsMost, "the blood is not capped");
        for (int i = 0; i < 200; ++i)
            b.step(.016f);
        check(b.liveDrops() == 0 && b.livePools() > 0, "the drops did not land");
        b.shot(bloodExtreme, {NAN, 0, 0}, {0, 0, -1}, 0);
        b.shot(bloodExtreme, {0, 1, 0}, {0, 0, -1}, NAN);
        check(b.liveDrops() == 0, "a NaN shot bled");
        b.shot(bloodExtreme, {0, 1.2f, -3}, {0, 0, -1}, 0);
        std::vector<Vertex> out;
        appendBlood(out, b, {0, 1.7f, 0}, .001f);
        check(!out.empty() && out.size() <= budget::blood + 60, "the blood broke its budget: " + std::to_string(out.size()));
        BloodPerf perf;
        bool tripped = false;
        for (int i = 0; i < 60 && !tripped; ++i)
            tripped = perf.step(.03f, 1 / 90.f, true);
        check(tripped && perf.off, "a frame drop did not turn RAGE BLOOD off");
        BloodPerf fine;
        for (int i = 0; i < 600; ++i)
            fine.step(1 / 90.f, 1 / 90.f, true);
        for (int i = 0; i < 100; ++i)
            fine.step(.03f, 1 / 90.f, false); // slow but not drawing
        check(!fine.off, "RAGE BLOOD turned off without a drop while drawing");
    });
    test("Version 0.0.72: SURVIVAL heals only at rest; WOLVERINE heals mid-fight; SUPERMAN, THOR, HULK immune", [] {
        using namespace hero072;
        check(!survivalHero(hero_modes::superman) && !survivalHero(hero_modes::thor) && !survivalHero(hero_modes::hulk),
              "an immune hero gets injuries");
        check(survivalHero(hero_modes::wolverine) && healsInFight(hero_modes::wolverine) && !healsInFight(hero_modes::punisher),
              "WOLVERINE's healing factor");
        Survival s;
        s.limb[torso] = 40;
        s.sinceHit = 99;
        for (int i = 0; i < 600; ++i)
            s.step(.016f, hero_modes::punisher, 0, true, 0, false); // in a fight
        check(s.limb[torso] == 40, "healed in a fight");
        for (int i = 0; i < 600; ++i)
            s.step(.016f, hero_modes::punisher, 0, false, 6.f, false); // running
        check(s.limb[torso] == 40, "healed while running");
        for (int i = 0; i < 600; ++i)
            s.step(.016f, hero_modes::punisher, 0, false, 1.f, true); // swinging
        check(s.limb[torso] == 40, "healed while swinging");
        for (int i = 0; i < 200; ++i)
            s.step(.016f, hero_modes::punisher, 0, false, 1.f, false); // 3.2 s walking: not yet
        check(s.limb[torso] == 40, "healed before resting long enough");
        for (int i = 0; i < 400; ++i)
            s.step(.016f, hero_modes::punisher, 0, false, 1.f, false);
        check(s.limb[torso] > 40, "did not heal at rest");
        Survival w;
        w.limb[leftLeg] = 30;
        w.sinceHit = 99;
        for (int i = 0; i < 300; ++i)
            w.step(.016f, hero_modes::wolverine, 0, true, 8.f, true);
        Survival c;
        c.limb[leftLeg] = 30;
        c.sinceHit = 99;
        c.rested = 99;
        for (int i = 0; i < 300; ++i)
            c.step(.016f, hero_modes::captainAmerica, 0, false, 0, false);
        check(w.limb[leftLeg] > 30 && w.limb[leftLeg] - 30 > c.limb[leftLeg] - 30, "WOLVERINE did not heal mid-fight faster than resting");
    });
    test("Version 0.0.72: FIRE DOUSE per hero (gestures, no triggers), SHIELD SLAM, the PUNISHER's HOOK", [] {
        using namespace hero072;
        check(!fireHookConfirmed, "the fire hook is marked CONFIRMED without an address");
        check(douseFor(hero_modes::spiderMan) == Douse::webBalls && douseFor(hero_modes::superman) == Douse::coldBreath &&
                  douseFor(hero_modes::ironMan) == Douse::foamPalm && douseFor(hero_modes::batman) == Douse::foamGrenade &&
                  douseFor(hero_modes::punisher) == Douse::foamGrenade && douseFor(hero_modes::thor) == Douse::hammerGust &&
                  douseFor(hero_modes::greenLantern) == Douse::constructHose && douseFor(hero_modes::hulk) == Douse::thunderClap &&
                  douseFor(hero_modes::captainAmerica) == Douse::shieldSlam && douseFor(hero_modes::daredevil) == Douse::batonFan,
              "a hero's douse");
        for (uint32_t d = 0; d < static_cast<uint32_t>(Douse::douses); ++d)
            check(std::string(douseName(static_cast<Douse>(d))) != "?", "a douse without a name");
        Fires fires;
        fires.add({0, 0, -5});
        fires.add({0, 0, 5}); // behind
        uint32_t out = 0;
        for (int i = 0; i < 120; ++i)
            out += fires.douse(Douse::foamPalm, {0, 0, 0}, {0, 0, -1}, .016f);
        check(out == 1 && fires.live() == 1, "the palm foam did not put out only the fire ahead");
        check(fires.douse(Douse::shieldSlam, {0, 0, 3}, {}, .016f) == 1, "the SHIELD SLAM's shockwave did not douse near");
        check(fires.douse(Douse::webBalls, {0, 0, 0}, {0, 0, -1}, .016f) == 0, "web balls are not the game's own");
        // THOR: spin fast below the head; raised it is the storm, not a gust.
        SpinGesture sp;
        bool spun = false;
        for (int i = 0; i < 90; ++i) {
            const float a = i * .25f;
            spun = sp.step(.016f, {3 * std::cos(a), 0, 3 * std::sin(a)}, true) || spun;
        }
        check(spun, "a fast spin not seen");
        SpinGesture raised;
        bool r2 = false;
        for (int i = 0; i < 90; ++i) {
            const float a = i * .25f;
            r2 = raised.step(.016f, {3 * std::cos(a), 0, 3 * std::sin(a)}, false) || r2;
        }
        check(!r2, "a spin with the hammer raised made a gust");
        SpinGesture straight;
        bool r3 = false;
        for (int i = 0; i < 90; ++i)
            r3 = straight.step(.016f, {0, 0, -4}, true) || r3;
        check(!r3, "a straight fast move counted as a spin");
        PalmSpray ps;
        bool sprayed = false;
        for (int i = 0; i < 20; ++i)
            sprayed = ps.step(.016f, 1.f, {0, 0, -1}, {0, 0, -1});
        check(sprayed && !PalmSpray{}.step(.5f, 1.f, {0, 0, 1}, {0, 0, -1}), "IRON MAN's palm foam");
        HoseGesture hose;
        bool h = false;
        for (int i = 0; i < 20; ++i)
            h = hose.step(.016f, 1, 1, {0, 1.7f, 0}, {0, 0, -1}, {-.05f, 1.4f, -.45f}, {.05f, 1.4f, -.45f});
        check(h, "GREEN LANTERN's hose");
        ClapGesture clap;
        clap.step(.016f, {-.4f, 1.3f, -.3f}, {.4f, 1.3f, -.3f});
        check(clap.step(.016f, {-.05f, 1.3f, -.3f}, {.05f, 1.3f, -.3f}), "HULK's clap");
        check(!clap.step(.016f, {-.05f, 1.3f, -.3f}, {.05f, 1.3f, -.3f}), "the clap re-fired");
        ClapGesture slow;
        slow.step(.016f, {-.1f, 1.3f, -.3f}, {.1f, 1.3f, -.3f});
        check(!slow.step(.1f, {-.06f, 1.3f, -.3f}, {.06f, 1.3f, -.3f}), "a slow touch clapped");
        ShieldSlam slam;
        check(!slam.step(.016f, false, {0, 1.7f, 0}, {0, .5f, -.3f}, {0, -4, 0}), "a slam without the shield");
        check(!slam.step(.016f, true, {0, 1.7f, 0}, {0, 1.2f, -.3f}, {0, -4, 0}), "a slam ending high");
        check(slam.step(.016f, true, {0, 1.7f, 0}, {0, .5f, -.3f}, {0, -4, 0}), "the SHIELD SLAM not seen");
        check(shieldSlamHit().amount > 0 && shieldSlamHit().knockAmount >= 400.f && slamRadius > 3.f, "the slam's knockback");
        HookLauncher hk;
        check(!hk.step(.016f, true, 1.f, false, {}, {0, 0, -1}) && hk.state == HookLauncher::stowed, "drawn off the chest");
        hk.step(.016f, true, 0.f, false, {}, {0, 0, -1});
        hk.step(.016f, true, 1.f, true, {}, {0, 0, -1});
        check(hk.state == HookLauncher::held, "the hook not drawn from the chest");
        hk.step(.016f, true, 1.f, false, {0, 0, -3}, {0, 0, -1});
        check(hk.state == HookLauncher::winding, "the push did not fire it");
        int bite = -1;
        for (int i = 0; i < 100 && bite < 0; ++i)
            if (hk.step(.016f, true, 1.f, false, {}, {0, 0, -1}))
                bite = i;
        check(bite >= 30 && bite <= 45, "the hook is not the slower grapple (wind-up)");
        hk.step(.016f, true, 0.f, false, {}, {0, 0, -1});
        check(hk.state == HookLauncher::stowed, "let go did not stow it");
        check(wayUp(hero_modes::punisher) == WayUp::hookLauncher && wayUp(hero_modes::wolverine) == WayUp::clawClimb &&
                  wayUp(hero_modes::batman) == WayUp::grapple && wayUp(hero_modes::thor) == WayUp::fly,
              "the ways up");
        check(climbAllowed(hero_modes::spiderMan, true) && !climbAllowed(hero_modes::batman, true) &&
                  climbAllowed(hero_modes::wolverine, true, true, true) && !climbAllowed(hero_modes::wolverine, true, false, true) &&
                  !climbAllowed(hero_modes::wolverine, true, true, false) && climbAllowed(hero_modes::batman, false),
              "only SPIDER-MAN crawls; WOLVERINE with claws out");
    });
    test("Version 0.0.72: UPPERCUT per hero, GRAPPLE PULL, the PARRY's timing, SHOVE, FACTIONS, REPUTATION per hero, ROSTER", [] {
        using namespace hero072;
        check(!uppercutLaunches(hero_modes::punisher) && uppercutBlow(hero_modes::punisher).knockAmount < 200.f,
              "the PUNISHER's uppercut launched");
        check(!uppercutLaunches(hero_modes::batman) && uppercutBlow(hero_modes::batman).knockAmount < uppercutBlow().knockAmount,
              "BATMAN got a big launch");
        check(uppercutBlow(hero_modes::superman).knockAmount > uppercutBlow(hero_modes::spiderMan).knockAmount &&
                  uppercutBlow(hero_modes::hulk).knockAmount == uppercutBlow(hero_modes::thor).knockAmount &&
                  uppercutBlow(hero_modes::captainAmerica).knockAmount == uppercutBlow().knockAmount,
              "super strength launches higher, others moderate");
        BatonEnemy en[3]{{1, {0, 1.2f, -10}, false}, {2, {3, 1.2f, -10}, false}, {3, {0, 1.2f, -6}, true}};
        check(pullTarget({0, 1.2f, 0}, {0, 0, -1}, en, 3) == 0, "the grapple did not pick the enemy aimed at");
        check(pullTarget({0, 1.2f, 0}, {1, 0, 0}, en, 3) == -1, "the grapple picked one not aimed at");
        ParryTiming pt;
        check(pt.hit() == ParryTiming::none, "uncrossed blocked");
        pt.step(.016f, true);
        pt.step(.1f, true);
        check(pt.hit() == ParryTiming::parry, "crossed right as the hit lands did not parry");
        for (int i = 0; i < 30; ++i)
            pt.step(.016f, true);
        check(pt.hit() == ParryTiming::block, "held crossed did not block");
        pt.step(.016f, false);
        check(pt.hit() == ParryTiming::none, "let go still blocked");
        ShoveGesture sh;
        check(sh.step(.016f, 0, 0, {-.2f, 1.3f, -.4f}, {.2f, 1.3f, -.4f}, {0, 0, -3}, {0, 0, -3}, {0, 0, -1}), "the shove not seen");
        check(!ShoveGesture{}.step(.016f, 1, 1, {-.2f, 1.3f, -.4f}, {.2f, 1.3f, -.4f}, {0, 0, -3}, {0, 0, -3}, {0, 0, -1}),
              "a shove with the grips held");
        check(!ShoveGesture{}.step(.016f, 0, 0, {-.2f, 1.3f, -.4f}, {.2f, 1.3f, -.4f}, {0, 0, -3}, {0, 0, -.5f}, {0, 0, -1}),
              "a one-hand shove");
        check(!factionHookConfirmed, "the faction hook is marked CONFIRMED");
        check(factionFor(hero_modes::daredevil, 0) == theHand && factionFor(hero_modes::captainAmerica, 0) == hydra &&
                  factionFor(hero_modes::spiderMan, 0) == vanilla && factionFor(hero_modes::captainAmerica, 1) == vanilla &&
                  factionFor(hero_modes::spiderMan, 2) == theHand && factionFor(hero_modes::daredevil, 3) == hydra &&
                  factionFor(hero_modes::batman, 0) == jokerGang && factionFor(hero_modes::thor, 4) == jokerGang &&
                  std::string(factionNames[jokerGang]) == "JOKER GANG",
              "the factions (BATMAN's AUTO: the JOKER GANG)");
        check(factionWorn(jokerGang) == vanilla && factionWorn(99) == vanilla && !factionModelReady[jokerGang],
              "the JOKER GANG (no model yet) is not worn as VANILLA");
        Reputation rep;
        rep.select(hero_modes::batman);
        rep.add(3000);
        RepEvents e;
        e.abandoned = true;
        rep.step(e);
        check(rep.points == 3000 + repAbandoned, "a crime left did not cost");
        rep.select(hero_modes::thor);
        check(rep.points == repStart, "reputation is not per hero");
        e = {};
        e.fires = 2;
        rep.step(e);
        check(rep.points == repStart + 2 * repFire, "fires out did not count");
        rep.select(hero_modes::batman);
        check(rep.points == 3000 + repAbandoned && rep.meter() > 0 && rep.meter() < 1, "BATMAN's own rank was lost");
        char buf[512];
        rep.save(buf, sizeof buf);
        Reputation back;
        back.hero = hero_modes::thor;
        back.load(buf);
        check(back.points == repStart + 2 * repFire && back.heroPoints[hero_modes::batman] == 3000 + repAbandoned,
              "the per-hero save did not read back");
        Reputation old;
        old.load("reputation=700\n");
        check(old.points == 700 && old.heroPoints[hero_modes::hulk] == 700, "the old shared save did not carry over");
        hero072::Fight f;
        f.step(.016f, 2, 0, 0, true);
        f.standingFar = 2;
        for (int i = 0; i < 300; ++i)
            f.step(.016f, 0, 0, 0, false);
        check(f.justAbandoned || f.abandoned == 1, "walking away from a fight was not a crime left");
        RosterUi ui;
        check(ui.confirm() == -1, "CONFIRM with no popup");
        ui.tap(hero_modes::thor);
        check(ui.state == RosterUi::popup && std::string(bio(ui.picked).identity) == "Thor Odinson", "the popup");
        check(ui.confirm() == static_cast<int>(hero_modes::thor) && ui.state == RosterUi::grid, "CONFIRM did not switch");
        ui.tap(99);
        check(ui.state == RosterUi::grid, "a bad tile opened a popup");
        for (uint32_t h = 0; h < rosterCount; ++h)
            check(bio(h).identity && bio(h).identity[0] && bio(h).abilities && bio(h).abilities[0], "a bio without a name or powers");
        for (uint32_t o = combat38::rageBlood; o < combat38::options; ++o) {
            const std::string help = combat38::optionInfo[o].help;
            check(help.size() <= 80 && std::count(help.begin(), help.end(), '.') == 1, "a 0.0.72 subtext: " + help);
        }
    });
    test("Version 0.0.72: PLAY composer - invincible, climb only, uppercut, GL beam, THOR storm, ultimate, rep, NaN safe", [] {
        using namespace hero072;
        const auto frame = [](uint32_t hero) {
            PlayIn in;
            in.dt = 1 / 90.f;
            in.play = true;
            in.hero = hero;
            in.head.position = {0, 1.7f, 0};
            for (auto& h : in.hands)
                h.tracked = true;
            in.hands[0].position = {-.25f, 1.2f, -.2f};
            in.hands[1].position = {.25f, 1.2f, -.2f};
            return in;
        };
        BatonEnemy foes[2] = {{0x11, {.3f, 1.4f, -.5f}}, {0x22, {.2f, 1.4f, -10.f}}};
        // NATURAL INVINCIBLE and SPIDER CLIMB ONLY.
        {
            Play play;
            PlayIn in = frame(hero_modes::thor);
            PlayOut out;
            play.step(in, out);
            check(out.keepTopped && !out.climbAllowed, "THOR: kept topped, no wall crawl");
            in.hero = hero_modes::spiderMan;
            play.step(in, out);
            check(!out.keepTopped && out.climbAllowed, "SPIDER-MAN: hurt as ever, crawls");
            in.o.naturalInvincible = false;
            in.hero = hero_modes::superman;
            play.step(in, out);
            check(!out.keepTopped, "NATURAL INVINCIBLE OFF");
            in.hero = hero_modes::wolverine;
            in.clawsOut = true;
            play.step(in, out);
            check(!out.climbAllowed, "0.0.73 (fixes 11 + 18): WOLVERINE claws out, CLAW CLIMB off by default: no climb");
            in.o.clawClimb = true;
            play.step(in, out);
            check(out.climbAllowed, "WOLVERINE claws out: CLAW CLIMB");
        }
        // UPPERCUT: a fast upward punch into the enemy.
        {
            Play play;
            PlayIn in = frame(hero_modes::hulk);
            in.list = foes;
            in.count = 1;
            in.hands[1].position = {.3f, .8f, -.45f};
            uint32_t ups = 0;
            for (int f = 0; f < 30; ++f) {
                in.hands[1].position.y += 3.f / 90.f;
                PlayOut out;
                play.step(in, out);
                for (uint32_t k = 0; k < out.blowCount; ++k)
                    ups += out.blows[k].kind == kindUppercut && out.blows[k].id == 0x11;
            }
            check(ups == 1, "one uppercut for one punch up");
            in.o.uppercut = false;
            Play off;
            uint32_t none = 0;
            in.hands[1].position = {.3f, .8f, -.45f};
            for (int f = 0; f < 30; ++f) {
                in.hands[1].position.y += 3.f / 90.f;
                PlayOut out;
                off.step(in, out);
                none += out.blowCount;
            }
            check(none == 0, "UPPERCUT OFF: no blow");
        }
        // GREEN LANTERN's beam: the right trigger held at an enemy, ticks and drains the charge.
        {
            Play play;
            PlayIn in = frame(hero_modes::greenLantern);
            in.list = foes + 1;
            in.count = 1;
            in.hands[1].position = {.2f, 1.4f, -.3f};
            in.hands[1].aim = {0, 0, -1};
            in.hands[1].trigger = 1;
            uint32_t ticks = 0;
            bool drawn = false;
            for (int f = 0; f < 90; ++f) {
                PlayOut out;
                play.step(in, out);
                for (uint32_t k = 0; k < out.blowCount; ++k)
                    ticks += out.blows[k].kind == kindBeam;
                drawn = drawn || (out.look.beam && out.look.any);
            }
            check(ticks >= 6 && ticks <= 10 && drawn, "the ring beam ticks about every .12 s");
            check(play.charge.level < chargeMost - 10.f, "the beam drains the ring's charge");
        }
        // THOR: the hammer from the back, raised straight up 1 s: the storm strikes the enemy near.
        {
            Play play;
            PlayIn in = frame(hero_modes::thor);
            in.list = foes;
            in.count = 1;
            PlayOut out;
            play.step(in, out);
            in.hands[1].position = {.2f, 1.6f, .1f};
            in.hands[1].grip = 1;
            play.step(in, out);
            check(play.hammerHeld, "the hammer drawn from behind the right shoulder");
            in.hands[1].position = {0, 2.1f, 0};
            in.hands[1].aim = {0, 1, 0};
            uint32_t storms = 0, sounds72 = 0;
            for (int f = 0; f < 200; ++f) {
                out = PlayOut{};
                play.step(in, out);
                for (uint32_t k = 0; k < out.blowCount; ++k)
                    storms += out.blows[k].kind == kindStorm;
                sounds72 += out.lightning[0] + out.lightning[1];
            }
            check(storms == stormStrikes, "the storm's three strikes on the enemy near");
            // Version 0.0.72: one of the player's two lightning sounds a strike, either at random
            check(sounds72 == stormStrikes && play.strikes == stormStrikes, "not one lightning sound a storm strike");
            PlayOut many;
            for (int k = 0; k < 200; ++k)
                play.strike(many);
            check(many.lightning[0] + many.lightning[1] == 200 && many.lightning[0] > 60 && many.lightning[1] > 60,
                  "the two lightning sounds not picked at random");
            Play seeded;
            seeded.seedLightning(0); // never a stuck generator
            PlayOut s0;
            for (int k = 0; k < 50; ++k)
                seeded.strike(s0);
            check(s0.lightning[0] > 0 && s0.lightning[1] > 0, "a zero seed stuck on one sound");
            check(spidy::sfx::voicesFor(spidy::sfx::thorLightning1) >=
                          static_cast<uint32_t>(spidy::sfx::sound(spidy::sfx::thorLightning1).seconds() / stormEvery) + 1 &&
                      spidy::sfx::voicesFor(spidy::sfx::thorLightning2) >=
                          static_cast<uint32_t>(spidy::sfx::sound(spidy::sfx::thorLightning2).seconds() / stormEvery) + 1,
                  "a lightning strike's sound can be dropped");
        }
        // ULTIMATE: TEST UNLOCKS ULTIMATES, both fists crossed on the chest, both grips held.
        {
            Play play;
            PlayIn in = frame(hero_modes::batman);
            in.list = foes;
            in.count = 1;
            in.o.testUnlocks = 2;
            in.hands[0].position = {.15f, 1.3f, -.15f};
            in.hands[1].position = {-.15f, 1.3f, -.15f};
            in.hands[0].grip = in.hands[1].grip = 1;
            bool fired = false;
            uint32_t hits = 0;
            for (int f = 0; f < 200; ++f) {
                PlayOut out;
                play.step(in, out);
                fired = fired || out.ultimateFired;
                for (uint32_t k = 0; k < out.blowCount; ++k)
                    hits += out.blows[k].kind == kindUltimate;
            }
            check(fired && hits == 1, "BATMAN's FEAR TAKEDOWN fires once, one blow");
            Play locked;
            in.o.testUnlocks = 0;
            bool lockedFired = false;
            for (int f = 0; f < 200; ++f) {
                PlayOut out;
                locked.step(in, out);
                lockedFired = lockedFired || out.ultimateFired;
            }
            check(!lockedFired, "no ultimate before max reputation");
        }
        // REPUTATION: a fight, an enemy down: points up; saved and loaded.
        {
            Play play;
            PlayIn in = frame(hero_modes::daredevil);
            BatonEnemy one[1] = {{0x33, {0, 1.4f, -2.f}}};
            in.list = one;
            in.count = 1;
            in.hitSent = true;
            PlayOut out;
            play.step(in, out);
            check(play.fight.on, "the fight starts");
            one[0].down = true;
            play.step(in, out);
            check(play.rep.points == repDown, "a down: reputation up");
            char text[2048];
            play.save(text, sizeof text);
            Play back;
            back.load(text);
            back.rep.select(hero_modes::daredevil);
            check(back.rep.heroPoints[hero_modes::daredevil] == repDown, "reputation kept for good");
            char line[256];
            play.status(line, sizeof line, false, true);
            check(std::strstr(line, "REP 2") && std::strstr(line, "YOUR OWN"), line);
        }
        // PUNISHER RAGE: enough damage in a fight: raging, red tint, shots 1.5x, blood.
        {
            Play play;
            PlayIn in = frame(hero_modes::punisher);
            in.list = foes;
            in.count = 1;
            in.lostShare = .4f;
            PlayOut out;
            play.step(in, out);
            in.lostShare = 0;
            for (int f = 0; f < 90; ++f)
                play.step(in, out);
            check(play.raging() && play.shotScale() == rageShotScale && out.tint.step > 0, "the PUNISHER rages red");
            play.shot(foes[0].chest, in.head.position, 0.f, bloodExtreme);
            play.step(in, out);
            check(out.look.blood != nullptr, "rage blood drawn");
        }
        // Nothing insane gets out: NaN hands and health, every hero.
        for (uint32_t h = 0; h < hero_modes::heroes; ++h) {
            Play play;
            PlayIn in = frame(h);
            in.list = foes;
            in.count = 2;
            const float nan = std::numeric_limits<float>::quiet_NaN();
            in.hands[0].position = {nan, nan, nan};
            in.hands[1].aim = {nan, 0, 0};
            in.lostShare = nan;
            in.speed = nan;
            in.dt = nan;
            for (int f = 0; f < 20; ++f) {
                PlayOut out;
                play.step(in, out);
                for (uint32_t k = 0; k < out.blowCount; ++k)
                    check(std::isfinite(out.blows[k].blow.amount) && finite(out.blows[k].at), "a finite blow");
                check(std::isfinite(out.punchScale[0]) && std::isfinite(out.dazed), "finite outputs");
            }
        }
    });
    test("Version 0.0.72: PERCH TAKEDOWN - BATMAN's quick press hangs a foe by a rope, GREEN / RED light, fail safe", [] {
        using namespace hero072;
        check(!perchHangHookConfirmed && !perchWebHideConfirmed && !perchSafeHookConfirmed && !perchAlertHookConfirmed,
              "a PERCH hook marked CONFIRMED");
        // Batman on a ledge 8 m up looking down at a thug; a second thug 30 m off (too far to see).
        BatonEnemy foes[3]{{0x51, {0, 1.3f, -6.f}}, {0x52, {0, 1.3f, -40.f}}, {0x53, {6.f, 1.3f, -6.f}}};
        Pose head;
        head.position = {0, 9.f, 0};
        head.orientation = arc(Vec3{0, 0, -1}, normalized(Vec3{0, -7.7f, -6.f}));
        PerchIn in;
        in.dt = .016f;
        in.on = true;
        in.head = head;
        in.perched = true;
        in.list = foes;
        in.count = 2;
        PerchTakedown td;
        PerchOut out;
        td.step(in, out);
        check(out.target == 0x51 && out.light == lightGreen && !out.sendButton, "GREEN: the thug below, no one sees him");
        in.button = true;
        in.promptNamed = true;
        td.step(in, out);
        check(out.sendButton && out.alertCount == 0 && out.rope && out.ropeTo.y < out.ropeFrom.y, "the quick press: the game's hang, a rope");
        td.step(in, out);
        check(!out.sendButton, "a held press sent twice");
        // RED: a third thug 6 m off, facing him (unknown facings count as seeing).
        in.button = false;
        in.count = 3;
        PerchTakedown red;
        red.step(in, out);
        check(out.light == lightRed, "RED not shown with a thug looking");
        const Vec3 facings[3]{{0, 0, -1}, {0, 0, -1}, {1, 0, 0}}; // the third looks away
        in.facings = facings;
        red.step(in, out);
        check(out.light == lightGreen, "a thug looking away saw it");
        in.facings = nullptr;
        in.button = true;
        red.step(in, out);
        check(out.sendButton && out.alertCount == 1 && out.alert[0] == 0x53 && red.loud == 1, "RED: the others not alerted");
        in.clear = [](Vec3, Vec3, void*) { return false; }; // a wall between
        check(!perchSeen(foes, nullptr, 3, 0x51, foes[0].chest, in.clear), "seen through a wall");
        in.clear = nullptr;
        // No prompt from the game: COMING SOON, nothing sent.
        PerchTakedown soon;
        in.promptNamed = false;
        in.button = false;
        soon.step(in, out);
        in.button = true;
        soon.step(in, out);
        check(out.comingSoon && !out.sendButton && !out.rope, "a fake takedown with no game prompt");
        // A long hold is not the quick press; not perched or gliding: no target; the SWOOP GRAB.
        PerchTakedown slow;
        in.promptNamed = true;
        in.button = false;
        in.perched = false;
        slow.step(in, out);
        check(out.target == 0, "a target off a perch");
        in.gliding = true;
        slow.step(in, out);
        check(out.target == 0x51, "the SWOOP GRAB has no target");
        // The hanging foe gone: the rope goes.
        BatonEnemy one[1]{{0x51, {0, 1.3f, -6.f}}};
        in.list = one;
        in.count = 1;
        in.button = true;
        slow.step(in, out);
        check(out.sendButton && out.rope, "the swoop grab");
        in.count = 0;
        slow.step(in, out);
        check(!out.rope && slow.hanging == 0, "a rope to nobody");
        // NaN and nonsense: nothing.
        PerchTakedown bad;
        in.head.position = {NAN, 0, 0};
        bad.step(in, out);
        check(out.target == 0 && !out.sendButton, "a NaN head took someone");
        in.head = head;
        in.dt = NAN;
        in.list = nullptr;
        in.count = 9;
        bad.step(in, out);
        check(out.target == 0, "a null list");
        // In Play: BATMAN only; OFF; Spider-Man never.
        Play play;
        PlayIn pin;
        pin.dt = .016f;
        pin.play = true;
        pin.hero = hero_modes::batman;
        pin.head = head;
        pin.perched = true;
        pin.takedownPrompt = true;
        pin.list = foes;
        pin.count = 2;
        for (auto& hd : pin.hands)
            hd.tracked = true;
        PlayOut po;
        play.step(pin, po);
        pin.faceButton = true;
        play.step(pin, po);
        check(po.perch.sendButton && po.perch.light == lightGreen && po.blowCount == 0, "BATMAN's PERCH TAKEDOWN in Play");
        pin.hero = hero_modes::spiderMan;
        pin.faceButton = false;
        play.step(pin, po);
        pin.faceButton = true;
        play.step(pin, po);
        check(!po.perch.sendButton && po.perch.light == lightNone, "SPIDER-MAN got the PERCH TAKEDOWN");
        pin.hero = hero_modes::batman;
        pin.o.perchTakedown = false;
        pin.faceButton = false;
        play.step(pin, po);
        pin.faceButton = true;
        play.step(pin, po);
        check(!po.perch.sendButton && po.perch.target == 0, "PERCH TAKEDOWN OFF still took him");
        const auto& o1 = combat38::optionInfo[combat38::perchTakedown];
        const auto& o2 = combat38::optionInfo[combat38::takedownLight];
        check(o1.values[0] == std::string("ON") && o2.values[0] == std::string("ON"), "the PERCH settings' defaults");
    });
    test("Version 0.0.72: CHAIN MOVES - 3 enemies from the start, 4-6 with the CHAIN perks, SPIDER-MAN vanilla", [] {
        using namespace hero072;
        BatonEnemy foes[8]{};
        for (uint32_t i = 0; i < 8; ++i)
            foes[i] = {0x40u + i, {static_cast<float>(i) * 2.f, 1.3f, -5.f}};
        foes[3].down = true; // a downed enemy is skipped
        const sm2_damage::Blow b{10.f, 5, 100.f};
        Play play;
        PlayOut out;
        check(play.carry(hero_modes::batman, foes[0].id, foes[0].chest, b, foes, 8, out, kindChain) == 2 && out.blowCount == 2 &&
                  out.blows[0].id == 0x41 && out.blows[1].id == 0x42,
              "RICOCHET: the batarang's first hit carries on to 2 more (3 in all), nearest first");
        play.perks.spend(hero_modes::batman, 0, perkAuto, true);
        out = {};
        check(play.carry(hero_modes::batman, foes[0].id, foes[0].chest, b, foes, 8, out, kindChain) == 5 && out.blows[2].id == 0x44,
              "RICOCHET 6: 6 in all, past the downed one");
        out = {};
        check(play.carry(hero_modes::spiderMan, foes[0].id, foes[0].chest, b, foes, 8, out, kindChain) == 0 && out.blowCount == 0 &&
                  play.chainCap(hero_modes::spiderMan) == 1,
              "SPIDER-MAN's moves carried a chain");
        for (uint32_t h : {hero_modes::superman, hero_modes::ironMan, hero_modes::punisher}) {
            out = {};
            play.perks.spend(h, 0, perkAuto, true);
            check(play.carry(h, foes[0].id, foes[0].chest, b, foes, 8, out, kindChain) == 0 && out.blowCount == 0 &&
                      play.chainCap(h) == 1 && play.perks.statBonus(h, h == hero_modes::punisher ? Stat::reloadSpeed
                                                                       : h == hero_modes::superman ? Stat::heatDamage
                                                                                                   : Stat::repulsorDamage) > .4f,
                  "SUPERMAN / IRON MAN / PUNISHER chained (9:26: they hit only where they aim), or no damage / reload perks");
        }
        out = {};
        check(play.carry(hero_modes::thor, foes[0].id, Vec3{NAN, 0, 0}, b, foes, 8, out, kindChain) == 0 &&
                  play.carry(hero_modes::thor, foes[0].id, foes[0].chest, b, nullptr, 0, out, kindChain) == 0,
              "a bad chain did something");
        // SPIDER-MAN: the REP meter only - no survival, uppercut, ultimate, perks or suits.
        PlayIn in;
        in.dt = 1 / 90.f;
        in.play = true;
        in.hero = hero_modes::spiderMan;
        in.o.testUnlocks = 3;
        in.o.survival = true;
        for (auto& h : in.hands)
            h.tracked = true;
        in.list = foes;
        in.count = 8;
        for (int f = 0; f < 30; ++f)
            play.step(in, out);
        char lines[4][hero072::treeLine];
        check(out.blowCount == 0 && out.climbAllowed && !out.keepTopped && !out.ultimateFired && play.tree(hero_modes::spiderMan, lines) == 0 &&
                  play.suits.suits(hero_modes::spiderMan) == 1,
              "SPIDER-MAN got a 0.0.72 extra");
        check(play.tree(hero_modes::thor, lines) == 4, "the tree lines for the settings page");
        // The wired perks: LONG PARRY, LONG RAGE, FAST RAGE.
        ParryTiming t;
        for (int f = 0; f <= 29; ++f)
            t.step(.01f, true); // crossed .29 s
        check(t.hit() == ParryTiming::block && t.hit(parryWindow * 1.3f) == ParryTiming::parry && t.hit(NAN) == ParryTiming::block,
              "LONG PARRY");
        Rage r;
        hero072::Fight fight;
        fight.on = true;
        fight.damage = 1;
        r.step(.1f, true, fight, 4.f);
        fight.on = false;
        for (int f = 0; f < 40; ++f)
            r.step(.05f, true, fight, 4.f); // 2 s after the fight
        check(r.raging, "LONG RAGE did not keep the rage");
        for (int f = 0; f < 60; ++f)
            r.step(.05f, true, fight, 4.f);
        check(!r.raging, "LONG RAGE kept it for ever");
        HulkRage a, c;
        fight.on = true;
        a.step(.1f, true, fight, .1f);
        c.step(.1f, true, fight, .1f, 1.25f);
        check(c.mult > a.mult && a.mult > 1.f, "FAST RAGE");
    });
    test("Build 8: ROSTER page - pictures, poke and laser presses, B back, MODEL MISSING disabled, per-frame cost", [] {
        namespace rp = roster_page;
        using rp::Screen;
        // Every picture folder found by name (the GLB tool and required_assets are checked in roster_page_tests.py).
        for (uint32_t k = 0; k < rp::pictureCount; ++k)
            check(rp::pictureOf(rp::pictureFolders[k]) == static_cast<int>(k), std::string("a picture folder: ") + rp::pictureFolders[k]);
        check(rp::pictureOf("Nope/Nope") < 0 && rp::pictureOf(nullptr) < 0, "an unknown picture folder found");
        // The suits as the game thread publishes them.
        hero072::SuitCatalog cat;
        for (uint32_t k = 0; k < cat.count; ++k) // build 9: every suit has its model - BEYOND's taken away here
            cat.list[k].soon = cat.list[k].soon || std::string(cat.list[k].folder) == "Suit_batman_1";
        rp::Snapshot snap = rp::snapshotOf(cat, false, false);
        check(snap.count[hero_modes::batman] == 5 && snap.rows[hero_modes::batman][0].status == rp::Status::inUse &&
                  snap.rows[hero_modes::batman][1].status == rp::Status::missing && snap.rows[hero_modes::batman][1].final,
              "BATMAN's rows: DEFAULT in use, BEYOND MODEL MISSING (FINAL)");
        for (uint32_t h = 0; h < rp::heroes; ++h)
            for (uint32_t i = 0; i < snap.count[h]; ++i)
                check(snap.rows[h][i].artist[0] != 0 || i == 0, "a row without its artist");
        check(rp::snapshotOf(cat, false, true).ownSuit, "OWN SUIT lost");
        rp::publish(snap);
        const uint32_t v0 = rp::version();
        rp::publish(snap);
        check(rp::version() == v0 && v0 > 0, "an unchanged snapshot bumped the version");
        // Buttons: every one inside the panel; MODEL MISSING rows disabled, row 0 (OWN SUIT) enabled.
        rp::Button bs[rp::buttonsMost];
        const uint32_t ng = rp::buttons(Screen::grid, 0, &snap, bs);
        check(ng == rp::heroes + 1, "the grid's buttons: 11 tiles and CLOSE");
        for (uint32_t i = 0; i < ng; ++i)
            check(bs[i].x0 >= -rp::width / 2 && bs[i].x1 <= rp::width / 2 && bs[i].y0 >= -rp::height / 2 && bs[i].y1 <= rp::height / 2 &&
                      bs[i].x1 > bs[i].x0 && bs[i].y1 > bs[i].y0,
                  "a grid button off the panel");
        rp::Button hb[rp::buttonsMost];
        const uint32_t nh = rp::buttons(Screen::hero, hero_modes::batman, &snap, hb);
        const rp::Button* own = nullptr;
        const rp::Button* missing = nullptr;
        const rp::Button* play = nullptr;
        for (uint32_t i = 0; i < nh; ++i) {
            own = hb[i].id == rp::row ? &hb[i] : own;
            missing = hb[i].id == rp::row + 1 ? &hb[i] : missing;
            play = hb[i].id == rp::playButton ? &hb[i] : play;
        }
        check(own && own->enabled && missing && !missing->enabled && play, "BATMAN's page: OWN SUIT on, BEYOND (MODEL MISSING) off");
        for (const int id : {static_cast<int>(rp::tile), static_cast<int>(rp::closeButton), static_cast<int>(rp::backButton),
                             static_cast<int>(rp::playButton), static_cast<int>(rp::row), static_cast<int>(rp::row) + 1})
            check(rp::helpFor(id >= rp::closeButton && id != rp::closeButton ? Screen::hero : Screen::grid, hero_modes::batman, id, &snap)
                          .find("No restart needed.") != std::string::npos,
                  "a button's help has no restart note: " + std::to_string(id));
        // The page, opened in front of the head (identity, at the origin): panel space = tracking space less the panel's place.
        rp::Page page;
        check(page.open(Pose{}, 0) && page.isOpen() && page.screen() == Screen::grid && page.holdsInput(), "the page did not open");
        const Pose panel = page.panel();
        auto centre = [&](const rp::Button& b) { return Vec3{(b.x0 + b.x1) / 2, (b.y0 + b.y1) / 2, 0}; };
        auto aimAt = [&](rp::Input& in, unsigned hand, const rp::Button& b, float trigger) {
            const Vec3 c = panel.position + panel.orientation.rotate(centre(b));
            in.hands[hand].tracked = true;
            in.hands[hand].aim = Pose{c + panel.orientation.rotate(Vec3{0, 0, .6f}), panel.orientation};
            in.hands[hand].grip = Pose{c + panel.orientation.rotate(Vec3{0, 0, .5f}), panel.orientation};
            in.hands[hand].trigger = trigger;
        };
        const rp::Button* batTile = nullptr;
        for (uint32_t i = 0; i < ng; ++i)
            batTile = bs[i].id == rp::tile + static_cast<int>(hero_modes::batman) ? &bs[i] : batTile;
        check(batTile != nullptr, "no BATMAN tile");
        rp::Input in;
        in.playing = hero_modes::spiderMan;
        // The trigger still held from the wrist press, and too soon: nothing.
        in.seconds = .1, aimAt(in, 1, *batTile, 1.f);
        page.update(in);
        in.seconds = .6;
        page.update(in);
        check(page.screen() == Screen::grid && page.presses() == 0, "a held trigger (or one too soon) pressed a tile");
        check(page.hover() == rp::tile + static_cast<int>(hero_modes::batman), "the laser did not hover the tile");
        Vec3 a{}, b{};
        check(page.laser(1, a, b) && !page.laser(0, a, b), "the right hand's laser not shown (or the left's shown)");
        in.seconds = .7, in.hands[1].trigger = 0;
        page.update(in);
        in.seconds = .8, in.hands[1].trigger = 1;
        page.update(in);
        check(page.screen() == Screen::hero && page.hero() == hero_modes::batman && page.presses() == 1, "a fresh pull did not open BATMAN");
        // MODEL MISSING row: a pull does nothing; OWN SUIT row: picked; PLAY AS: BATMAN.
        in.seconds = .9, aimAt(in, 1, *missing, 0);
        page.update(in);
        in.seconds = 1;
        in.hands[1].trigger = 1;
        auto act = page.update(in);
        check(act.suitIndex < 0 && page.presses() == 1, "a MODEL MISSING suit was picked");
        in.seconds = 1.1, aimAt(in, 1, *own, 0);
        page.update(in);
        in.seconds = 1.2, in.hands[1].trigger = 1;
        act = page.update(in);
        check(act.suitHero == static_cast<int>(hero_modes::batman) && act.suitIndex == 0, "OWN SUIT not picked");
        in.seconds = 1.3, aimAt(in, 1, *play, 0);
        page.update(in);
        in.seconds = 1.4, in.hands[1].a = true; // A presses the aimed button too
        act = page.update(in);
        check(act.playAs == static_cast<int>(hero_modes::batman), "PLAY AS BATMAN not pressed with A");
        in.hands[1].a = false;
        // B: back to the grid, then closed; the input held until B is let go.
        in.hands[1] = {};
        in.seconds = 1.5, in.hands[0].b = true;
        page.update(in);
        check(page.screen() == Screen::grid, "B did not go back");
        in.seconds = 1.6, in.hands[0].b = false;
        page.update(in);
        in.seconds = 1.7, in.hands[0].b = true;
        act = page.update(in);
        check(act.closed && !page.isOpen() && page.holdsInput(), "B on the grid did not close (or let the held B through)");
        in.seconds = 1.8, in.hands[0].b = false;
        page.update(in);
        check(!page.holdsInput(), "the page still holds the input after B was let go");
        // A poke: the hand pushed onto a tile (from clear of it) opens that hero.
        check(page.open(Pose{}, 2), "the page did not reopen");
        in = {};
        in.seconds = 2.5;
        aimAt(in, 0, *batTile, 0);
        in.hands[0].aim.orientation = Quat::yaw(1.57f); // not aimed at the panel
        page.update(in);
        in.seconds = 2.6;
        in.hands[0].grip.position = panel.position + panel.orientation.rotate(centre(*batTile) + Vec3{0, 0, .02f});
        page.update(in);
        check(page.screen() == Screen::hero && page.hero() == hero_modes::batman, "a poke did not press the tile");
        // Walked away: closed.
        in.seconds = 2.7, in.head = Pose{{0, 0, 6}, {}};
        check(page.update(in).closed && !page.isOpen(), "walking away did not close the page");
        // The Roster model's pictures: picture k is triangles 2k, 2k + 1, its UV box in its image's layer.
        mesh_model::Mesh m;
        m.colors.assign(2 * rp::pictureCount, Vec3{1, 1, 1});
        m.corners.assign(6 * rp::pictureCount, Vec3{});
        m.image.resize(2 * rp::pictureCount);
        m.uvs.resize(12 * rp::pictureCount);
        m.images.resize(6);
        for (int i = 0; i < 6; ++i)
            m.images[static_cast<size_t>(i)].layer = 10 + i;
        for (uint32_t k = 0; k < rp::pictureCount; ++k) {
            m.image[2 * k] = m.image[2 * k + 1] = static_cast<int16_t>(k / 9);
            const float u0 = (k % 3) / 3.f, v0 = (k / 3 % 3) / 3.f;
            const float uv[12] = {u0, v0, u0 + .3f, v0, u0 + .3f, v0 + .3f, u0, v0, u0 + .3f, v0 + .3f, u0, v0 + .3f};
            for (int c = 0; c < 12; ++c)
                m.uvs[12 * k + static_cast<uint32_t>(c)] = uv[c];
        }
        rp::Picture pics[rp::pictureCount];
        check(rp::pictures(&m, pics) && pics[13].layer == 11 && std::abs(pics[13].u0 - 1 / 3.f) < 1e-5f &&
                  std::abs(pics[13].v1 - (1 / 3.f + .3f)) < 1e-5f,
              "a picture's layer or UV box");
        check(!rp::pictures(nullptr, pics) && pics[0].layer < 0, "no Roster model gave pictures");
        // Drawn: finite, the pictures only into the textured pass, rebuilt only when it changes; a frame's cost bounded.
        check(page.open(Pose{}, 3), "the page did not open to draw");
        in = {};
        for (int f = 1; f <= 30; ++f) { // faded in (.2 s)
            in.seconds = 3 + f * .02;
            page.update(in);
        }
        rp::Cache cache;
        std::vector<Vertex> plate, models;
        const auto v = rp::view(page, hero_modes::spiderMan, Pose{});
        check(v.opacity > 0 && v.screen == Screen::grid, "the view of an open page");
        rp::append(plate, &models, v, cache, &m, &snap);
        check(!plate.empty() && !models.empty() && cache.rebuilds == 1, "the grid drew nothing (or no pictures)");
        for (const auto& x : models)
            check(x.shape.w == 1 && x.shape.z >= 10 && x.shape.z <= 15, "a picture vertex not textured from the Roster layers");
        const size_t platesize = plate.size();
        const auto start = std::chrono::steady_clock::now();
        for (int f = 0; f < 200; ++f) {
            plate.clear(), models.clear();
            rp::append(plate, &models, v, cache, &m, &snap);
        }
        const double perFrame = std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - start).count() / 200;
        check(cache.rebuilds == 1 && plate.size() == platesize, "an unchanged page was rebuilt");
        check(perFrame < 3000, "the page costs " + std::to_string(perFrame) + " us a frame");
        for (const auto& x : plate)
            check(std::isfinite(x.position.x) && std::isfinite(x.position.y) && std::isfinite(x.position.z), "a vertex not finite");
        plate.clear(), models.clear();
        rp::append(plate, nullptr, v, cache, nullptr, &snap); // untextured: PICTURE MISSING boxes, nothing textured
        check(!plate.empty(), "the untextured page drew nothing");
        page.close();
        check(rp::view(page, 0, Pose{}).opacity == 0, "a closed page is drawn");
    });
    test("Version 0.0.72: SUITS per hero - the user's picks, FINAL at max reputation, COMING SOON never worn", [] {
        using namespace hero072;
        SuitCatalog c;
        // Build 9: the user's picks he sent: Batman 4, Iron Man 4, Cap 2 (+ the 0.0.7 suit), Daredevil 2, Hulk 1 (no FINAL),
        // Wolverine 3, the Punisher 2, Thor 2, Green Lantern 2, Superman 1; each after DEFAULT.
        const uint32_t want[hero_modes::heroes] = {1, 5, 3, 2, 5, 4, 2, 3, 3, 3, 3};
        for (uint32_t h = 0; h < hero_modes::heroes; ++h)
            check(c.suits(h) == want[h], "the built-in suits of hero " + std::to_string(h));
        const uint32_t finals[hero_modes::heroes] = {0, 2, 3, 0, 1, 4, 4, 0, 1, 2, 3}; // the sheets' numbers (0: none)
        for (uint32_t h = 0; h < hero_modes::heroes; ++h) {
            uint32_t f = 0, n = 0;
            for (uint32_t i = 0; i < c.suits(h); ++i)
                if (c.suit(h, i)->final) {
                    ++f;
                    n = i;
                    check(c.suit(h, i)->rep == repMost, "a FINAL suit is not at max reputation");
                } else {
                    check(c.suit(h, i)->rep == 0, "a picked suit is not unlocked from the start");
                }
            check(f == (finals[h] ? 1u : 0u), "one FINAL suit per hero (none for the Punisher or HULK)");
            if (finals[h]) {
                const std::string folder = c.suit(h, n)->folder;
                check(folder.substr(folder.size() - 2) == "_" + std::to_string(finals[h]), "the FINAL is the user's number: " + folder);
            }
            for (uint32_t i = 0; i < c.suits(h); ++i)
                check(i == 0 ? c.suit(h, i)->artist[0] != 0 : c.suit(h, i)->artist[0] && c.suit(h, i)->licence[0], "a suit without its credit");
        }
        // Build 9: every pick has its model (none COMING SOON); a COMING SOON one is never stepped onto or worn.
        char line[96];
        for (uint32_t k = 0; k < c.count; ++k)
            check(!c.list[k].soon, std::string("a COMING SOON suit in build 9: ") + c.list[k].folder);
        {
            SuitCatalog g;
            for (uint32_t k = 0; k < g.count; ++k)
                g.list[k].soon = std::string(g.list[k].folder) == "Suit_batman_1";
            g.line(hero_modes::batman, 1, true, line, sizeof line);
            check(std::string(line) == "BEYOND: MODEL MISSING", std::string("a MODEL MISSING line: ") + line);
            check(!g.choose(hero_modes::batman, 1, true) && g.chosen[hero_modes::batman] == 0, "the roster chose a MODEL MISSING suit");
            g.chosen[hero_modes::batman] = 1;
            check(g.current(hero_modes::batman, true) == 0, "a COMING SOON suit was worn");
            // A converted model dropped in (suits.txt, the same NAME) replaces the COMING SOON entry and keeps its rule.
            check(g.parseList("4|BEYOND|Light.k|CC BY|0|Suit_batman_1\n") == 1 && g.suits(hero_modes::batman) == 5 &&
                      g.suit(hero_modes::batman, 1)->final && !g.suit(hero_modes::batman, 1)->soon,
                  "a converted pick did not replace its COMING SOON entry");
        }
        c.line(hero_modes::captainAmerica, 0, false, line, sizeof line);
        check(std::string(line) == "SUIT: CAPTAIN AMERICA BY iqbalmulyawan (CC BY)", std::string("the 0.0.7 suit: ") + line);
        check(c.parseList("4|BEYOND|Light.k|CC BY|0|Suit_batman_1\n") == 0 && c.suits(hero_modes::batman) == 5, "a suits.txt line doubled a suit");
        check(c.suit(hero_modes::batman, 1)->final && c.suit(hero_modes::batman, 1)->rep == repMost, "the dropped-in FINAL lost its rule");
        check(c.isUnlocked(hero_modes::batman, 2, false), "a picked suit is locked at the start");
        c.line(hero_modes::batman, 1, false, line, sizeof line);
        check(std::string(line) == "BEYOND LOCKED: MAX REP (FINAL)", std::string("a FINAL's lock: ") + line);
        c.unlockFor(hero_modes::batman, repMost - 1);
        check(!c.isUnlocked(hero_modes::batman, 1, false), "the FINAL opened below max reputation");
        check(c.isUnlocked(hero_modes::batman, 1, true), "UNLOCK ALL SUITS did not open the FINAL");
        c.chosen[hero_modes::batman] = 0;
        check(c.next(hero_modes::batman, false) == 2, "SUIT stepped onto the locked FINAL");
        c.unlockFor(hero_modes::batman, repMost);
        check(c.isUnlocked(hero_modes::batman, 1, false), "max reputation did not open the FINAL");
        c.unlockFor(hero_modes::batman, 100);
        check(c.isUnlocked(hero_modes::batman, 1, false), "a lost reputation locked a suit again");
        c.chosen[hero_modes::batman] = 1;
        check(c.inUse(hero_modes::batman, false, false) == 1 && c.inUse(hero_modes::batman, false, true) == 0,
              "USE MY OWN OR GAME SUIT did not fall back to the game's suit");
        char save[1024];
        c.save(save, sizeof save);
        SuitCatalog d;
        d.parseList("4|BEYOND|Light.k|CC BY|0|Suit_batman_1\n");
        d.load(save);
        check(d.isUnlocked(hero_modes::batman, 1, false) && d.current(hero_modes::batman, false) == 1, "the unlock was not saved");
        d.load("suits.4=0\n");
        check(d.isUnlocked(hero_modes::batman, 1, false), "an old save locked it again");
        // Drop-in suits of its own.
        const uint32_t added = d.parseList("# my suits\n9|STORM|someone|CC BY|850|ThorStorm\r\nbad line\n42|X|y|z|0|f\n9|STORM|dupe|CC BY|0|f\n");
        check(added == 1 && d.suits(hero_modes::thor) == 4 && d.suit(hero_modes::thor, 3)->rep == 850, "suits.txt");
        d.line(hero_modes::thor, 3, false, line, sizeof line);
        check(std::string(line) == "STORM LOCKED: REP 850", std::string("a dropped-in suit's lock: ") + line);
        for (int i = 0; i < 20; ++i)
            d.add(makeSuit(hero_modes::thor, ("S" + std::to_string(i)).c_str(), "a", "CC BY", 0, ""));
        check(d.suits(hero_modes::thor) == suitsMost, "the suits per hero are not capped");
        check(combat38::optionInfo[combat38::testUnlocks].values[0] == std::string("OFF"), "TEST UNLOCKS is not OFF by default");
        check(combat38::optionInfo[combat38::ownSuit].values[0] == std::string("OFF"), "USE MY OWN OR GAME SUIT is not OFF by default");
    });
    test("Version 0.0.72: PERK TREES and ULTIMATES - POWER / DEFENSE / MOVE x T1 > T2 > T3 > ULT, +1, RESET POINTS, the CHAIN 3 to 6, none for SPIDER-MAN", [] {
        using namespace hero072;
        check(perkCount == treeHeroes * perksPerHero && treeCost() <= static_cast<uint32_t>(repLevels), "the perk table");
        check(!hasTree(hero_modes::spiderMan) && std::string(ultimate(hero_modes::spiderMan).name).empty(),
              "SPIDER-MAN has a tree or an ultimate (he keeps the game's own skill tree)");
        for (uint32_t h = 1; h < hero_modes::heroes; ++h) {
            check(hasTree(h) && std::string(ultimate(h).name).size() > 0 && ultimate(h).cooldown >= 120.f && ultimate(h).radius > 0,
                  "an ultimate without a name, a long cooldown or a reach");
            uint32_t chains = 0;
            for (uint32_t i = 0; i < perksPerHero; ++i) {
                const Perk& k = perk(h, i);
                const std::string sub = k.sub;
                check(k.hero == h && k.tier == tierOf[i] && k.slot == columnOf[i] && (isIdea(k) || k.amount > 0) && k.cost == perkCost(i), "a perk out of place");
                check(sub.size() <= 80 && std::count(sub.begin(), sub.end(), '.') == 1 && sub.back() == '.',
                      std::string("a perk's subtext is not one short sentence: ") + k.name);
                chains += k.stat == Stat::chainJumps;
            }
            const Stat want = hasChain(h) ? Stat::chainJumps : h == hero_modes::superman ? Stat::heatDamage
                                                                 : h == hero_modes::ironMan  ? Stat::repulsorDamage
                                                                                             : Stat::reloadSpeed;
            check(chains == (hasChain(h) ? 3u : 0u) && perk(h, chainSlot[0]).stat == want && perk(h, chainSlot[1]).stat == want &&
                      perk(h, chainSlot[2]).stat == want,
                  "a CHAIN (or the damage / reload) perk in each tier");
        }
        check(perk(hero_modes::thor, 1).stat == Stat::stormRadius && perk(hero_modes::greenLantern, 2).stat == Stat::chargeDrain &&
                  perk(hero_modes::hulk, 1).stat == Stat::rageBuild && perk(hero_modes::batman, 2).stat == Stat::glideTime &&
                  std::string(ultimate(hero_modes::thor).name) == "BIFROST STRIKE" && std::string(ultimate(hero_modes::hulk).name) == "GROUND SMASH",
              "the user's tree (9:12)");
        // 9:35: the approved mockup (02_skill_tree_thor): POWER / DEFENSE / MOVE x T1-T3, IDEA-TBD placeholders.
        check(std::string(perk(hero_modes::thor, 0).name) == "CHAIN LIGHTNING I" && std::string(perk(hero_modes::thor, 6).name) == "CHAIN LIGHTNING III" &&
                  std::string(perk(hero_modes::thor, 2).name) == "FASTER HAMMER RETURN" && std::string(perk(hero_modes::thor, 4).name) == "LONGER LIGHTNING" &&
                  isIdea(perk(hero_modes::thor, 5)) && isIdea(perk(hero_modes::thor, 7)) && isIdea(perk(hero_modes::thor, 8)) &&
                  !isIdea(perk(hero_modes::thor, 0)) && std::string(columnNames[1]) == "DEFENSE",
              "the mockup's THOR tree");
        for (uint32_t h = 1; h < hero_modes::heroes; ++h) {
            uint32_t ideas = 0;
            for (uint32_t i = 0; i < perksPerHero; ++i) {
                ideas += isIdea(perk(h, i));
                check(isIdea(perk(h, i)) ? !wiredStat(perk(h, i).stat) : perk(h, i).amount > 0, "an IDEA-TBD perk wired, or a perk with no amount");
                check(!isIdea(perk(h, chainSlot[i / 3])), "a POWER chain perk is an idea");
            }
            check(ideas >= 3 && ideas <= 5, "the IDEA-TBD placeholders");
        }
        Perks p;
        check(p.chainCap(hero_modes::batman) == chainBase && p.chainCap(hero_modes::spiderMan) == 1, "the CHAIN hits 3 from the start");
        check(!hasChain(hero_modes::superman) && !hasChain(hero_modes::ironMan) && !hasChain(hero_modes::punisher) &&
                  hasChain(hero_modes::captainAmerica) && hasChain(hero_modes::daredevil) && hasChain(hero_modes::hulk) &&
                  hasChain(hero_modes::wolverine) && hasChain(hero_modes::thor) && hasChain(hero_modes::greenLantern),
              "the CHAIN heroes (9:26)");
        check(treeCost() == 18 && perkCost(0) == 1 && perkCost(3) == 2 && perkCost(8) == 3, "1 / 2 / 3 points: 18 of the 20 levels");
        check(p.points(hero_modes::batman, 499, false) == 0 && p.points(hero_modes::batman, 500, false) == 1, "a point a level");
        check(p.points(hero_modes::spiderMan, repMost, false) == 0 && p.spend(hero_modes::spiderMan, repMost, perkAuto, true) == 0,
              "SPIDER-MAN got perk points");
        // AUTO: DEFENSE, MOVE, then POWER in each tier; IDEA-TBD last.
        check(p.spend(hero_modes::batman, 1000, perkAuto, false) == 2 && !p.tierDone(hero_modes::batman, 0) && p.chainCap(hero_modes::batman) == 3,
              "T1 in order");
        check(p.spend(hero_modes::batman, 1500, perkAuto, false) == 1 && p.tierDone(hero_modes::batman, 0) && p.chainCap(hero_modes::batman) == 4,
              "T1 in order, CHAIN 4");
        check(!p.open(hero_modes::batman, 6), "T3 opened before T2 was full");
        check(p.spend(hero_modes::batman, 2500, perkAuto, false) == 1 && (p.owned[hero_modes::batman] & perkBit(5)) &&
                  !(p.owned[hero_modes::batman] & perkBit(4)),
              "T2's first wired perk (the IDEA-TBD one waits)");
        check(p.scale(hero_modes::batman, Stat::glideTime) > 1.1f && p.scale(hero_modes::hulk, Stat::glideTime) == 1.f,
              "the perks' stats are not per hero");
        check(p.spend(hero_modes::batman, 2500, perkAuto, false) == 0, "spent points it did not have");
        Perks c;
        c.spend(hero_modes::thor, 500 * 4, perkChainFirst, false); // 4 points: T1 (3), then 1 short of T2
        check((c.owned[hero_modes::thor] & perkBit(0)) && c.count(hero_modes::thor) == 3, "CHAIN FIRST");
        c.spend(hero_modes::thor, 500 * 6, perkChainFirst, false);
        check((c.owned[hero_modes::thor] & perkBit(3)) && !(c.owned[hero_modes::thor] & perkBit(4)) && c.chainCap(hero_modes::thor) == 5,
              "CHAIN FIRST in T2");
        Perks hold;
        check(hold.spend(hero_modes::hulk, repMost, perkHold, false) == 0 && hold.points(hero_modes::hulk, repMost, false) == 20, "HOLD POINTS");
        // +1 by hand (the SKILL TREE) and RESET POINTS.
        check(!hold.buy(hero_modes::hulk, 3, repMost, false) && hold.buy(hero_modes::hulk, 0, repMost, false) &&
                  !hold.buy(hero_modes::hulk, 0, repMost, false) && hold.points(hero_modes::hulk, repMost, false) == 19,
              "+1: a locked tier, or bought twice");
        check(hold.buy(hero_modes::hulk, 1, repMost, false) && hold.buy(hero_modes::hulk, 2, repMost, false) && hold.buy(hero_modes::hulk, 3, repMost, false) &&
                  hold.spent(hero_modes::hulk) == 5 && hold.chainCap(hero_modes::hulk) == 5,
              "+1 through T2");
        check(!hold.buy(hero_modes::hulk, 0, 500, false) && !hold.buy(hero_modes::spiderMan, 0, repMost, true), "+1 with no points, or for SPIDER-MAN");
        Perks poor;
        check(!poor.buy(hero_modes::thor, 0, 499, false) && poor.buy(hero_modes::thor, 0, 500, false) && !poor.buy(hero_modes::thor, 1, 500, false),
              "+1 without the point");
        hold.dirty = false;
        check(hold.reset(hero_modes::hulk) == 4 && hold.count(hero_modes::hulk) == 0 && hold.points(hero_modes::hulk, repMost, false) == 20 &&
                  hold.dirty && hold.chainCap(hero_modes::hulk) == 3 && hold.reset(hero_modes::spiderMan) == 0,
              "RESET POINTS");
        check(p.spend(hero_modes::thor, 0, perkAuto, true) == perksPerHero && p.count(hero_modes::thor) == perksPerHero &&
                  p.chainCap(hero_modes::thor) == chainMost,
              "ALL did not fill the tree, or the CHAIN is not 6");
        check(p.statBonus(hero_modes::thor, Stat::idea) == 0.f, "an IDEA-TBD perk did something");
        p.spend(hero_modes::thor, 0, perkOff, false);
        check(p.off && p.chainCap(hero_modes::thor) == chainBase && p.scale(hero_modes::thor, Stat::stormRadius) == 1.f, "PERKS OFF");
        p.spend(hero_modes::thor, 0, perkAuto, false);
        char lines[4][hero072::treeLine];
        check(p.tree(hero_modes::thor, false, lines) == 4 && std::strstr(lines[0], "[x] CHAIN LIGHTNING I") && std::strstr(lines[0], "FASTER HAMMER RETURN") &&
                  std::strstr(lines[2], "CHAIN LIGHTNING III") && std::strstr(lines[3], "[ ] BIFROST STRIKE") && p.tree(hero_modes::spiderMan, true, lines) == 0,
              "the tree lines");
        char buf[512];
        p.save(buf, sizeof buf);
        check(!std::strstr(buf, "tree.0=") && std::strstr(buf, "tree.9=511"), "SPIDER-MAN's perks saved, or THOR's not");
        Perks q;
        q.load(buf);
        check(q.owned[hero_modes::batman] == p.owned[hero_modes::batman] && q.count(hero_modes::thor) == perksPerHero, "perks not saved");
        q.load("tree.4=0\ntree.10=511\nperks.1=63\n");
        check(q.owned[hero_modes::batman] == p.owned[hero_modes::batman] && q.count(hero_modes::greenLantern) == perksPerHero &&
                  q.count(hero_modes::ironMan) == 0,
              "an old save took perks away, tree.1 read tree.10, or the 6-perk test save was read");
        // The ultimate: max reputation (or TEST UNLOCKS), the crossed fists held, a long cooldown.
        check(!ultimateUnlocked(hero_modes::hulk, repMost - 1, false) && ultimateUnlocked(hero_modes::hulk, repMost, false) &&
                  ultimateUnlocked(hero_modes::hulk, 0, true) && !ultimateUnlocked(hero_modes::spiderMan, repMost, true),
              "the ultimate's unlock (none for SPIDER-MAN)");
        check(testSuits(1) && !testUltimates(1) && testUltimates(2) && testSuits(2) && testPerks(3) && !testSuits(0), "TEST UNLOCKS' values");
        holster::BodyPoint l{.35f, .12f, .15f}, r{.35f, -.12f, .15f};
        check(fistsCrossed(l, r) && !fistsCrossed(r, l) && !fistsCrossed({1.f, .12f, .15f}, r), "fists crossed on the chest");
        UltimateMove u;
        bool fired = false;
        for (int i = 0; i < 100 && !fired; ++i)
            fired = u.step(.016f, hero_modes::hulk, false, true, true, 1, 1);
        check(!fired, "a locked ultimate fired");
        int at = -1;
        for (int i = 0; i < 120 && at < 0; ++i)
            if (u.step(.016f, hero_modes::hulk, true, true, true, 1, 1))
                at = i;
        check(at >= 70 && at <= 80, "the ultimate's 1.2 s hold");
        check(u.hit(hero_modes::hulk) && !u.hit(hero_modes::hulk), "GROUND SMASH is not one blow");
        bool again = false;
        for (int i = 0; i < 300; ++i)
            again = u.step(.016f, hero_modes::hulk, true, true, true, 1, 1) || again;
        check(!again && u.cooldown > 100.f, "the ultimate's long cooldown");
        UltimateMove w;
        for (int i = 0; i < 80; ++i)
            w.step(.016f, hero_modes::wolverine, true, true, true, 1, 1);
        uint32_t hits = 0;
        for (int i = 0; i < 600; ++i) {
            w.step(.016f, hero_modes::wolverine, true, true, false, 0, 0);
            hits += w.hit(hero_modes::wolverine);
        }
        check(hits == ultimate(hero_modes::wolverine).hits, "BERSERKER's slashes: " + std::to_string(hits));
        UltimateMove off;
        bool o = false;
        for (int i = 0; i < 100; ++i)
            o = off.step(.016f, hero_modes::thor, true, false, true, 1, 1) || o;
        check(!o, "ULTIMATES OFF fired");
    });
    test("Version 0.0.7: CAPTAIN AMERICA settings, defaults and helpers", [] {
        using namespace spidy;
        using namespace spidy::combat38;
        check(std::string(valueName(captainAmerica, 0)) == "OFF" && std::string(valueName(shieldArm, 0)) == "RIGHT" &&
                  std::string(valueName(shieldArm, 1)) == "LEFT" &&
                  std::string(valueName(shieldDamage, 0)) == "35 HP" && std::string(valueName(shieldChain, 0)) == "ON" &&
                  std::string(valueName(shieldBlock, 0)) == "OFF" && std::string(valueName(shieldLook, 0)) == "BUILT-IN",
              "OFF, RIGHT (LEFT selectable), 35 HP, CHAIN ON, BLOCK OFF, BUILT-IN by default");
        check(std::string(valueName(shieldBlock, 1)) == "EXPERIMENTAL" &&
                  std::string(optionInfo[shieldBlock].help).find("CANDIDATE") != std::string::npos,
              "SHIELD BLOCK is labelled EXPERIMENTAL and CANDIDATE");
        check(isHeroToggle(captainAmerica) && !isHeroToggle(shieldArm) && std::size(heroToggles) == 10, "the tenth hero toggle (0.0.72: THOR, GREEN LANTERN)");
        check(hero_modes::fromToggles(false, false, false, false, false, false, false, true) == hero_modes::captainAmerica &&
                  hero_modes::fromToggles(false, false, false, false, false, false, true, true) == hero_modes::punisher &&
                  hero_modes::fromToggles(false, false, false, false, false, false, false, false) == hero_modes::spiderMan,
              "CAPTAIN AMERICA from the toggles, the first on wins");
        check(captain::throwHp(0) == 35.f && captain::throwHp(1) == 20.f && captain::throwHp(2) == 50.f && captain::throwHp(3) == 70.f &&
                  captain::throwHp(99) == 35.f && captain::throwHit(0).amount == 35.f && captain::throwHit(0).knockback == 5,
              "SHIELD DAMAGE 35 / 20 / 50 / 70 HP, the CONFIRMED knock kind");
        check(captain::armHand(captain::armRight) == 1 && captain::armHand(captain::armLeft) == 0 && captain::armHand(7) == 1 &&
                  captain::armRight == 0 && captain::chainOn(0) &&
                  !captain::chainOn(1) && !captain::blockOn(0) && captain::blockOn(1) && !captain::lookModel(0) && captain::lookModel(1),
              "the value helpers");
        check(std::string(hero007::blowKindNames[hero007::kindShield]) == "SHIELD" &&
                  std::string(hero007::blowKindNames[hero007::kindShieldBash]) == "SHIELD BASH",
              "the blow names");
        // The throw's aim: a fast forward sweep, else the controller's aim; NaN safe.
        const Vec3 f{0, 0, -1};
        check(length(captain::throwAim({3, 0, -3}, f, f) - normalized(Vec3{3, 0, -3})) < 1e-4f, "a backhand sweep throws along it");
        check(length(captain::throwAim({0, 0, -1}, f, f) - f) < 1e-4f, "slow: along the aim");
        check(length(captain::throwAim({0, 0, 5}, f, f) - f) < 1e-4f, "a backswing (away from the view) is not the throw");
        check(finite(captain::throwAim({NAN, 0, 0}, {NAN, 0, 0}, f)), "NaN: still a direction");
        // The model's frame: the RIGHT arm's centre is the LEFT's turned about the pivot; on the back the
        // disc's middle lands where it should, the face backward.
        const Vec3 cr = captain::forSide(captain::centreLeft, 1);
        check(std::abs(cr.x - .002f) < 1e-5f && std::abs(cr.y - (-.21763f + .113f)) < 1e-5f, "the RIGHT arm's mirror");
        for (uint32_t side = 0; side < 2; ++side) {
            const auto b = captain::onBack({0, 1.7f, 0}, {0, 0, -1}, {1, 0, 0}, side);
            const Vec3 mid = captain::centreOf(b, side);
            check(b.ok && length(mid - Vec3{0, 1.3f, .22f}) < 1e-4f && b.face.z > .99f, "on the back, between the shoulder blades");
            const auto a = captain::onArm({0, 1.3f, -.3f}, {0, 0, -1}, {0, 0, -1}, {1, 0, 0}, side);
            check(a.ok && std::abs(dot(a.face, a.up)) < 1e-4f && (side ? a.face.x > 0 : a.face.x < 0), "on the arm: square, leaning out");
        }
        check(!captain::onArm({NAN, 0, 0}, f, f, {1, 0, 0}, 0).ok && !captain::onBack({0, 1.7f, 0}, {0, 0, 0}, {1, 0, 0}, 0).ok,
              "NaN / no body: no pose");
    });
    test("Version 0.0.7: CAPTAIN AMERICA SHIELD BLOCK (EXPERIMENTAL): never a revive, never above the cap", [] {
        using namespace spidy;
        captain::Block b;
        check(b.step(100, 100, NAN, true, true, false) < 0, "the first reading: nothing");
        check(b.step(80, 100, NAN, true, true, false) == 100.f && b.refunds == 1, "a covered hit is given back");
        check(b.step(70, 100, NAN, true, false, false) < 0 && b.uncovered == 1, "an uncovered hit stays");
        check(b.step(0, 100, NAN, true, true, false) < 0, "never a revive");
        b = {};
        b.step(100, 100, NAN, false, true, false);
        check(b.step(80, 100, NAN, false, true, false) < 0, "OFF: nothing");
        b = {};
        b.step(100, 100, NAN, true, true, true);
        check(b.step(80, 100, NAN, true, true, true) < 0, "INVINCIBLE already refills: nothing");
        b = {};
        b.step(100, 100, .25f, true, true, false);
        check(b.step(60, 100, .25f, true, true, false) == 75.f, "never above the game's own cap");
        b = {};
        b.step(50, 100, NAN, true, true, false);
        check(b.step(40, 100, NAN, true, true, false) == 50.f, "back to where it was, no more");
        check(b.step(NAN, 100, NAN, true, true, false) < 0 && b.hpWas < 0 && b.step(30, 100, NAN, true, true, false) < 0,
              "a NaN reading forgets the last one");
        const hero_modes::BatonEnemy front[1] = {{5, {0, 1.3f, -4}}}, behind[1] = {{6, {0, 1.3f, 4}}};
        check(captain::covers({0, 1.3f, -.3f}, {0, 0, -1}, front, 1) && !captain::covers({0, 1.3f, -.3f}, {0, 0, -1}, behind, 1) &&
                  !captain::covers({0, 1.3f, -.3f}, {0, 0, -1}, nullptr, 0) && !captain::covers({NAN, 0, 0}, {0, 0, -1}, front, 1),
              "covers: the nearest enemy in front of the face");
    });
    test("Version 0.0.7: CAPTAIN AMERICA shield: back holster, throw, chain, return, draw", [] {
        using namespace spidy::hero007;
        const spidy::hero_modes::BatonEnemy foes[3] = {{41, {0, 1.3f, -4}}, {42, {2, 1.3f, -5.5f}}, {43, {-2.5f, 1.3f, -7}}};
        const Vec3 back{-.1f, 1.5f, .25f}, front{-.2f, 1.3f, -.3f}, rightAway{.3f, 1.3f, -.5f};
        const auto mirror = [](Vec3 v) { return Vec3{-v.x, v.y, v.z}; };
        const auto run = [&](uint32_t chainValue, uint32_t damage, int& hits, float& amount, uint32_t& sounds, bool& heldInFlight,
                             Play& p, uint32_t armValue = spidy::captain::armLeft) {
            const unsigned k = spidy::captain::armHand(armValue), other = 1 - k;
            PlayInput in;
            in.shieldArm = armValue;
            in.dt = 1 / 90.f;
            in.play = true;
            in.hero = spidy::hero_modes::captainAmerica;
            in.head = {{0, 1.7f, 0}, {}};
            in.list = foes;
            in.count = 3;
            in.shieldChain = spidy::captain::chainOn(chainValue);
            in.shieldDamage = damage;
            for (int f = 0; f < 500; ++f) {
                const Vec3 l = f < 4 ? back : front;
                in.hands[k] = {k ? mirror(l) : l, {0, 0, -1}, true, f == 20 ? 1.f : 0.f, f >= 2 ? 1.f : 0.f, false, false};
                in.hands[other] = {k ? mirror(rightAway) : rightAway, {0, 0, -1}, true, 0, 0, false, false};
                PlayOutput o;
                p.holsterStep(in, o);
                PlayOutput s2;
                p.step(in, s2);
                sounds |= s2.sounds | o.sounds;
                for (uint32_t b = 0; b < s2.blowCount; ++b)
                    if (s2.blows[b].kind == kindShield) {
                        ++hits;
                        amount = s2.blows[b].blow.amount;
                    }
                if (!p.shield.inHandNow() && p.shieldRack.heldIn(k) < 0)
                    heldInFlight = false;
            }
        };
        Play p;
        int hits = 0;
        float amount = 0;
        uint32_t sounds = 0;
        bool held = true;
        run(0, 0, hits, amount, sounds, held, p);
        check(p.shield.throws == 1 && hits == 3 && amount == 35.f, "CHAIN ON: one throw, three enemies, 35 HP each: " + std::to_string(hits));
        check(p.shield.catches + p.shield.timeouts == 1 && p.shield.inHandNow() && p.shieldOnArm(), "it comes back to the arm");
        check(held, "the grip let go is kept while the shield flies (keep)");
        check((sounds >> spidy::sfx::shieldThrow & 1) && (sounds >> spidy::sfx::shieldRicochet & 1) &&
                  (sounds >> spidy::sfx::shieldCatch & 1) && (sounds >> spidy::sfx::holsterTick & 1),
              "throw, ricochet, catch and the holster's tick");
        Play q;
        hits = 0;
        sounds = 0;
        run(1, 3, hits, amount, sounds, held, q);
        check(q.shield.throws == 1 && hits == 1 && amount == 70.f && q.shield.inHandNow(), "CHAIN OFF: one enemy (70 HP), then home");
        // SHIELD ARM RIGHT (the default value 0): the same throw, chain and return from the right arm.
        Play pr;
        hits = 0;
        sounds = 0;
        held = true;
        run(0, 0, hits, amount, sounds, held, pr, spidy::captain::armRight);
        check(pr.shieldHand == 1 && pr.shield.throws == 1 && hits == 3 && amount == 35.f && pr.shieldOnArm() &&
                  pr.shieldRack.heldIn(1) >= 0 && pr.shieldRack.heldIn(0) < 0,
              "RIGHT (default): drawn by the right hand, three enemies, back on the right arm: " + std::to_string(hits));
        {
            PlayInput d0;
            check(d0.shieldArm == spidy::captain::armRight && spidy::captain::armHand(d0.shieldArm) == 1, "a default input is the RIGHT arm");
        }
        // Only the SHIELD ARM's hand draws it; a change of arm puts it back on the back.
        Play r;
        PlayInput in;
        in.dt = 1 / 90.f;
        in.play = true;
        in.hero = spidy::hero_modes::captainAmerica;
        in.head = {{0, 1.7f, 0}, {}};
        const Vec3 backR{.1f, 1.5f, .25f};
        in.shieldArm = spidy::captain::armLeft;
        PlayOutput o;
        for (int f = 0; f < 3; ++f) {
            in.hands[0] = {front, {0, 0, -1}, true, 0, 0, false, false};
            in.hands[1] = {backR, {0, 0, -1}, true, 0, f ? 1.f : 0.f, false, false};
            o = {};
            r.holsterStep(in, o);
        }
        check(r.shieldRack.heldIn(1) < 0 && !(o.claimed & 2), "LEFT: the right hand cannot take the shield");
        Draw d;
        r.draw(d, Pose{}, in, 0);
        check(d.any && d.worn[0].look == lookShield && d.held[0].look == lookNone && d.held[1].look == lookNone,
              "holstered: on the back only");
        in.shieldArm = spidy::captain::armRight;
        for (int f = 0; f < 3; ++f) {
            in.hands[1] = {backR, {0, 0, -1}, true, 0, f ? 1.f : 0.f, false, false};
            o = {};
            r.holsterStep(in, o);
        }
        check(r.shieldHand == 1 && r.shieldRack.heldIn(1) >= 0 && (o.claimed & 2), "RIGHT: the right hand draws it");
        in.hands[1] = {Vec3{-front.x, front.y, front.z}, {0, 0, -1}, true, 0, 1, false, false};
        o = {};
        r.holsterStep(in, o);
        PlayOutput s2;
        r.step(in, s2);
        r.draw(d, Pose{}, in, 0);
        check(d.held[1].look == lookShield && d.held[1].side == 1 && d.worn[0].look == lookNone, "drawn: on the right arm only");
        in.shieldArm = spidy::captain::armLeft;
        r.holsterStep(in, o);
        check(r.shieldHand == 0 && r.shieldRack.heldIn(1) < 0 && r.shieldRack.heldIn(0) < 0, "an arm change: back on the back");
        // Guarding: the face toward the nearest enemy.
        Play g;
        in.shieldArm = spidy::captain::armLeft;
        const spidy::hero_modes::BatonEnemy one[1] = {{51, {-.5f, 1.3f, -4}}};
        in.list = one;
        in.count = 1;
        for (int f = 0; f < 6; ++f) {
            in.hands[0] = {f < 3 ? back : front, {0, 1, 0}, true, 0, f ? 1.f : 0.f, false, false};
            in.hands[1] = {rightAway, {0, 0, -1}, true, 0, 0, false, false};
            o = {};
            g.holsterStep(in, o);
            s2 = {};
            g.step(in, s2);
        }
        check(g.shieldOnArm() && g.guarding, "the guard up, the enemy in front: guarding");
        // Other heroes: no shield rack, nothing claimed.
        in.hero = spidy::hero_modes::batman;
        in.hands[0] = {back, {0, 0, -1}, true, 0, 1, false, false};
        o = {};
        g.holsterStep(in, o);
        // 0.0.73: BATMAN's grip there draws his grapple gun (fix 3) - never a shield.
        check((o.claimed == 0 || g.gunDrawn[0]) && g.shieldRack.heldIn(0) < 0, "another hero: no shield");
        // NaN never draws or throws.
        Play n;
        in.hero = spidy::hero_modes::captainAmerica;
        in.hands[0] = {{NAN, 0, 0}, {0, 0, -1}, true, 1, 1, false, false};
        o = {};
        n.holsterStep(in, o);
        s2 = {};
        n.step(in, s2);
        n.draw(d, Pose{}, in, 0);
        check(n.shield.throws == 0 && s2.blowCount == 0, "NaN: no throw");
    });
    test("Version 0.0.7: DAREDEVIL BATON GRIP - in the fist from the grip pose: 15-25 deg off the forearm, hand at 1/3, mirrored, per controller", [] {
        // The user (public 0.0.63): "daredevils batons sit weird in his hands not like a natural grop".
        // 0.0.62 drew the held baton along the hand's AIM, .12 m behind the grip to .45 m ahead.
        namespace bg = spidy::baton_grip;
        const auto deg = [](Vec3 a, Vec3 b) {
            return std::acos(std::clamp(dot(normalized(a), normalized(b)), -1.f, 1.f)) * 180.f / 3.14159265f;
        };
        const auto mirror = [](Vec3 v) { return Vec3{-v.x, v.y, v.z}; };
        check(bg::handleTiltDeg(ControllerKind::touch) == 30.f && bg::handleTiltDeg(ControllerKind::index) == 15.f,
              "per controller: Touch 30 deg (CONFIRMED, Update 20), Index 15 deg (CANDIDATE)");
        check(bg::handleTiltDeg(ControllerKind::frame) == 30.f && bg::handleTiltDeg(ControllerKind::other) == 30.f &&
                  bg::handleTiltDeg(ControllerKind::none) == 30.f,
              "the Steam Frame, others and unknown hold like Touch");
        check(bg::offForearmDeg >= 15.f && bg::offForearmDeg <= 25.f, "the shaft 15-25 deg off the forearm");
        check(std::abs(bg::length - .57f) < 1e-6f && std::abs(bg::gripShare - 1.f / 3.f) < 1e-6f, "57 cm, the hand at a third");
        // Touch vs Index in the grip frame: only the handle's tilt differs, both 20 deg off their forearm.
        check(std::abs(deg(bg::localShaft(ControllerKind::touch), bg::localShaft(ControllerKind::index)) - 15.f) < .01f,
              "Touch and Index shafts differ by the handles' 15 deg");
        check(std::abs(deg(bg::localShaft(ControllerKind::touch), {0, -1, 0}) - 50.f) < .01f &&
                  std::abs(deg(bg::localShaft(ControllerKind::index), {0, -1, 0}) - 35.f) < .01f,
              "off the grip's -Y (0.0.62's aim, AIM AXIS HAND): Touch 50 deg, Index 35 deg");
        check(std::abs(bg::localShaft(ControllerKind::touch).x) < 1e-6f, "in the grip's Y-Z plane (no palm-normal part)");
        const Quat turns[] = {Quat{}, Quat::around({0, 1, 0}, .7f), Quat::around({1, .3f, -.2f}, -1.1f),
                              Quat::yaw(2.5f) * Quat::around({0, 0, 1}, .4f), Quat::around({.2f, -1, .5f}, 2.9f)};
        const ControllerKind kinds[] = {ControllerKind::touch, ControllerKind::index, ControllerKind::frame, ControllerKind::none};
        for (const Quat& q : turns)
            for (const ControllerKind k : kinds) {
                const Pose right{{.21f, 1.27f, -.38f}, q};
                const Pose left{mirror(right.position), {q.x, -q.y, -q.z, q.w}}; // the mirror image (+X kept right)
                const auto r = bg::shaft(right, 1, k), l = bg::shaft(left, 0, k);
                check(r.ok && l.ok, "a good grip pose gives a shaft");
                const Vec3 way = r.tip - r.butt;
                const Vec3 forearm = q.rotate(bg::localForearm(k));
                const float off = deg(way, forearm);
                check(off >= 15.f && off <= 25.f, "the shaft is not 15-25 deg off the forearm");
                check(dot(normalized(way), q.rotate({0, 0, -1})) > .5f, "the tip does not leave over the thumb's side");
                check(dot(normalized(way), forearm) > .9f, "the tip does not lead forward with the forearm");
                check(std::abs(length(way) - .57f) < 1e-4f, "not 57 cm");
                const float share = dot(right.position - r.butt, normalized(way)) / length(way);
                check(std::abs(share - 1.f / 3.f) < .01f, "the hand is not a third of the way from the butt");
                check(length(cross(right.position - r.butt, normalized(way))) < 1e-4f, "the grip point is off the shaft");
                check(length(l.butt - mirror(r.butt)) < 1e-4f && length(l.tip - mirror(r.tip)) < 1e-4f,
                      "left and right are not mirror images");
                check(std::abs(deg(l.tip - l.butt, left.orientation.rotate(bg::localForearm(k))) - off) < .01f,
                      "the left hand's angle differs");
            }
        // Never from the aim: the same grip gives the same shaft whatever the aim pose or AIM AXIS (it takes none).
        // A bad pose draws nothing from it (game_xr keeps 0.0.62's shaft along the aim), never a NaN.
        const float nan = std::numeric_limits<float>::quiet_NaN();
        check(!bg::shaft({{nan, 1, 0}, {}}, 1, ControllerKind::touch).ok, "NaN position");
        check(!bg::shaft({{0, 1, 0}, {0, 0, 0, 0}}, 1, ControllerKind::touch).ok, "zero rotation");
        check(!bg::shaft({{0, 1, 0}, {nan, 0, 0, 1}}, 0, ControllerKind::index).ok, "NaN rotation");
        check(!bg::shaft({{0, 1, 0}, {0, 0, 0, 2}}, 0, ControllerKind::touch).ok, "not a unit rotation");
        check(!bg::shaft({{0, 1, 0}, {}}, 0, ControllerKind::touch, nan).ok, "NaN length");
        // The fallback and what still uses the hand's aim are unchanged: 0.0.62's shaft .12 / .45, the
        // throw (along the aim from the hand) and its catch; one baton per hand.
        Vec3 g{}, tp{};
        hero_modes::batonShaft({0, 1.2f, -.2f}, {0, 0, -1}, g, tp);
        check(length(g - Vec3{0, 1.2f, -.08f}) < 1e-5f && length(tp - Vec3{0, 1.2f, -.65f}) < 1e-5f, "0.0.62's fallback shaft moved");
        hero_modes::Baton b;
        const Vec3 hand{0, 1.2f, 0};
        b.update(1.f / 90, true, hand, {0, 0, -1}, nullptr, 0, -1);
        check(!b.inHandNow() && b.throws == 1, "the trigger no longer throws");
        for (int f = 0; f < 90 * 4 && !b.inHandNow(); ++f)
            b.update(1.f / 90, false, hand, {0, 0, -1}, nullptr, 0, -1);
        check(b.inHandNow() && b.catches == 1, "the baton did not come back to the hand");
    });
    test("Version 0.0.7: PUNISHER GUN GRIP - in the palm from the grip pose: barrel on the forearm and the aim ray, mirrored, per controller", [] {
        // The user, 26 Oct: "make sure punishers gun sit right in his hand". 0.0.62 drew a held gun along
        // the hand's AIM (AIM AXIS HAND: the grip's -Y, 30 deg below the forearm on Touch), upright to the
        // world, its origin (the grip's front) on the grip point.
        using namespace spidy::hero007;
        namespace gg = spidy::gun_grip;
        namespace bg = spidy::baton_grip;
        const auto deg = [](Vec3 a, Vec3 b) {
            return std::acos(std::clamp(dot(normalized(a), normalized(b)), -1.f, 1.f)) * 180.f / 3.14159265f;
        };
        const auto mirror = [](Vec3 v) { return Vec3{-v.x, v.y, v.z}; };
        // Per controller, grip-local: the barrel is the forearm (Touch 30 deg off the grip's -Y, Index 15),
        // the top toward the thumb (-Z), square to it, nothing along the palm's normal.
        check(std::abs(deg(bg::localForearm(ControllerKind::touch), bg::localForearm(ControllerKind::index)) - 15.f) < .01f,
              "Touch and Index barrels differ by the handles' 15 deg");
        // Meta's aim pose (and Virtual Desktop's): the hand (the grip's -Y) turned 30 deg toward the thumb (tracking.hpp).
        check(deg(bg::localForearm(ControllerKind::touch), bg::localDirection(30.f)) < .01f, "Touch: the barrel is the aim ray");
        for (const ControllerKind k : {ControllerKind::touch, ControllerKind::index, ControllerKind::frame}) {
            check(std::abs(dot(bg::localForearm(k), gg::localUp(k))) < 1e-5f && gg::localUp(k).z < -.8f &&
                      std::abs(gg::localUp(k).x) < 1e-6f, "the top square to the barrel, toward the thumb");
        }
        // Each look's grip middle sits under the slide, behind the trigger (the web high on the backstrap,
        // the index finger along the guard).
        for (const bool model : {false, true})
            for (const gg::Weapon w : {gg::pistol, gg::sawedOff}) {
                const auto p = gg::palmPoint(w, model);
                check(p.forward < 0 && p.forward > -.06f && p.up < 0 && p.up > -.04f, "a grip middle off the look's grip");
            }
        check(gg::muzzleFromPalm(gg::pistol).forward > .15f && gg::muzzleFromPalm(gg::sawedOff).forward > .35f &&
                  gg::muzzleFromPalm(gg::pistol).up > .05f, "the muzzle ahead of and above the hand");
        // From a grip pose: the grip point, the barrel along the forearm, mirrored left / right.
        const Quat turns[] = {Quat{}, Quat::around({0, 1, 0}, .7f), Quat::around({1, .3f, -.2f}, -1.1f), Quat::around({.2f, -1, .5f}, 2.9f)};
        for (const Quat& q : turns)
            for (const ControllerKind k : {ControllerKind::touch, ControllerKind::index}) {
                const Pose right{{.2f, 1.3f, -.4f}, q}, left{mirror(right.position), {q.x, -q.y, -q.z, q.w}};
                const auto r = gg::held(right, 1, k), l = gg::held(left, 0, k);
                check(r.ok && l.ok, "a good pose holds a gun");
                check(length(r.at - right.position) < 1e-6f, "the gun's grip is not on the grip point");
                check(deg(r.forward, q.rotate(bg::localForearm(k))) < .05f, "the barrel is off the forearm");
                check(deg(r.up, q.rotate({0, 0, -1})) < 31.f, "the top is not toward the thumb");
                check(length(l.forward - mirror(r.forward)) < 1e-4f && length(l.up - mirror(r.up)) < 1e-4f &&
                          length(l.at - mirror(r.at)) < 1e-5f, "left and right are not mirror images");
                const Vec3 mz = gg::from(r, gg::muzzleFromPalm(gg::pistol)), ml = gg::from(l, gg::muzzleFromPalm(gg::pistol));
                check(length(ml - mirror(mz)) < 1e-4f, "the muzzles are not mirrored");
            }
        const float nan = std::numeric_limits<float>::quiet_NaN();
        check(!gg::held({{nan, 1, 0}, {}}, 1, ControllerKind::touch).ok && !gg::held({{0, 1, 0}, {0, 0, 0, 0}}, 0, ControllerKind::touch).ok &&
                  !gg::held({{0, 1, 0}, {nan, 0, 0, 1}}, 0, ControllerKind::index).ok, "a bad pose holds nothing");
        // In play: draw both pistols at the hips, hold them out, shoot along the barrel (not the aim).
        Play g;
        PlayInput in{};
        in.dt = 1 / 90.f;
        in.play = true;
        in.hero = spidy::hero_modes::punisher;
        in.head = {{0, 1.7f, 0}, {}};
        in.reload = reloadAuto;
        const Vec3 rightHip{.25f, 1.0f, 0}, leftHip{-.25f, 1.0f, 0};
        // A right grip whose forearm points straight ahead (-Z world), thumb up (Touch: grip +Y 30 deg off the arm).
        const Quat rq = Quat::around({1, 0, 0}, (90.f - 30.f) * 3.14159265f / 180.f);
        const Quat lq{rq.x, -rq.y, -rq.z, rq.w};
        check(deg(rq.rotate(bg::localForearm(ControllerKind::touch)), {0, 0, -1}) < .05f, "the test pose aims ahead");
        // Version 0.0.72 AIMED GUNS: the barrel and the shot follow the aim ray (the user's 0.0.71 videos: "guns aimed
        // correctly"), the grip stays in the palm from the grip pose.
        Vec3 aimWay{0, 0, -1};
        const auto hands = [&](Vec3 l, float sl, Vec3 r, float sr, float trig, bool gunPose) {
            in.hands[0] = {l, aimWay, true, trig, sl, false};
            in.hands[1] = {r, aimWay, true, trig, sr, false};
            const gg::Held hl = gg::held({l, lq}, 0, ControllerKind::touch), hr = gg::held({r, rq}, 1, ControllerKind::touch);
            in.hands[0].gunOk = gunPose && hl.ok;
            in.hands[0].gunAt = hl.at;
            in.hands[0].gunForward = hl.forward;
            in.hands[0].gunUp = hl.up;
            in.hands[1].gunOk = gunPose && hr.ok;
            in.hands[1].gunAt = hr.at;
            in.hands[1].gunForward = hr.forward;
            in.hands[1].gunUp = hr.up;
            PlayOutput o;
            g.holsterStep(in, o);
            g.step(in, o);
            return o;
        };
        hands(leftHip, 1, rightHip, 1, 0, true);
        const Vec3 outL{-.2f, 1.4f, -.4f}, outR{.2f, 1.4f, -.4f};
        hands(outL, 1, outR, 1, 0, true);
        Draw d;
        g.draw(d, Pose{}, in, 0);
        check(d.held[0].look == lookPistol && d.held[1].look == lookPistol && d.held[0].palm && d.held[1].palm, "both pistols held in the palm");
        check(length(d.held[1].at - outR) < 1e-5f && deg(d.held[1].forward, {0, 0, -1}) < .1f && deg(d.held[1].up, {0, 1, 0}) < .1f,
              "the right pistol: the grip in the palm, the barrel ahead along the aim, upright with the thumb");
        check(length(d.held[0].at - mirror(d.held[1].at)) < 1e-5f && length(d.held[0].forward - mirror(d.held[1].forward)) < 1e-4f,
              "the left pistol mirrors the right");
        const spidy::hero_modes::BatonEnemy foe[1] = {{77, {.2f, 1.4f + gg::muzzleFromPalm(gg::pistol).up, -6.f}}};
        in.list = foe;
        in.count = 1;
        uint32_t blows = 0;
        const uint64_t shotsWere = g.shots;
        for (int f = 0; f < 6; ++f)
            blows += hands(outL, 1, outR, 1, f % 2 ? 0.f : 1.f, true).blowCount;
        check(g.shots > shotsWere && blows > 0, "a shot along the barrel misses the enemy it points at");
        g.draw(d, Pose{}, in, 0);
        bool caseNear = false;
        for (uint32_t k = 0; k < d.shells; ++k)
            caseNear = caseNear || length(d.shellAt[k] - (outR + Vec3{0, .07f, -.05f})) < .15f || length(d.shellAt[k] - (outL + Vec3{0, .07f, -.05f})) < .15f;
        check(d.shells > 0 && caseNear, "the cases leave the ejection port");
        // The aim turned to the floor: the barrel turns with it, the grip stays in the palm.
        aimWay = {0, -1, 0};
        hands(outL, 1, outR, 1, 0, true);
        g.draw(d, Pose{}, in, 0);
        check(d.held[1].palm && length(d.held[1].at - outR) < 1e-5f && deg(d.held[1].forward, {0, -1, 0}) < .1f &&
                  std::fabs(dot(d.held[1].up, d.held[1].forward)) < 1e-3f, "the barrel did not follow the aim");
        // No usable grip pose: 0.0.62's placement along the aim, upright, not palm; still one pistol per hand.
        hands(outL, 1, outR, 1, 0, false);
        g.draw(d, Pose{}, in, 0);
        check(d.held[1].look == lookPistol && !d.held[1].palm && length(d.held[1].at - outR) < 1e-5f &&
                  deg(d.held[1].forward, {0, -1, 0}) < .1f, "the fallback moved");
        // Both looks draw a palm gun, the sawed-off broken open too (its barrels on their hinge), nothing insane.
        for (const uint32_t look : {static_cast<uint32_t>(lookPistol), static_cast<uint32_t>(lookSawedOff), static_cast<uint32_t>(lookSawedOffOpen)}) {
            Draw one{};
            one.any = true;
            one.held[1] = {};
            one.held[1].look = look;
            one.held[1].at = outR;
            one.held[1].forward = {0, 0, -1};
            one.held[1].up = {0, 1, 0};
            one.held[1].palm = true;
            std::vector<spidy::Vertex> v;
            appendHero007(v, one, {}, {0, 1.62f, 0}, .002f);
            check(!v.empty(), "a palm gun drew nothing");
            for (const auto& x : v)
                check(finite(x.position), "a palm gun drew a NaN");
        }
    });
    test("Version 0.0.7: CAPTAIN AMERICA SHIELD ARM RIGHT (default): no clash with the right hand's other inputs", [] {
        using namespace spidy::hero007;
        // The user, 26 Oct: "it should be on the right arm... or toggable between arms". The right hand
        // draws from the back only at the holster, never while it is on a web or a wall (web-zip, climb),
        // its grip anywhere else is never claimed, the left hand is left alone, and another hero's
        // one-per-hand racks are unchanged with SHIELD ARM RIGHT set.
        const Vec3 backR{.1f, 1.5f, .25f}, backL{-.1f, 1.5f, .25f}, ahead{.3f, 1.3f, -.5f}, aheadL{-.3f, 1.3f, -.5f};
        const Vec3 rightHip{.25f, 1.0f, 0};
        const auto frames = [](Play& p, PlayInput& in, int n) {
            PlayOutput o;
            for (int f = 0; f < n; ++f) {
                o = {};
                p.holsterStep(in, o);
            }
            return o;
        };
        PlayInput in;
        in.dt = 1 / 90.f;
        in.play = true;
        in.hero = spidy::hero_modes::captainAmerica;
        in.head = {{0, 1.7f, 0}, {}};
        check(in.shieldArm == spidy::captain::armRight, "SHIELD ARM RIGHT by default");
        // On a web or a wall (busy): the right grip at the back draws nothing and is not claimed.
        Play busy;
        in.hands[0] = {aheadL, {0, 0, -1}, true, 0, 0, false, false};
        in.hands[1] = {backR, {0, 0, -1}, true, 0, 0, true, false};
        frames(busy, in, 1);
        in.hands[1].squeeze = 1;
        PlayOutput o = frames(busy, in, 3);
        check(busy.shieldRack.heldIn(1) < 0 && !(o.claimed & 2), "a busy right hand (web-zip, climb) never draws the shield");
        // The right grip in front (where web-zip and climb grab): never claimed.
        Play front;
        in.hands[1] = {ahead, {0, 0, -1}, true, 0, 0, false, false};
        frames(front, in, 1);
        in.hands[1].squeeze = 1;
        o = frames(front, in, 3);
        check(front.shieldRack.heldIn(1) < 0 && o.claimed == 0, "the right grip away from the back stays the game's");
        // The left hand at the back: not the shield's (it is free for its own grips).
        Play left;
        in.hands[1] = {ahead, {0, 0, -1}, true, 0, 0, false, false};
        in.hands[0] = {backL, {0, 0, -1}, true, 0, 0, false, false};
        frames(left, in, 1);
        in.hands[0].squeeze = 1;
        o = frames(left, in, 3);
        check(left.shieldRack.heldIn(0) < 0 && o.claimed == 0, "RIGHT: the left hand at the back takes nothing");
        // The right hand draws it at the back, and only there.
        Play ok;
        in.hands[0] = {aheadL, {0, 0, -1}, true, 0, 0, false, false};
        in.hands[1] = {backR, {0, 0, -1}, true, 0, 0, false, false};
        frames(ok, in, 1);
        in.hands[1].squeeze = 1;
        o = frames(ok, in, 3);
        check(ok.shieldRack.heldIn(1) >= 0 && (o.claimed & 2) && !(o.claimed & 1), "RIGHT: the right hand draws it at the back");
        // PUNISHER with SHIELD ARM RIGHT set: his right pistol is drawn by the right hand as before, no shield.
        Play gun;
        in.hero = spidy::hero_modes::punisher;
        in.hands[0] = {aheadL, {0, 0, -1}, true, 0, 0, false, false};
        in.hands[1] = {rightHip, {0, 0, -1}, true, 0, 0, false, false};
        frames(gun, in, 1);
        in.hands[1].squeeze = 1;
        o = frames(gun, in, 3);
        check(gun.guns.heldIn(1) >= 0 && (o.claimed & 2) && gun.shieldRack.heldIn(1) < 0 && !gun.shieldOnArm(),
              "PUNISHER: the right pistol is the right hand's, no shield");
        // DAREDEVIL BATON HOLSTERS with SHIELD ARM RIGHT set: one baton per hand as before.
        Play dd;
        in.hero = spidy::hero_modes::daredevil;
        in.batonHolsters = true;
        in.hands[1] = {backR, {0, 0, -1}, true, 0, 0, false, false};
        frames(dd, in, 1);
        in.hands[1].squeeze = 1;
        o = frames(dd, in, 3);
        check(dd.batons.heldIn(1) >= 0 && dd.shieldRack.heldIn(1) < 0, "DAREDEVIL: the right back baton, no shield");
    });
    test("Version 0.0.7: CAPTAIN AMERICA shield looks keep their budget", [] {
        using namespace spidy::hero007;
        const Vec3 viewer{0, 1.6f, 0};
        const float px = .0015f;
        for (uint32_t look : {uint32_t(lookShield), uint32_t(lookShieldSpin)})
            for (uint32_t side = 0; side < 2; ++side)
                for (const Vec3 eye : {viewer, Vec3{0, 1.6f, -2}}) {
                    std::vector<Vertex> v;
                    Item it{look, {0, 1.3f, -.6f}, {0, 0, 1}, {0, 1, 0}, 1.f, 0, side};
                    appendItem(v, it, eye, px);
                    check(!v.empty() && v.size() <= budget::shield, "shield in budget: " + std::to_string(v.size()));
                }
        std::vector<Vertex> v;
        Item bad{lookShield, {NAN, 0, 0}};
        appendItem(v, bad, viewer, px);
        check(v.empty(), "a NaN shield draws nothing");
        Item flat{lookShield, {0, 1.3f, -.6f}, {0, 0, 0}, {0, 0, 0}};
        appendItem(v, flat, viewer, px);
        check(v.size() <= budget::shield, "a degenerate frame never overruns");
        namespace mm = spidy::mesh_model;
        const std::string real = "build/h7out/Models/";
        if (std::filesystem::exists(real + "Shield/scene.glb")) {
            mm::Library lib;
            check(lib.load(mm::slotShield, real) == mm::loaded, "the converted shield loads");
            for (uint32_t side = 0; side < 2; ++side) {
                v.clear();
                Item it{lookShieldSpin, {0, 1.3f, -.6f}, {0, 0, 1}, {0, 1, 0}, .7f, 0, side};
                check(appendShieldModel(v, it, *lib.model(mm::slotShield), viewer) && !v.empty() && v.size() <= budget::model,
                      "the shield model in budget: " + std::to_string(v.size()));
            }
        }
    });
    test("Version 0.0.72: TEST BUILD NOTICE - the exact text, after calibration, once a session, OK by poke or aimed trigger", [] {
        namespace tn = spidy::test_notice;
        check(tn::text == "You are on the latest test version, please be aware that some features do not work or are unfinished, "
                          "revert to 0.0.63 if unplayable and report issues in my discord server linked on the launcher",
              "the user's text word for word");
        check(tn::testBuild, "the 0.0.73 private test builds build with HERO_TEST_BUILD ON (the test notice shows)");
        for (char c : tn::text)
            check(c == ' ' || drawable(c), std::string("the font draws '") + c + "'");
        const auto ls = tn::lines(tn::text, tn::textHeight, tn::width - 2 * tn::margin);
        std::string joined;
        for (const auto& l : ls) {
            check(textWidth(l, tn::textHeight) <= tn::width - 2 * tn::margin + 1e-4f, "each line fits");
            joined += (joined.empty() ? "" : " ") + std::string(l);
        }
        check(joined == tn::text, "the lines put together are the text");
        check(ls.size() >= 4 && (tn::height / 2 - tn::margin) - ls.size() * (tn::textHeight + tn::lineGap) > tn::buttonY + tn::buttonHeight / 2,
              "the lines stay above the OK button: " + std::to_string(ls.size()));
        // Play, standing at 1.7 m looking down -z.
        const auto base = [](double t) {
            tn::Input in;
            in.enabled = true;
            in.seconds = t;
            in.immersive = true;
            in.head = {{0, 1.7f, 0}, {}};
            for (auto& h : in.hands) {
                h.tracked = true;
                h.grip = h.aim = {{.2f, 1.1f, -.3f}, Quat::around({1, 0, 0}, -1.2f)}; // pointing at the floor
            }
            return in;
        };
        {
            tn::Notice n; // a calibration due and then running: nothing until it closes
            auto in = base(0);
            in.calibrationDue = true;
            for (double t = 0; t < 5; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::waiting, "waits while a calibration is due");
            in.calibrationDue = false;
            in.calibrating = true;
            in.hands[0].trigger = in.hands[1].trigger = 1; // both triggers held for the T-pose
            for (double t = 5; t < 9; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::waiting, "waits while the calibration shows");
            in.calibrating = false;
            for (double t = 9; t < 9.95; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::waiting, "not before play has shown a second");
            for (double t = 9.95; t < 10.6; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::shown, "shows right after the calibration closes");
            check(std::abs(n.panel().position.z + 1.3f) < .01f && std::abs(n.panel().position.y - 1.6f) < .01f,
                  "1.3 m ahead, just under the eyes");
            for (double t = 10.6; t < 13; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::shown, "the triggers held from the calibration do not dismiss it");
            in.hands[0].trigger = in.hands[1].trigger = 0;
            in.seconds = 13.1;
            n.update(in);
            in.hands[0].trigger = 1;
            in.seconds = 13.2;
            n.update(in);
            check(n.state() == tn::State::shown, "a pull aimed at the floor is play, not OK");
            in.hands[0].trigger = 0;
            in.hands[0].aim = {{0, 1.385f, -.4f}, Quat{}}; // aim straight at the button
            in.seconds = 13.3;
            n.update(in);
            check(n.hover(), "aiming at OK lights it");
            in.hands[0].trigger = 1;
            in.seconds = 13.4;
            n.update(in);
            check(n.state() == tn::State::gone && n.ended() == tn::Ended::triggered, "an aimed pull is OK");
            for (double t = 13.5; t < 15; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(!n.visible(), "fades out");
            // A second calibration in the same session: never again.
            in.calibrating = true;
            n.update(in);
            in.calibrating = false;
            for (double t = 15; t < 40; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::gone, "once a session");
        }
        {
            tn::Notice n; // no calibration this session: after play has shown a second; a poke is OK
            auto in = base(0);
            for (double t = 0; t < 1.5; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::shown, "no calibration due: shows once play has shown");
            in.hands[1].grip.position = n.buttonCentre() + Vec3{0, 0, .2f};
            in.seconds = 2;
            n.update(in);
            check(n.state() == tn::State::shown, "a hand short of the button does nothing");
            in.hands[1].grip.position = n.buttonCentre() + Vec3{.02f, 0, .01f};
            in.seconds = 2.1;
            n.update(in);
            check(n.state() == tn::State::gone && n.ended() == tn::Ended::poked, "a poke is OK");
        }
        {
            tn::Notice n; // a poke in the first moment does not count (a hand already there)
            auto in = base(0);
            for (double t = 0; t < 1.1; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::shown, "shown");
            in.hands[1].grip.position = n.buttonCentre();
            in.seconds = 1.2;
            n.update(in);
            check(n.state() == tn::State::shown, "not armed in the first .75 s");
            for (double t = 1.2; t < 200; t += .2) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::gone && n.ended() == tn::Ended::timedOut, "a hand left in it: gone by itself, never stuck");
        }
        {
            tn::Notice n; // not a test build, or a bad head: nothing
            auto in = base(0);
            in.enabled = false;
            for (double t = 0; t < 5; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::waiting && !n.visible(), "a release build never shows it");
            in.enabled = true;
            in.head.position = {NAN, 0, 0};
            for (double t = 5; t < 9; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::waiting, "an untracked head: waits");
            in.immersive = false;
            in.head = {{0, 1.7f, 0}, {}};
            for (double t = 9; t < 12; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            check(n.state() == tn::State::waiting, "paused or flat screen: waits");
        }
        {
            tn::Notice n;
            auto in = base(0);
            for (double t = 0; t < 2; t += .1) {
                in.seconds = t;
                n.update(in);
            }
            const auto v = tn::view(n, {{0, 0, 0}, {}});
            check(v.opacity > .99f, "faded in");
            std::vector<Vertex> out;
            tn::append(out, v);
            check(!out.empty() && out.size() < 24000, "draws, in one call's budget: " + std::to_string(out.size()));
            bool ok = true;
            for (const auto& x : out)
                ok &= finite(x.position) && x.alpha >= 0 && x.alpha <= 1;
            check(ok, "finite and in range");
            out.clear();
            tn::append(out, tn::View{1, false, {{NAN, 0, 0}, {}}});
            check(out.empty(), "a NaN panel draws nothing");
            tn::append(out, tn::View{});
            check(out.empty(), "opacity 0 draws nothing");
            check(tn::view(n, {{0, 0, 0}, {NAN, 0, 0, 1}}).opacity == 0, "a bad world pose: nothing");
        }
    });
    test("Build 7: THOR - the hammer thrown flies, hits, comes back and is caught; LIGHTNING BLAST; bolts seen; storm with no enemy", [] {
        using namespace hero072;
        const auto frame = [] {
            PlayIn in;
            in.dt = 1 / 72.f; // the user's test 6 headset rate
            in.play = true;
            in.hero = hero_modes::thor;
            in.head.position = {0, 1.7f, 0};
            for (auto& h : in.hands)
                h.tracked = true;
            in.hands[0].position = {-.25f, 1.2f, -.2f};
            in.hands[1].position = {.25f, 1.2f, -.2f};
            in.hands[1].aim = {0, 0, -1};
            return in;
        };
        BatonEnemy foes[1] = {{0x33, {.3f, 1.4f, -6.f}}};
        Play play;
        PlayIn in = frame();
        in.list = foes;
        in.count = 1;
        PlayOut out;
        play.step(in, out);
        in.hands[1].position = {.2f, 1.6f, .1f};
        in.hands[1].grip = 1;
        play.step(in, out);
        check(play.hammerHeld, "the hammer drawn from the back");
        check(play.takeThorEvents() & Play::thorDrawn, "the draw not logged");
        // A forward swing (3.6 m/s), the grip let go just after the swing's peak (the hand already slowing).
        in.hands[1].position = {.25f, 1.45f, 0};
        play.step(in, out);
        for (int f = 0; f < 6; ++f) {
            in.hands[1].position.z -= .05f;
            out = PlayOut{};
            play.step(in, out);
        }
        in.hands[1].position.z -= .01f;
        in.hands[1].grip = 0;
        out = PlayOut{};
        play.step(in, out);
        check(play.throws == 1 && play.hammerInAir() && !play.hammerHeld, "a swing and let go did not throw the hammer");
        check(play.lastThrowSpeed >= throwSpeedLow && play.lastThrowSpeed <= throwSpeedHigh, "the throw's speed");
        check(out.look.hammer && !out.look.hammerSheathed, "the thrown hammer not drawn in the air");
        uint32_t hammerHits = 0, boltFrames = 0, frames = 0;
        bool movedAway = false;
        const float startZ = play.hammerAirAt().z;
        for (; frames < 200 && play.hammerInAir(); ++frames) {
            if (frames == 18)
                in.hands[1].grip = 1; // hold the grip for the catch (its press also recalls)
            out = PlayOut{};
            play.step(in, out);
            for (uint32_t k = 0; k < out.blowCount; ++k)
                hammerHits += out.blows[k].kind == kindHammer && out.blows[k].id == 0x33;
            boltFrames += out.look.bolts > 0;
            movedAway = movedAway || play.hammerAirAt().z < startZ - 2.f;
        }
        check(movedAway, "the hammer did not fly out");
        check(hammerHits == 1, "the thrown hammer did not hit the enemy in its way exactly once");
        check(boltFrames >= 20, "no lightning seen on the flying hammer / its hit");
        check(!play.hammerInAir() && play.hammerHeld, "the hammer did not come back into the held grip");
        const uint32_t ev = play.takeThorEvents();
        check((ev & Play::thorThrown) && (ev & Play::thorHammerHit) && (ev & Play::thorCaught), "the throw's events not logged");
        // LIGHTNING BLAST: the right trigger with the hammer in hand, at the enemy aimed at; its bolt lingers.
        in.hands[1].trigger = 1;
        out = PlayOut{};
        play.step(in, out);
        uint32_t bolts = 0, sounds = out.lightning[0] + out.lightning[1];
        for (uint32_t k = 0; k < out.blowCount; ++k)
            bolts += out.blows[k].kind == kindBolt && out.blows[k].id == 0x33;
        check(bolts >= 1 && sounds == 1, "the trigger's LIGHTNING BLAST did not strike the enemy with one sound");
        check(play.takeThorEvents() & Play::thorBlast, "the blast not logged");
        uint32_t seen = 0;
        for (int f = 0; f < 15; ++f) {
            out = PlayOut{};
            play.step(in, out); // trigger held: no second blast
            seen += out.look.bolts > 0;
            sounds += out.lightning[0] + out.lightning[1];
        }
        check(seen == 15 && sounds == 1, "the blast's bolt not seen for a fifth of a second, or it re-fired");
        in.hands[1].trigger = 0;
        // STORM with no enemy: the hammer up overhead (the controller tilted, as held), bolts from the sky.
        in.count = 0;
        in.hands[1].position = {.1f, 2.f, -.1f};
        in.hands[1].aim = {0, .7f, -.7f};
        uint32_t stormSounds = 0, skyFrames = 0;
        for (int f = 0; f < 200; ++f) {
            out = PlayOut{};
            play.step(in, out);
            stormSounds += out.lightning[0] + out.lightning[1];
            skyFrames += out.look.bolts >= 3;
        }
        check(stormSounds == stormStrikes, "the storm's strikes with no enemy");
        check(skyFrames >= 20, "the storm's sky bolts not seen with no enemy");
        check(play.takeThorEvents() & Play::thorStorm, "the storm not logged");
        // A slow let go puts it back on the back: never thrown by accident.
        for (int f = 0; f < 30; ++f)
            play.step(in, out);
        in.hands[1].grip = 0;
        out = PlayOut{};
        play.step(in, out);
        check(!play.hammerHeld && !play.hammerInAir() && play.throws == 1, "a still let go threw the hammer");
        out = PlayOut{};
        play.step(in, out);
        check(out.look.hammerSheathed, "the hammer not back on the back");
        // Recall: thrown with nothing in its way, the grip pressed brings it back early.
        in.hands[1].position = {.2f, 1.6f, .1f};
        in.hands[1].grip = 1;
        play.step(in, out);
        in.hands[1].position = {.25f, 1.45f, 0};
        play.step(in, out);
        for (int f = 0; f < 6; ++f) {
            in.hands[1].position.z -= .05f;
            play.step(in, out);
        }
        in.hands[1].grip = 0;
        play.step(in, out);
        check(play.throws == 2 && play.hammerInAir(), "the second throw");
        for (int f = 0; f < 10; ++f)
            play.step(in, out);
        in.hands[1].grip = 1;
        play.step(in, out);
        check(play.takeThorEvents() & Play::thorRecalled, "the grip did not recall the hammer");
        int back = 0;
        while (play.hammerInAir() && back < 200) {
            play.step(in, out);
            ++back;
        }
        check(play.hammerHeld && back < 60, "the recalled hammer not caught within a second");
        check(Play::boltsSeenSeconds() >= .25f, "bolts last a moment");
    });
    test("Build 7: GREEN LANTERN - one hand up no longer takes him off (RingFlight gates FLY MODE's pose)", [] {
        using namespace hero072;
        const Vec3 head{0, 1.7f, 0};
        RingFlight rf;
        float lift = 0;
        uint32_t pose = 0;
        for (int f = 0; f < 60; ++f)
            pose = rf.gate(1 / 72.f, false, 1u, 1.f, head, {-.25f, 1.2f, -.2f}, {.1f, 2.1f, 0}, lift);
        check(pose == 0u, "one hand up took GREEN LANTERN off");
        for (int f = 0; f < 60; ++f)
            pose = rf.gate(1 / 72.f, false, 1u, 1.f, head, {-.15f, 2.15f, 0}, {.15f, 2.15f, 0}, lift);
        check(pose == 1u && lift == 1.f, "both arms straight up did not take off");
        check(rf.gate(1 / 72.f, true, 2u, 0.f, head, {}, {}, lift) == 2u, "in the air the poses do not steer");
    });
